#!/usr/bin/env python3
"""Primary reference evaluator for the ACCORD-02E4R5R4 declarative candidate.

The candidate is data: objects are loaded only by explicit bootstrap entrypoints and
registry-declared paths, then all procedure assertions are interpreted from the
closed primitive/procedure registries. External trust, profile schema bytes, profile
JSON, frozen content, accepted-source bytes, and their expected digests are supplied
by the caller on every run. This is a primary evaluator, not an independent verifier.

Every pre-execution failure is selected and reported from the verifier's own protocol
commitment of the R5R25 TOTAL pre-execution failure model (family, condition, stage,
precedence, code, diagnostic, witness derivations); see the commitment block below.
"""
