class GateError(Exception):
    def __init__(self, code: str, witness: Mapping[str, Any] | None = None, detail: str = ""):
        super().__init__(detail or code)
        self.code = code
        self.witness = dict(witness or {})
        self.detail = detail or code

class DuplicateJSONName(ValueError):
    pass

class ExpressionError(Exception):
    def __init__(self, error_class: str, pointer: str = "", detail: str = ""):
        super().__init__(detail or error_class)
        self.error_class = error_class
        self.pointer = pointer
        self.detail = detail or error_class

@dataclass(frozen=True)
class ResolvedObject:
    reference: Mapping[str, str]
    registration: Mapping[str, Any]
    content: Any
    raw_bytes: bytes
    origin: str
    schema: Any = None
    requested_ref: Mapping[str, str] | None = None

    def json_view(self) -> dict[str, Any]:
        if self.origin not in ("CANDIDATE_UNIVERSE", "BOUND_SOURCE_UNIVERSE"):
            raise ExpressionError("INELIGIBLE_OBJECT", detail="object is outside the verification universe")
        integrity = self.registration["integrity"]
        mode = integrity["mode"]
        integrity_source = {
            "SEMANTIC_JSON_CONTENT": "VALIDATED_REGISTRY_ENTRY",
            "SELF_DIGEST": "PACKAGE_SELF_DIGEST",
            "PACKAGE_PINNED_BOOTSTRAP": "PACKAGE_REGISTRY_SEMANTIC_PIN",
            "DUAL_ACCEPTED_SOURCE": "EXTERNAL_ACCEPTANCE_PROFILE",
        }[mode]
        return {
            "kind": self.reference["kind"],
            "id": self.reference["id"],
            "version": self.reference["version"],
            "ref": dict(self.requested_ref or self.reference),
            "reference": dict(self.reference),
            "path": self.registration["path"],
            "status": self.registration["status"],
            "classification": self.registration["classification"],
            "roles": list(self.registration["roles"]),
            "schema_ref": self.registration.get("schema_ref"),
            "content": self.content,
            "origin": self.origin,
            "integrity": integrity,
            "integrity_source": integrity_source,
            "members": list(self.registration.get("members", [])),
            "raw_content_base64": base64.b64encode(self.raw_bytes).decode("ascii"),
        }

class TypedResolvedJSON(dict):
    """Exact public JSON payload with RESOLVED_OBJECT provenance from an AST producer."""

@dataclass(frozen=True)
class BoundArgumentValue:
    """A declared RULE_BINDING: content-root JSON plus preserved object bytes."""
    object: ResolvedObject

@dataclass(frozen=True)
class VerificationUniverse:
    objects: tuple[ResolvedObject, ...]

    def json_view(self) -> dict[str, Any]:
        return {"objects":[o.json_view() for o in self.objects]}

    def resolve(self, reference: Any) -> ResolvedObject:
        if not isinstance(reference, dict) or set(reference) - {"kind", "id", "version", "member_id"}:
            raise ExpressionError("INVALID_TYPED_REFERENCE", detail="typed reference must be a closed object")
        if not {"kind", "id", "version"}.issubset(reference) or any(not isinstance(reference[k], str) or not reference[k] for k in ("kind", "id", "version")):
            raise ExpressionError("INVALID_TYPED_REFERENCE", detail="typed reference requires nonempty kind/id/version")
        if "member_id" in reference and (not isinstance(reference["member_id"], str) or not reference["member_id"]):
            raise ExpressionError("INVALID_TYPED_REFERENCE", detail="member_id must be a nonempty string")
        matches = [o for o in self.objects if all(o.reference.get(k) == reference[k] for k in ("kind", "id", "version"))]
        if not matches:
            raise ExpressionError("RESOLUTION_NOT_FOUND", detail=f"no object for {reference!r}")
        if len(matches) != 1:
            raise ExpressionError("RESOLUTION_AMBIGUOUS", detail=f"multiple objects for {reference!r}")
        result = matches[0]
        member = reference.get("member_id")
        if member is not None:
            matches = result.registration.get("members", []).count(member)
            if matches == 0:
                raise ExpressionError("MEMBER_NOT_FOUND", detail=f"member {member!r} not registered for {reference!r}")
            if matches != 1:
                raise ExpressionError("RESOLUTION_AMBIGUOUS", detail=f"member {member!r} is duplicated for {reference!r}")
        return ResolvedObject(result.reference, result.registration, result.content,
                              result.raw_bytes, result.origin, result.schema, dict(reference))

def reject_duplicate_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for key, value in pairs:
        if key in out:
            raise DuplicateJSONName(f"duplicate JSON object member {key!r}")
        out[key] = value
    return out

def reject_constant(value: str) -> None:
    raise ValueError(f"non-JSON numeric constant {value}")

def exact_json_integer(token: str) -> int:
    negative = token.startswith("-")
    digits = token[1:] if negative else token
    value = 0
    for offset in range(0, len(digits), 9):
        chunk = digits[offset:offset + 9]
        value = value * (10 ** len(chunk)) + int(chunk)
    return -value if negative else value

def jcs(value: Any) -> bytes:
    if isinstance(value, BoundArgumentValue):
        value = value.object.content
    elif isinstance(value, ResolvedObject):
        value = value.json_view()
    elif isinstance(value, VerificationUniverse):
        value = value.json_view()
    try:
        # Use the pinned library for every scalar (including its exact number and string
        # encoding), and an explicit stack for containers. This is the same RFC8785
        # traversal without Python recursion in the nesting depth of candidate JSON.
        output = bytearray()
        pending: list[tuple[str, Any]] = [("value", value)]
        while pending:
            action, item = pending.pop()
            if action == "raw":
                output.extend(item)
                continue
            if isinstance(item, dict):
                keys = sorted(item, key=_utf16_key)
                pending.append(("raw", b"}"))
                for index in range(len(keys) - 1, -1, -1):
                    key = keys[index]
                    pending.append(("value", item[key]))
                    pending.append(("raw", b":"))
                    pending.append(("value", key))
                    if index:
                        pending.append(("raw", b","))
                pending.append(("raw", b"{"))
            elif isinstance(item, (list, tuple)):
                pending.append(("raw", b"]"))
                for index in range(len(item) - 1, -1, -1):
                    pending.append(("value", item[index]))
                    if index:
                        pending.append(("raw", b","))
                pending.append(("raw", b"["))
            else:
                if isinstance(item, decimal.Decimal):
                    if not item.is_finite():
                        raise ValueError("nonfinite JSON number")
                    item = float(item)
                    if not math.isfinite(item):
                        raise ValueError("JSON number outside RFC8785 range")
                output.extend(rfc8785.dumps(item))
        return bytes(output)
    except Exception as exc:
        raise ExpressionError("OUTSIDE_I_JSON_DOMAIN", detail=str(exc)) from exc

def sha256(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()

def git_blob(raw: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(raw)).encode("ascii") + b"\0" + raw).hexdigest()

def identity_tuple(ref: Mapping[str, Any]) -> tuple[str, str, str]:
    return (str(ref.get("kind", "")), str(ref.get("id", "")), str(ref.get("version", "")))

def identity_utf16_key(ref: Mapping[str, Any]) -> tuple[bytes, bytes, bytes]:
    return tuple(part.encode("utf-16-be") for part in identity_tuple(ref))

def identity_object(ref: Mapping[str, Any], digest: str | None = None) -> dict[str, Any]:
    out = {"kind": ref.get("kind", ""), "id": ref.get("id", ""), "version": ref.get("version", "")}
    if digest is not None:
        out["digest"] = digest
    return out

def parse_pointer(pointer: str) -> list[str]:
    if not isinstance(pointer, str):
        raise ExpressionError("INVALID_POINTER", detail="pointer is not a string")
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ExpressionError("INVALID_POINTER", pointer, "RFC6901 pointer must be empty or start with /")
    tokens: list[str] = []
    for raw in pointer[1:].split("/"):
        if re.search(r"~(?![01])", raw):
            raise ExpressionError("INVALID_POINTER", pointer, "invalid RFC6901 escape")
        tokens.append(raw.replace("~1", "/").replace("~0", "~"))
    return tokens

def pointer_from_tokens(tokens: Sequence[str]) -> str:
    return "" if not tokens else "/" + "/".join(str(x).replace("~", "~0").replace("/", "~1") for x in tokens)

def _json_view(value: Any) -> Any:
    if isinstance(value, BoundArgumentValue):
        return value.object.content
    if isinstance(value, VerificationUniverse):
        return value.json_view()
    return value.json_view() if isinstance(value, ResolvedObject) else value

def _erase_resolved_type(value: Any) -> Any:
    if isinstance(value, (BoundArgumentValue, VerificationUniverse, ResolvedObject)):
        value = _json_view(value)
    if isinstance(value, TypedResolvedJSON):
        return dict(value)
    if isinstance(value, list):
        if any(isinstance(item, (TypedResolvedJSON, ResolvedObject)) for item in value):
            return [_erase_resolved_type(item) for item in value]
        return value
    return value

def get_pointer(value: Any, pointer: str) -> Any:
    tokens = parse_pointer(pointer)
    current = _json_view(value)
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise ExpressionError("MISSING_PATH", pointer, f"missing object key {token!r}")
            current = current[token]
        elif isinstance(current, list):
            if token == "-" or not re.fullmatch(r"0|[1-9][0-9]*", token):
                raise ExpressionError("INVALID_ARRAY_INDEX", pointer, f"invalid array index {token!r}")
            index = int(token)
            if index >= len(current):
                raise ExpressionError("MISSING_PATH", pointer, f"array index {index} out of range")
            current = current[index]
        else:
            raise ExpressionError("MISSING_PATH", pointer, f"cannot traverse {type(current).__name__}")
    return current

def delete_pointer(value: Any, pointer: str) -> None:
    tokens = parse_pointer(pointer)
    if not tokens:
        raise ExpressionError("INVALID_EXCLUSION_POINTER", pointer, "cannot exclude the document root")
    parent = value
    for token in tokens[:-1]:
        if isinstance(parent, dict) and token in parent:
            parent = parent[token]
        elif isinstance(parent, list) and token.isdigit() and str(int(token)) == token and int(token) < len(parent):
            parent = parent[int(token)]
        else:
            raise ExpressionError("INVALID_EXCLUSION_POINTER", pointer, "exclusion parent is missing")
    last = tokens[-1]
    if isinstance(parent, dict) and last in parent:
        del parent[last]
    elif isinstance(parent, list) and last.isdigit() and str(int(last)) == last and int(last) < len(parent):
        del parent[int(last)]
    else:
        raise ExpressionError("INVALID_EXCLUSION_POINTER", pointer, "exclusion target is missing")

def _all_pointers(value: Any) -> Iterator[str]:
    if isinstance(value, dict):
        for k, v in value.items():
            yield from _all_pointers(k)
            yield from _all_pointers(v)
    elif isinstance(value, list):
        for item in value:
            yield from _all_pointers(item)

def check_local_schema_refs(schema: Any, here: str = "", root: Any = None) -> None:
    """Require every $ref/$dynamicRef to resolve as a local RFC6901 fragment.

    Depth-first, document-order walk with an explicit LIFO stack (children pushed reversed): the first offending member
    in the walk order is reported at the same location as before, and no Python call-stack depth is consumed per
    nesting level of the schema value."""
    if root is None:
        root = schema
    pending: list[tuple[Any, str]] = [(schema, here)]
    while pending:
        schema, here = pending.pop()
        if isinstance(schema, dict):
            for key in ("$ref", "$dynamicRef"):
                if key not in schema:
                    continue
                reference = schema[key]
                if not isinstance(reference, str) or not reference.startswith("#"):
                    raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", here, f"nonlocal or malformed schema reference {reference!r}")
                fragment = reference[1:]
                if re.search(r"%(?![0-9A-Fa-f]{2})", fragment):
                    raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", here, f"malformed percent escape in schema reference {reference!r}")
                try:
                    decoded = urllib.parse.unquote(fragment, errors="strict")
                    if decoded == "":
                        target = root
                    elif decoded.startswith("/"):
                        target = get_pointer(root, decoded)
                    else:
                        raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", here, f"schema fragment is not an RFC6901 pointer: {reference!r}")
                except (UnicodeDecodeError, ExpressionError) as exc:
                    raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", here, f"schema reference {reference!r} does not resolve: {exc}") from exc
                if not isinstance(target, (dict, bool)):
                    raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", here, f"schema reference {reference!r} resolves to a non-schema value")
            # These JSON Schema keywords contain instance data, not subschemas.
            # A "$ref" inside a const value is an ordinary JSON member.
            children = [(value, here + "/" + str(key)) for key, value in schema.items()
                        if key not in ("const", "enum", "default", "examples")]
            pending.extend(reversed(children))
        elif isinstance(schema, list):
            pending.extend(reversed([(value, here + f"/{i}") for i, value in enumerate(schema)]))

def _validation_error_sort_key(error: Any) -> tuple[Any, ...]:
    absolute_path = tuple(map(str, getattr(error, "absolute_path", ())))
    absolute_schema_path = tuple(map(str, getattr(error, "absolute_schema_path", ())))
    return absolute_path, absolute_schema_path, str(getattr(error, "validator", "") or ""), str(getattr(error, "message", ""))

def _is_reference_resolution_error(exc: BaseException) -> bool:
    candidates = (
        getattr(jsonschema.exceptions, "_RefResolutionError", None),
        getattr(jsonschema.exceptions, "_WrappedReferencingError", None),
        getattr(referencing_exceptions, "Unresolvable", None),
        getattr(referencing_exceptions, "PointerToNowhere", None),
        getattr(referencing_exceptions, "NoSuchAnchor", None),
        getattr(referencing_exceptions, "NoSuchResource", None),
    )
    return any(isinstance(cls, type) and isinstance(exc, cls) for cls in candidates)

def schema_errors(schema: Any, instance: Any, mode: str) -> list[jsonschema.ValidationError]:
    if not isinstance(schema, dict):
        raise ExpressionError("MALFORMED_SCHEMA", detail="schema must be an object")
    if mode not in ("META_SCHEMA", "INSTANCE"):
        raise ExpressionError("INVALID_SCHEMA_MODE", detail=mode)
    try:
        schema_key = sha256(jcs(schema))
    except ExpressionError as exc:
        raise ExpressionError("MALFORMED_SCHEMA", detail=exc.detail) from exc
    validator = _SCHEMA_VALIDATOR_CACHE.get(schema_key)
    if validator is None:
        check_local_schema_refs(schema)
        if schema.get("$schema") != DIALECT:
            raise ExpressionError("UNSUPPORTED_DIALECT", detail=f"schema dialect must be {DIALECT}")
        try:
            _check_schema(schema)
            validator = jsonschema.Draft202012Validator(schema, format_checker=_DATE_TIME_FORMAT_CHECKER)
        except jsonschema.SchemaError as exc:
            raise ExpressionError("MALFORMED_SCHEMA", detail=str(exc)) from exc
        except Exception as exc:
            if _is_reference_resolution_error(exc):
                raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", detail=str(exc)) from exc
            raise
        _SCHEMA_VALIDATOR_CACHE[schema_key] = validator
    if mode == "META_SCHEMA":
        cache_key = (schema_key, schema_key, mode)
        cached = _SCHEMA_RESULT_CACHE.get(cache_key)
        if cached is None:
            meta_validator = _META_SCHEMA_VALIDATOR
            try:
                errors = list(meta_validator.iter_errors(schema))
            except Exception as exc:
                if _is_reference_resolution_error(exc):
                    raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", detail=str(exc)) from exc
                raise
            cached = tuple(_CachedValidationError(err.message, tuple(err.absolute_path), tuple(err.absolute_schema_path), err.validator)
                           for err in sorted(errors, key=_validation_error_sort_key))
            _bounded_cache_put(_SCHEMA_RESULT_CACHE, cache_key, cached)
        return list(cached)  # type: ignore[return-value]
    try:
        instance_key = sha256(jcs(instance))
    except ExpressionError:
        # JSON Schema input instances must be JSON values. Leave this uncached so the
        # validator reports the same type/domain diagnostic as the normative library.
        instance_key = None
    cache_key = (schema_key, instance_key, mode) if instance_key is not None else None
    cached = _SCHEMA_RESULT_CACHE.get(cache_key) if cache_key is not None else None
    if cached is None:
        try:
            errors = list(validator.iter_errors(instance))
        except Exception as exc:
            if _is_reference_resolution_error(exc):
                raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", detail=str(exc)) from exc
            raise
        cached = tuple(_CachedValidationError(err.message, tuple(err.absolute_path), tuple(err.absolute_schema_path), err.validator)
                       for err in sorted(errors, key=_validation_error_sort_key))
        if cache_key is not None:
            _bounded_cache_put(_SCHEMA_RESULT_CACHE, cache_key, cached)
    return list(cached)  # type: ignore[return-value]


# ---- format: date-time assertion (R5R29A-R2b) ----------------------------------------------------------------------
# metacontract:/runtime_representation/schema_format_assertion declares r5r4_format_assertion ASSERTED for `format: date-time`
# (Draft 2020-12 Validation sections 7.2 / 7.3.1 with the RFC 3339 date-time grammar) in every SCHEMA_VALIDATE op node under
# either mode and in every instance validated against a registered schema_ref (registration and eligibility); a silent no-op
# is not conforming and an implementation that cannot assert it must fail closed. The pinned library family ships no
# date-time checker, so the declared grammar is asserted here, independently (implementation_deficiency_note). ONLY the
# declared `date-time` format is asserted: every other `format` value stays annotation-only (it is absent from this checker).
# Grammar (RFC 3339 section 5.6 and Appendix A, ABNF DIGIT = %x30-39 only; section 5.7 date/time restrictions):
#   date-time = full-date "T" full-time    ("T" and "Z" may be lower case: standard_domain_semantics)
#   full-date = 4DIGIT "-" 2DIGIT "-" 2DIGIT   month 01-12, mday 01 .. days of that month and Gregorian year
#   full-time = partial-time time-offset; partial-time = HH ":" MM ":" SS ["." 1*DIGIT]   HH 00-23, MM 00-59, SS 00-60
#   time-offset = "Z" / ("+" / "-") HH ":" MM   (offset required; -00:00 is valid syntax)
# SS = 60 (leap second, section 5.7), R5R29A-R2c law metacontract:/runtime_representation/schema_format_assertion/
# standard_domain_semantics/leap_second_rule: the date-time and numeric offset are normalised to the UTC leap-second label
# (fraction preserved), and the string is a valid date-time only if the whole label YYYY-MM-DDT23:59:60Z (fraction removed) is
# listed in the registered leap-second table of the package under evaluation (_leap_second_labels: governed input, never a
# private copy and never refreshed). No literal string equality is involved: a fraction, an offset, or lower-case t / z do not
# change the label. A non-string instance is out of scope of the format (Validation section 7.1: format applies to strings
# only) and conforms.
_DATE_TIME_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})[Tt]([0-9]{2}):([0-9]{2}):([0-9]{2})(?:\.[0-9]+)?"
                           r"(?:[Zz]|([+-])([0-9]{2}):([0-9]{2}))")
_DAYS_IN_MONTH = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def _rfc3339_date_time(instance: Any) -> bool:
    if not isinstance(instance, str):
        return True
    match = _DATE_TIME_RE.fullmatch(instance)
    if match is None:
        return False
    year, month, day, hour, minute, second = (int(match.group(index)) for index in range(1, 7))
    if not 1 <= month <= 12:
        return False
    leap_year = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    if not 1 <= day <= _DAYS_IN_MONTH[month - 1] + (1 if month == 2 and leap_year else 0):
        return False
    if hour > 23 or minute > 59 or second > 60:
        return False
    offset_minutes = 0
    if match.group(7) is not None:
        offset_hour, offset_minute = int(match.group(8)), int(match.group(9))
        if offset_hour > 23 or offset_minute > 59:
            return False
        offset_minutes = (offset_hour * 60 + offset_minute) * (1 if match.group(7) == "+" else -1)
    if second == 60:
        day_shift, utc_minute_of_day = divmod(hour * 60 + minute - offset_minutes, 1440)
        if utc_minute_of_day != 23 * 60 + 59:
            return False
        try:
            utc_day = dt.date(year, month, day) + dt.timedelta(days=day_shift)
        except (ValueError, OverflowError):
            return False  # no year-0000 / beyond-9999 UTC day is a listed insertion
        return f"{utc_day.year:04d}-{utc_day.month:02d}-{utc_day.day:02d}T23:59:60Z" in _leap_second_labels()
    return True


# ---- the registered leap-second table: governed input of the date-time assertion (R5R29A-R2d) ---------------------------
# metacontract:/runtime_representation/schema_format_assertion/standard_domain_semantics/leap_second_rule names the table
# (table_ref, table_path) and pins its RFC 8785 JCS SHA-256 (table_semantic_sha256, table_digest_algorithm,
# table_digest_serialization); the table is exhaustive for the package version and is never refreshed at evaluation time. The
# verifier therefore takes the table ONLY from the package under evaluation (registry row of table_ref, at table_path, read
# under the run root), and only after its JCS digest equals the pin. Anything else (no run, no rule, no registered row, a row
# at another path, unreadable or non-JSON table, digest differing from the pin, malformed table) means the verifier cannot
# assert format date-time: the run FAILS CLOSED with an internal verifier error (never a candidate result, never a pass).
class LeapSecondTableError(RuntimeError):
    """The registered leap-second table cannot be bound or does not match its pin: format date-time cannot be asserted."""


_LEAP_RUN: list[Any] = [None]  # the Run whose package supplies the governed table (set by _init_run)
_LEAP_BOUND: list[Any] = [None, None]  # [run, frozenset of table labels] once bound and verified
_LEAP_LABEL = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T23:59:60Z")


def _leap_second_labels(run: Any = None) -> frozenset[str]:
    run = run if run is not None else _LEAP_RUN[0]
    if run is None:
        raise LeapSecondTableError("no package under evaluation supplies the registered leap-second table")
    if _LEAP_BOUND[0] is run:
        return _LEAP_BOUND[1]
    node: Any = run.metacontract
    for member in ("runtime_representation", "schema_format_assertion", "standard_domain_semantics", "leap_second_rule"):
        node = node.get(member) if isinstance(node, dict) else None
    if not isinstance(node, dict):
        raise LeapSecondTableError("the package metacontract declares no leap_second_rule")
    reference, path, pin = node.get("table_ref"), node.get("table_path"), node.get("table_semantic_sha256")
    if (not isinstance(path, str) or not _is_sha256_hex(pin) or node.get("table_digest_algorithm") != "SHA-256"
            or node.get("table_digest_serialization") != "RFC8785_JCS"):
        raise LeapSecondTableError("the leap_second_rule table path or digest pin is malformed")
    rows = run.find_rows(_identity_triple(reference))
    if len(rows) != 1 or rows[0][1].get("path") != path:
        raise LeapSecondTableError("the package does not register exactly one leap-second table row at the declared path")
    status, table = run.row_content(rows[0][1])
    if status != "OK" or not isinstance(table, dict):
        raise LeapSecondTableError("the registered leap-second table is unreadable or is not a JSON object")
    try:
        digest = sha256(jcs(table))
    except ExpressionError as exc:
        raise LeapSecondTableError("the registered leap-second table is outside the RFC 8785 domain") from exc
    if digest != pin:
        raise LeapSecondTableError("the registered leap-second table digest differs from the pin of the leap_second_rule")
    insertions = table.get("insertions")
    if not isinstance(insertions, list) or not insertions or table.get("insertion_count") != len(insertions):
        raise LeapSecondTableError("the registered leap-second table has no consistent insertions list")
    labels: set[str] = set()
    for insertion in insertions:
        label = insertion.get("utc_instant") if isinstance(insertion, dict) else None
        if not isinstance(label, str) or _LEAP_LABEL.fullmatch(label) is None or label in labels:
            raise LeapSecondTableError("the registered leap-second table holds a malformed or duplicate utc_instant")
        try:
            dt.date.fromisoformat(label[:10])
        except ValueError as exc:
            raise LeapSecondTableError("the registered leap-second table holds a non-calendar utc_instant") from exc
        labels.add(label)
    _LEAP_BOUND[0], _LEAP_BOUND[1] = run, frozenset(labels)
    return _LEAP_BOUND[1]


_DATE_TIME_FORMAT_CHECKER = jsonschema.FormatChecker(formats=())
_DATE_TIME_FORMAT_CHECKER.checks("date-time")(_rfc3339_date_time)


def _date_time_assertion_selfcheck() -> None:
    """Fail closed (verifier defect, never a candidate result) unless the library really applies the date-time checker."""
    probe = jsonschema.Draft202012Validator({"format": "date-time"}, format_checker=_DATE_TIME_FORMAT_CHECKER)
    other = jsonschema.Draft202012Validator({"format": "email"}, format_checker=_DATE_TIME_FORMAT_CHECKER)
    if not (probe.is_valid("1985-04-12T23:20:50.52Z") and not probe.is_valid("1985-04-12") and not probe.is_valid("x")
            and probe.is_valid(5) and other.is_valid("not an email")):
        raise RuntimeError("the declared format: date-time assertion cannot be asserted by this implementation")


_date_time_assertion_selfcheck()


@dataclass(frozen=True)
class _CachedValidationError:
    message: str
    absolute_path: tuple[Any, ...]
    absolute_schema_path: tuple[Any, ...]
    validator: str | None


_SCHEMA_VALIDATOR_CACHE: dict[str, Any] = {}
_SCHEMA_RESULT_CACHE: dict[tuple[str, str, str], tuple[_CachedValidationError, ...]] = {}
_META_SCHEMA_VALIDATOR = jsonschema.Draft202012Validator(jsonschema.Draft202012Validator.META_SCHEMA, format_checker=_DATE_TIME_FORMAT_CHECKER)
_PROGRESS_ENABLED = False


def _progress(message: str) -> None:
    if _PROGRESS_ENABLED:
        print(f"[self-test] {message}", file=sys.stderr, flush=True)


def _bounded_cache_put(cache: dict[Any, Any], key: Any, value: Any, limit: int = 512) -> None:
    # FIFO eviction bounds memory. The keys include canonical schema/instance digests,
    # so entries are reusable only for byte-equivalent JSON under the same schema.
    if len(cache) >= limit:
        cache.pop(next(iter(cache)))
    cache[key] = value


# ---- PE-36 content validation: bounded evaluation of recursive oneOf grammars (R5R29, implementation only) --------------
# The PE-36 question and its witness are unchanged: "does the governed object satisfy its registered schema?" and, if not,
# the DESCENDANTS-canonical-preorder first location among the top-level JSON Schema failures (the `absolute_path` of the
# errors returned by Validator.iter_errors; nothing else of an error is read by PE-36). Only the METHOD changes.
#
# Why the library is slow: Validator.iter_errors evaluates a oneOf by an exhaustive error enumeration of every failing
# branch, and a failing branch that declares an operand name the instance also has descends into that child again, so a
# recursive oneOf grammar costs (number of same-named branches)^depth. In a schema whose definition D is exactly
# {"oneOf": [...]} and refers back to itself, the top-level errors of "$ref D" on an instance node x are [] or ONE error at
# x (everything inside the oneOf is only error.context), so they are determined by the boolean "D is valid for x", and that
# boolean depends on x alone. This accelerator computes it once per node, bottom-up, with an explicit work stack (no Python
# recursion in the depth of the expression): the library itself evaluates D on one node at a time, every "$ref D" met
# below that node is answered from the memo of already computed verdicts, and a node whose operand verdicts are still
# unknown is re-evaluated after the operands. Invalid nodes get their real library error from one complete evaluation.
# Every decision is therefore still taken by the library's own keyword functions. While one node is evaluated the oneOf
# decision is the library's (an error unless exactly one branch is valid), but a branch is tested only up to its first
# error; the premises below exclude the only things that could make that observable (a pattern that does not compile, an
# unresolvable or dynamically scoped reference, recursion that stays on the same instance). The accelerator applies only
# when it can prove those premises from the schema document (single resource without anchors / dynamic references,
# patterns that compile, the recursion passes through a member/element descent); in every other case, and on any internal
# exception, the frozen routine `schema_errors` is used unchanged. `schema_errors` itself and all its other consumers (PE-38,
# PE-39, the SCHEMA_VALIDATE primitive, ...) are not touched; the result is stored in the same result cache the frozen
# routine uses, so a later use of the same schema/instance pair finds exactly what the frozen routine would have stored.
_PE36_STOCK_REF = jsonschema.Draft202012Validator.VALIDATORS.get("$ref")
_PE36_STOCK_ONEOF = jsonschema.Draft202012Validator.VALIDATORS.get("oneOf")
_PE36_ACTIVE: list[Any] = [None]
_PE36_PLAN_CACHE: dict[str, Any] = {}
_PE36_MAP_KEYWORDS = ("properties", "patternProperties", "$defs", "definitions", "dependentSchemas")
_PE36_SCOPING_KEYWORDS = ("$id", "$schema", "$anchor", "$dynamicAnchor", "$dynamicRef")
_PE36_ANNOTATION_KEYWORDS = ("title", "description", "$comment")


class _Pe36Fallback(Exception):
    """Internal: the accelerated path declines; the frozen exhaustive routine answers instead."""


def _pe36_pending(memo: Mapping[Any, Any], needed: Sequence[Any]) -> list[Any]:
    pending, seen = [], set()
    for frame in needed:
        key = (id(frame[1]), id(frame[2]))
        if key not in memo and key not in seen:
            seen.add(key)
            pending.append(frame)
    return pending


class _Pe36State:
    """Verdict memo of one accelerated validation. phase: OUTER (document walk), DRIVE (one node, lazy oneOf), FINAL (the real
    library error of an invalid outermost node)."""
    __slots__ = ("targets", "phase", "memo", "needed", "current")

    def __init__(self, targets: Mapping[str, Any]):
        self.targets = targets
        self.phase = "OUTER"
        self.memo: dict[tuple[int, int], tuple[Any, bool]] = {}
        self.needed: list[tuple[str, Any, Any]] = []
        self.current: tuple[int, int] | None = None

    def expression(self, validator: Any, ref: str, target: Any, instance: Any) -> Iterator[Any]:
        if self.phase == "OUTER":
            yield from self._outer(validator, ref, target, instance)
            return
        key = (id(target), id(instance))
        if key == self.current:
            raise _Pe36Fallback()
        entry = self.memo.get(key)
        if entry is None:
            self.needed.append((ref, target, instance))  # unknown operand verdict: provisional "valid", pass is repeated
        elif not entry[1]:
            yield jsonschema.ValidationError("memoised invalid operand")

    def _outer(self, validator: Any, ref: str, target: Any, instance: Any) -> Iterator[Any]:
        key = (id(target), id(instance))
        if key not in self.memo:
            self._drive(validator, [(ref, target, instance)])
        if self.memo[key][1]:
            return
        schema = {"$ref": ref}
        self.current = key
        try:
            while True:
                self.phase, self.needed = "FINAL", []
                try:
                    errors = list(_PE36_STOCK_REF(validator, ref, instance, schema))
                finally:
                    self.phase = "OUTER"
                if not self.needed:
                    break
                pending = _pe36_pending(self.memo, self.needed)
                if not pending:
                    raise _Pe36Fallback()
                self._drive(validator, pending)
                self.current = key
        finally:
            self.current, self.needed = None, []
        if not errors:
            raise _Pe36Fallback()
        yield from errors

    def _drive(self, validator: Any, frames: list[tuple[str, Any, Any]]) -> None:
        memo = self.memo
        stack = list(reversed(frames))
        try:
            while stack:
                ref, target, node = stack[-1]
                key = (id(target), id(node))
                if key in memo:
                    stack.pop()
                    continue
                self.phase, self.current, self.needed = "DRIVE", key, []
                errors = list(_PE36_STOCK_REF(validator, ref, node, {"$ref": ref}))
                if self.needed:
                    pending = _pe36_pending(memo, self.needed)
                    if not pending:
                        raise _Pe36Fallback()
                    stack.extend(reversed(pending))
                    continue
                memo[key] = (node, not errors)  # the node is kept alive, so its id stays unique
                stack.pop()
        finally:
            self.phase, self.current, self.needed = "OUTER", None, []


def _pe36_ref(validator: Any, ref: Any, instance: Any, schema: Any) -> Any:
    state = _PE36_ACTIVE[0]
    target = state.targets.get(ref) if state is not None and isinstance(ref, str) else None
    if target is None:
        return _PE36_STOCK_REF(validator, ref, instance, schema)
    return state.expression(validator, ref, target, instance)


def _pe36_oneof_exactly_one(validator: Any, branches: Any, instance: Any) -> Iterator[Any]:
    # Same decision as the library's oneOf (an error unless exactly one branch is valid); branch validity is tested lazily
    # because only the verdict is wanted. The message is never read in this phase.
    valid = 0
    for index, branch in enumerate(branches):
        if next(iter(validator.descend(instance, branch, schema_path=index)), None) is None:
            valid += 1
            if valid > 1:
                break
    if valid != 1:
        yield jsonschema.ValidationError("oneOf: not exactly one valid branch")


def _pe36_oneof(validator: Any, branches: Any, instance: Any, schema: Any) -> Any:
    state = _PE36_ACTIVE[0]
    if state is not None and state.phase == "DRIVE":
        return _pe36_oneof_exactly_one(validator, branches, instance)
    return _PE36_STOCK_ONEOF(validator, branches, instance, schema)


try:  # an installed library without these keyword functions simply keeps the frozen routine
    _PE36_VALIDATOR_CLASS = (jsonschema.validators.extend(jsonschema.Draft202012Validator, {"$ref": _pe36_ref, "oneOf": _pe36_oneof})
                             if _PE36_STOCK_REF is not None and _PE36_STOCK_ONEOF is not None else None)
except Exception:
    _PE36_VALIDATOR_CLASS = None


def _pe36_single_resource(schema: Any) -> bool:
    """One JSON Schema resource: the root's $id/$schema are the only ones, and there is no $anchor, $dynamicAnchor or
    $dynamicRef anywhere, so a "#/..." reference means the same root pointer wherever it occurs (no dynamic scope)."""
    stack: list[tuple[Any, Any, bool]] = [(schema, None, True)]
    while stack:
        node, parent_key, is_root = stack.pop()
        if isinstance(node, dict):
            for key, value in node.items():
                if key in _PE36_SCOPING_KEYWORDS:
                    root_identity = is_root and key in ("$id", "$schema") and isinstance(value, str)
                    property_name = isinstance(value, (dict, bool)) and parent_key in _PE36_MAP_KEYWORDS
                    if not root_identity and not property_name:
                        return False
                stack.append((value, key, False))
        elif isinstance(node, list):
            stack.extend((item, parent_key, False) for item in node)
    return True


def _pe36_patterns_compile(schema: Any) -> None:
    stack = [schema]
    while stack:
        node = stack.pop()
        if isinstance(node, dict):
            for key, value in node.items():
                if key == "pattern" and isinstance(value, str):
                    re.compile(value)
                elif key == "patternProperties" and isinstance(value, dict):
                    for pattern in value:
                        re.compile(pattern)
                stack.append(value)
        elif isinstance(node, list):
            stack.extend(node)


def _pe36_references(schema: Any) -> list[str]:
    found, stack = [], [schema]
    while stack:
        node = stack.pop()
        if isinstance(node, dict):
            for key, value in node.items():
                if key == "$ref" and isinstance(value, str):
                    found.append(value)
                stack.append(value)
        elif isinstance(node, list):
            stack.extend(node)
    return found


def _pe36_recursion(target: Any, resolve: Callable[[str], Any]) -> bool | None:
    """None: no path from `target` back to itself. False: such a path exists that stays on the same instance (left recursion)
    or cannot be resolved. True: every path back to the target passes a keyword that descends into a member or element."""
    seen: set[tuple[int, bool]] = set()
    stack: list[tuple[Any, bool]] = [(target, False)]
    recursive = False
    while stack:
        node, descended = stack.pop()
        if not isinstance(node, dict) or (id(node), descended) in seen:
            continue
        seen.add((id(node), descended))
        for key, value in node.items():
            if key == "$ref" and isinstance(value, str):
                destination = resolve(value)
                if destination is None:
                    return False
                if destination is target:
                    recursive = True
                    if not descended:
                        return False
                stack.append((destination, descended))
            elif key in ("allOf", "anyOf", "oneOf") and isinstance(value, list):
                stack.extend((sub, descended) for sub in value)
            elif key in ("not", "if", "then", "else"):
                stack.append((value, descended))
            elif key == "dependentSchemas" and isinstance(value, dict):
                stack.extend((sub, descended) for sub in value.values())
            elif key in ("properties", "patternProperties") and isinstance(value, dict):
                stack.extend((sub, True) for sub in value.values())
            elif key in ("additionalProperties", "items", "contains", "propertyNames", "unevaluatedProperties",
                         "unevaluatedItems", "contentSchema"):
                stack.append((value, True))
            elif key == "prefixItems" and isinstance(value, list):
                stack.extend((sub, True) for sub in value)
    return True if recursive else None


def _pe36_build_plan(schema: dict[str, Any]) -> tuple[Any, dict[str, Any]] | None:
    """(validator, {local $ref string: recursive oneOf-only definition}) or None when the frozen routine must answer."""
    if _PE36_VALIDATOR_CLASS is None or schema.get("$schema") != DIALECT:
        return None
    check_local_schema_refs(schema)
    _check_schema(schema)
    if not _pe36_single_resource(schema):
        return None
    _pe36_patterns_compile(schema)
    resolver = _ReferencingRegistry().resolver_with_root(
        _ReferencingResource.from_contents(schema, default_specification=_REFERENCING_DRAFT202012))
    resolved: dict[str, Any] = {}

    def resolve(reference: str) -> Any:
        if reference not in resolved:
            try:
                resolved[reference] = resolver.lookup(reference).contents
            except Exception:
                resolved[reference] = None
        return resolved[reference]

    targets: dict[str, Any] = {}
    for reference in set(_pe36_references(schema)):
        target = resolve(reference)
        if not isinstance(target, dict) or not isinstance(target.get("oneOf"), list) \
                or not set(target) <= {"oneOf", *_PE36_ANNOTATION_KEYWORDS}:
            continue
        if _pe36_recursion(target, resolve) is True:
            targets[reference] = target
    return (_PE36_VALIDATOR_CLASS(schema, format_checker=_DATE_TIME_FORMAT_CHECKER), targets) if targets else None


def _pe36_plan(schema: Any) -> tuple[str, Any, dict[str, Any]] | None:
    try:
        key = sha256(jcs(schema))
    except Exception:
        return None
    if key not in _PE36_PLAN_CACHE:
        try:
            built = _pe36_build_plan(schema)
            plan = None if built is None else (key, built[0], built[1])
        except Exception:  # an invalid schema is reported by the frozen routine exactly as before
            plan = None
        _bounded_cache_put(_PE36_PLAN_CACHE, key, plan)
    return _PE36_PLAN_CACHE[key]


def _pe36_schema_errors(schema: Any, instance: Any) -> list[Any]:
    """Result of schema_errors(schema, instance, "INSTANCE"), obtained without the exponential oneOf enumeration. The result
    is stored in (and served from) the same result cache as the frozen routine, so later users of the pair are unaffected."""
    plan = _pe36_plan(schema) if isinstance(schema, dict) else None
    if plan is not None:
        schema_key, validator, targets = plan
        try:
            instance_key: str | None = sha256(jcs(instance))
        except ExpressionError:
            instance_key = None
        cache_key = (schema_key, instance_key, "INSTANCE") if instance_key is not None else None
        cached = _SCHEMA_RESULT_CACHE.get(cache_key) if cache_key is not None else None
        if cached is None:
            _PE36_ACTIVE[0] = _Pe36State(targets)
            try:
                errors: list[Any] | None = list(validator.iter_errors(instance))
            except Exception:
                errors = None
            finally:
                _PE36_ACTIVE[0] = None
            if errors is not None:
                cached = tuple(_CachedValidationError(err.message, tuple(err.absolute_path), tuple(err.absolute_schema_path),
                                                      err.validator) for err in sorted(errors, key=_validation_error_sort_key))
                if cache_key is not None:
                    _bounded_cache_put(_SCHEMA_RESULT_CACHE, cache_key, cached)
        if cached is not None:
            return list(cached)
    return schema_errors(schema, instance, "INSTANCE")


# ---- SCHEMA_VALIDATE evaluation independent of the Python call-stack depth (R5R29A-R2) ------------------------------
# The SCHEMA_VALIDATE primitive declares output BOOLEAN, semantics "JSON Schema Draft 2020-12; local fragment refs only; no
# retrieval", and the error classes MALFORMED_SCHEMA, UNRESOLVED_LOCAL_FRAGMENT and UNSUPPORTED_DIALECT. It declares no
# structural or traversal bound (max_json_traversal_depth is attached to DESCENDANTS only), so a schema or an instance that
# is merely deeply nested has the Draft 2020-12 boolean it has: Python call-stack exhaustion is never a result.
#
# The library evaluates by Python recursion (several frames per nesting level of schema and of instance). Method here: the
# library's own keyword functions decide everything, but the validator class used (a private extension of Draft202012Validator)
# answers every nested evaluation request (`descend`, `iter_errors`, hence `is_valid`) from a verdict memo instead of recursing.
# One node (schema, instance, resolution context) is evaluated at a time, bottom-up, with an explicit work stack:
#  - a request whose verdict is not yet known is recorded and provisionally taken as "valid" for the rest of that pass;
#  - the recorded requests are then evaluated in the order they were made; as soon as one proves invalid the pass is stale and
#    is repeated (so evaluation is as lazy as the library's: nothing after an invalid operand is evaluated for its sake). A node
#    that has repeated _SV_LAZY_REPEATS times (a keyword that counts or tries alternatives over many operands) decides all of
#    its operands before its next repeat, which bounds the repeats; only the schedule changes, never a verdict;
#  - when every request of a pass is answered with a verdict equal to the assumption, the pass outcome is the node's verdict.
# A node's verdict is therefore always one complete library pass over its keywords with real verdicts for all operands; the
# first error of that pass decides, exactly as `is_valid` does. A cycle (a node that needs its own verdict) is a schema that
# the recursive library can only fail on by call-stack exhaustion; it raises _SchemaEvaluationCycle, an internal failure,
# never a boolean. Memo keys use the resolution context (base URI and dynamic scope) by value, so $id / $anchor / $dynamicRef
# behave as in the library. Only validity is computed (SCHEMA_VALIDATE needs nothing else); callers that need error
# objects keep using schema_errors.
#
# Location mode (R5R29A-R2d): the same machinery can also report WHERE a document is invalid, which a registered schema document
# that violates the meta-schema needs (PE-37 SCHEMA_METASCHEMA: the first invalid location in DESCENDANTS canonical preorder
# among the errors of Validator.iter_errors) when the document is nested too deeply for the recursive library. In this mode a
# pass lists ALL errors of the node (not only the first), and the memo keeps for every invalid node the minimal error location
# (relative path, DESCENDANTS canonical preorder: an ancestor precedes its descendants, array indexes ascend, object member
# names ascend by UTF-16 code units). A request answered from the memo yields one stand-in error whose path is the descend `path`
# prefix plus that minimal relative location; the minimum of the prefixed locations is the prefix of the minimum, so the minimum
# over the whole evaluation is exact. Verdict-only mode is unchanged.
_SV_ACTIVE: list[Any] = [None]
_SV_NO_LOCATION = object()
_SV_LAZY_REPEATS = 3  # a node repeats its pass at once for its first invalid operands; after that all of its operands are decided first
_SV_CLASS: Any = None
_SV_STOCK_DESCEND: Any = None
_SV_STOCK_ITER_ERRORS: Any = None
_SV_FIELDS: tuple[tuple[str, str], ...] = ()


class _SchemaEvaluationCycle(Exception):
    """Internal: schema evaluation needs the verdict of a node whose verdict it is computing."""


class _SvInvalid:
    """Location-mode verdict of an invalid node: falsy, carries the minimal error location. A location is a persistent list
    (None = the node itself, else (token, rest)) so that a parent prepends its own token in O(1) and shares the tail."""
    __slots__ = ("path",)

    def __init__(self, path: Any):
        self.path = path

    def __bool__(self) -> bool:
        return False


def _sv_location_before(one: Any, two: Any) -> bool:
    """one < two in DESCENDANTS canonical preorder (an ancestor precedes its descendants; array indexes ascend; object member
    names ascend by UTF-16 code units). Locations share tails, so equal suffixes are recognised by identity."""
    while one is not two:
        if one is None:
            return True
        if two is None:
            return False
        key_one, key_two = _path_key((one[0],)), _path_key((two[0],))
        if key_one != key_two:
            return key_one < key_two
        one, two = one[1], two[1]
    return False


class _SvRequest:
    __slots__ = ("key", "kind", "validator", "instance", "schema", "resolver")

    def __init__(self, key: Any, kind: str, validator: Any, instance: Any, schema: Any, resolver: Any):
        self.key, self.kind, self.validator, self.instance, self.schema, self.resolver = key, kind, validator, instance, schema, resolver


def _sv_context(resolver: Any) -> Any:
    """Value identity of a referencing.Resolver: its base URI and its dynamic scope."""
    return (resolver._base_uri, resolver._previous)


def _sv_pass(request: _SvRequest, locate: bool = False) -> Any:
    """One library pass over the keywords of one node; True when it yields no error (under the pass assumptions). In location
    mode every error of the pass is listed and an invalid node yields _SvInvalid(minimal relative error location)."""
    if request.kind == "D":
        errors = _SV_STOCK_DESCEND(request.validator, request.instance, request.schema, None, None, request.resolver)
    else:
        errors = _SV_STOCK_ITER_ERRORS(request.validator, request.instance, None)
    if not locate:
        return next(errors, None) is None
    best: Any = None
    found = False
    for error in errors:
        located = getattr(error, "_sv_location", _SV_NO_LOCATION)
        if located is _SV_NO_LOCATION:  # an error raised by a keyword function at this node itself
            located = None
            for token in reversed(tuple(error.absolute_path)):
                located = (token, located)
        if not found or _sv_location_before(located, best):
            best, found = located, True
    return _SvInvalid(best) if found else True


class _SvState:
    __slots__ = ("memo", "needed", "active", "locate")

    def __init__(self, locate: bool = False) -> None:
        self.memo: dict[Any, tuple[Any, _SvRequest]] = {}
        self.needed: list[_SvRequest] = []
        self.active: set[Any] = set()
        self.locate = locate

    def answer(self, key: Any, make: Callable[[], _SvRequest], path: Any = None) -> Iterator[Any]:
        entry = self.memo.get(key)
        if entry is None:
            self.needed.append(make())  # unknown operand verdict: provisionally valid for the rest of this pass
            return iter(())
        if entry[0]:
            return iter(())
        if not self.locate:
            return iter((jsonschema.ValidationError("memoised invalid evaluation"),))
        located = entry[0].path if isinstance(entry[0], _SvInvalid) else None
        standin = jsonschema.ValidationError("memoised invalid evaluation")
        standin._sv_location = located if path is None else (path, located)
        return iter((standin,))

    def solve(self, root: _SvRequest) -> bool:
        memo, active = self.memo, self.active
        # frame: request, operand requests, next operand, pass outcome, repeats so far, an operand proved invalid
        start = _SV_LAZY_REPEATS if self.locate else 0  # location mode lists every error: all requested operands are decided first
        stack: list[list[Any]] = [[root, None, 0, True, start, False]]
        active.add(root.key)
        while stack:
            frame = stack[-1]
            request = frame[0]
            if frame[1] is None:
                self.needed = []
                outcome = _sv_pass(request, self.locate)
                operands: list[_SvRequest] = []
                seen: set[Any] = set()
                for operand in self.needed:
                    if operand.key not in memo and operand.key not in seen:
                        seen.add(operand.key)
                        operands.append(operand)
                self.needed = []
                if not operands:
                    memo[request.key] = (outcome, request)  # the request keeps schema and instance alive: ids stay unique
                    active.discard(request.key)
                    stack.pop()
                    continue
                frame[1], frame[2], frame[3], frame[5] = operands, 0, outcome, False
            operands, index, invalid = frame[1], frame[2], frame[5]
            repeat = False
            while index < len(operands):
                entry = memo.get(operands[index].key)
                if entry is None:
                    break
                if not entry[0]:
                    invalid = True
                    if frame[4] < _SV_LAZY_REPEATS:
                        repeat = True  # nothing after an invalid operand is evaluated for its sake: repeat the pass at once
                        break
                index += 1
            frame[2], frame[5] = index, invalid
            if repeat or (invalid and index == len(operands)):
                frame[1], frame[4] = None, frame[4] + 1  # an operand is invalid: the provisional assumption was wrong
                continue
            if index == len(operands):
                memo[request.key] = (frame[3], request)  # every operand is valid, as assumed: the pass outcome stands
                active.discard(request.key)
                stack.pop()
                continue
            operand = operands[index]
            if operand.key in active:
                raise _SchemaEvaluationCycle("schema evaluation requires its own verdict")
            active.add(operand.key)
            stack.append([operand, None, 0, True, start, False])
        return memo[root.key][0]


def _sv_descend(self: Any, instance: Any, schema: Any, path: Any = None, schema_path: Any = None, resolver: Any = None) -> Any:
    state = _SV_ACTIVE[0]
    if state is None:
        return _SV_STOCK_DESCEND(self, instance, schema, path, schema_path, resolver)
    if schema is True:
        return iter(())
    if schema is False:
        return iter((jsonschema.ValidationError("False schema does not allow the instance"),))
    key = (id(schema), id(instance), "D", _sv_context(self._resolver), None if resolver is None else _sv_context(resolver))
    return state.answer(key, lambda: _SvRequest(key, "D", self, instance, schema, resolver), path)


def _sv_iter_errors(self: Any, instance: Any, _schema: Any = None) -> Any:
    state = _SV_ACTIVE[0]
    if state is None or _schema is not None:
        return _SV_STOCK_ITER_ERRORS(self, instance, _schema)
    schema = self.schema
    if schema is True:
        return iter(())
    if schema is False:
        return iter((jsonschema.ValidationError("False schema does not allow the instance"),))
    key = (id(schema), id(instance), "I", _sv_context(self._resolver))
    return state.answer(key, lambda: _SvRequest(key, "I", self, instance, schema, None))


def _sv_evolve(self: Any, **changes: Any) -> Any:
    # The library's evolve, except that a subschema declaring the same dialect keeps this validator class (the metaschema
    # vocabularies declare $schema themselves); any other dialect selects its own library class, as in the library.
    cls = type(self)
    schema = changes.setdefault("schema", self.schema)
    target = jsonschema.validators.validator_for(schema, default=cls)
    if target is jsonschema.Draft202012Validator:
        target = cls
    for name, alias in _SV_FIELDS:
        if alias not in changes:
            changes[alias] = getattr(self, name)
    return target(**changes)


def _sv_is_valid(validator: Any, instance: Any, locate: bool = False) -> Any:
    """True iff `validator.schema` validates `instance`; independent of the Python call-stack depth of schema and instance.
    In location mode (internal) the result is True or an _SvInvalid carrying the first invalid location."""
    state = _SvState(locate)
    previous, _SV_ACTIVE[0] = _SV_ACTIVE[0], state
    try:
        schema = validator.schema
        if schema is True or schema is False:
            return True if schema is True else (_SvInvalid(None) if locate else False)
        key = (id(schema), id(instance), "I", _sv_context(validator._resolver))
        return state.solve(_SvRequest(key, "I", validator, instance, schema, None))
    finally:
        _SV_ACTIVE[0] = previous


def _sv_first_invalid_location(validator: Any, instance: Any) -> tuple[Any, ...] | None:
    """None when `validator.schema` validates `instance`; else the first invalid location (instance path tokens) in DESCENDANTS
    canonical preorder among the errors of validator.iter_errors(instance); independent of the Python call-stack depth."""
    verdict = _sv_is_valid(validator, instance, True)
    if verdict:
        return None
    tokens: list[Any] = []
    node = verdict.path
    while node is not None:
        tokens.append(node[0])
        node = node[1]
    return tuple(tokens)


def _sv_selfcheck(cls: Any) -> bool:
    probe = {"$schema": "https://json-schema.org/draft/2020-12/schema", "$ref": "#/$defs/n",
             "$defs": {"n": {"type": ["array", "integer"], "items": {"$ref": "#/$defs/n"}}}}
    validator = cls(probe)
    return (_sv_is_valid(validator, [[1], 2]) is True and _sv_is_valid(validator, [["x"]]) is False
            and _sv_is_valid(cls(jsonschema.Draft202012Validator.META_SCHEMA), probe) is True)


# const, enum and uniqueItems compare whole values, and the library compares them by Python recursion in the nesting depth of the
# values, so the class below carries equivalent comparison keyword functions (same verdicts, explicit stack, no error text).
_SV_TRUE, _SV_FALSE = object(), object()


def _sv_equal(one: Any, two: Any) -> bool:
    """JSON Schema value equality as the library defines it (booleans are not numbers; arrays element-wise; objects member-wise,
    unordered; everything else by Python equality), with an explicit stack instead of recursion in the nesting depth."""
    pending: list[tuple[Any, Any]] = [(one, two)]
    while pending:
        one, two = pending.pop()
        if one is two:
            continue
        if isinstance(one, str) or isinstance(two, str):
            if one != two:
                return False
        elif isinstance(one, Sequence) and isinstance(two, Sequence):
            if len(one) != len(two):
                return False
            pending.extend(zip(one, two))
        elif isinstance(one, Mapping) and isinstance(two, Mapping):
            if len(one) != len(two):
                return False
            for key, value in one.items():
                if key not in two:
                    return False
                pending.append((value, two[key]))
        elif (_SV_TRUE if one is True else _SV_FALSE if one is False else one) != (
                _SV_TRUE if two is True else _SV_FALSE if two is False else two):
            return False
    return True


def _sv_unique(items: Any) -> bool:
    """No two elements of the array are equal (_sv_equal). Elements are grouped by a shallow fingerprint first, so only
    candidates that can be equal are compared."""
    groups: dict[Any, list[Any]] = {}
    for item in items:
        if isinstance(item, str):
            fingerprint: Any = ("str", item)
        elif isinstance(item, (list, tuple)):
            fingerprint = ("arr", len(item))
        elif isinstance(item, Mapping):
            fingerprint = ("obj", frozenset(item))
        elif item is True or item is False or item is None:
            fingerprint = ("lit", item)
        else:
            fingerprint = ("num", item)
        members = groups.setdefault(fingerprint, [])
        if members and (fingerprint[0] in ("str", "lit", "num") or any(_sv_equal(item, other) for other in members)):
            return False
        members.append(item)
    return True


def _sv_const(validator: Any, const: Any, instance: Any, schema: Any) -> Iterator[Any]:
    if not _sv_equal(instance, const):
        yield jsonschema.ValidationError("value is not the const")


def _sv_enum(validator: Any, enums: Any, instance: Any, schema: Any) -> Iterator[Any]:
    if all(not _sv_equal(each, instance) for each in enums):
        yield jsonschema.ValidationError("value is not one of the enum")


def _sv_unique_items(validator: Any, unique: Any, instance: Any, schema: Any) -> Iterator[Any]:
    if unique and validator.is_type(instance, "array") and not _sv_unique(instance):
        yield jsonschema.ValidationError("array has non-unique elements")


try:  # an installed library without the expected internals simply keeps the recursive library routine
    _SV_CLASS = jsonschema.validators.extend(
        jsonschema.Draft202012Validator, {"const": _sv_const, "enum": _sv_enum, "uniqueItems": _sv_unique_items})
    _SV_STOCK_DESCEND, _SV_STOCK_ITER_ERRORS = _SV_CLASS.descend, _SV_CLASS.iter_errors
    _SV_FIELDS = tuple((field.name, field.alias) for field in _SV_CLASS.__attrs_attrs__ if field.init)
    _SV_CLASS.descend, _SV_CLASS.iter_errors, _SV_CLASS.evolve = _sv_descend, _sv_iter_errors, _sv_evolve
    if not _sv_selfcheck(_SV_CLASS):
        _SV_CLASS = None
except Exception:  # import-time capability probe only: nothing here is ever a candidate result
    _SV_CLASS = None


_SV_VALIDATOR_CACHE: dict[str, Any] = {}
_SV_REJECTED_CACHE: dict[str, tuple[str, str, str]] = {}
_SV_RESULT_CACHE: dict[tuple[str, str | None, str], bool] = {}
_SV_NESTING_LIMIT = 48  # containers; the recursive library check_schema needs about 5 frames per container level
_SV_META_VALIDATOR: Any = (_SV_CLASS(jsonschema.Draft202012Validator.META_SCHEMA, format_checker=_DATE_TIME_FORMAT_CHECKER)
                           if _SV_CLASS is not None else None)
_SV_CHECK_VALIDATOR: Any = (_SV_CLASS(jsonschema.Draft202012Validator.META_SCHEMA,
                                      format_checker=jsonschema.Draft202012Validator.FORMAT_CHECKER)
                            if _SV_CLASS is not None else None)


def _json_nesting_exceeds(value: Any, limit: int) -> bool:
    """True when `value` holds a container nested more than `limit` containers deep (explicit stack)."""
    pending: list[tuple[Any, int]] = [(value, 1)]
    while pending:
        node, level = pending.pop()
        if isinstance(node, dict):
            children: Iterable[Any] = node.values()
        elif isinstance(node, (list, tuple)):
            children = node
        else:
            continue
        if level > limit:
            return True
        pending.extend((child, level + 1) for child in children)
    return False


def _meta_schema_errors(document: Any) -> list[Any]:
    """list(_META_SCHEMA_VALIDATOR.iter_errors(document)) for PE-37. A deeply nested document is decided without Python
    recursion in its depth (R5R29A-R2d): the errors of such a document are represented by ONE error whose absolute_path is the
    first invalid location in DESCENDANTS canonical preorder among all errors of the library evaluation (the only property of
    the errors that PE-37 reads); [] when the document is valid. Every other document uses the library routine as before."""
    if _SV_CLASS is not None and _json_nesting_exceeds(document, _SV_NESTING_LIMIT):
        location = _sv_first_invalid_location(_SV_META_VALIDATOR, document)
        return [] if location is None else [jsonschema.ValidationError("document violates the Draft 2020-12 meta-schema", path=location)]
    return list(_META_SCHEMA_VALIDATOR.iter_errors(document))


def _check_schema(schema: Any) -> None:
    """jsonschema.Draft202012Validator.check_schema(schema); a deeply nested schema is decided by _sv_is_valid instead of by
    Python recursion in its depth (SchemaError names only the fact when it violates the meta-schema)."""
    if _SV_CLASS is not None and _json_nesting_exceeds(schema, _SV_NESTING_LIMIT):
        if not _sv_is_valid(_SV_CHECK_VALIDATOR, schema):
            raise jsonschema.SchemaError("schema is not valid under the Draft 2020-12 meta-schema")
        return
    jsonschema.Draft202012Validator.check_schema(schema)


# ---- SCHEMA_VALIDATE schema-operand admission and decision (R5R29A-R2e-P staged law) ------------------------------------
# Law: primitive-registry:/primitives/<SCHEMA_VALIDATE>/{schema_representation, dialect_selection, reference_admissibility,
# schema_position, meta_schema_mode, error_precedence, within_step_selection}; the error classes stay MALFORMED_SCHEMA, UNRESOLVED_LOCAL_FRAGMENT and
# UNSUPPORTED_DIALECT only. The decision procedure, for the `schema` operand in both modes:
#   1 shape       the operand is an admitted schema object or boolean representable in RFC 8785      -> MALFORMED_SCHEMA otherwise
#   2 dialect     every `$schema` member at a schema position: not a string, or not an absolute RFC 3986 URI with a scheme,
#                 or not equal to its RFC 3986 6.2.2 syntax-based normalisation -> MALFORMED_SCHEMA; any other valid URI that
#                 is not exactly the supported identifier (a trailing "#" included) -> UNSUPPORTED_DIALECT; an absent
#                 `$schema` selects Draft 2020-12; a nested `$schema` equal to the supported identifier is inert
#   3 admissible  Draft 2020-12 meta-schema validity (keyword value forms, structure); every `$ref` at a schema position is
#                 exactly "#" or "#/..." with an RFC 3986 fragment whose percent-decoded value is an RFC 6901 pointer; no
#                 `$dynamicRef` at a schema position (all semantically active); no ref located inside, or whose pointer path
#                 from the root enters, an embedded schema resource (a non-root schema position declaring `$id`)  -> MALFORMED_SCHEMA
#   4 resolution  admitted refs resolve against the operand root: missing target -> UNRESOLVED_LOCAL_FRAGMENT; present
#                 non-schema target or cyclic local-ref graph -> MALFORMED_SCHEMA; repeated acyclic targets are allowed
#   5 boolean     instance validation (INSTANCE); META_SCHEMA tests only the schema operand and ignores instance
# `$anchor` and `$dynamicAnchor` are inert; a root `$id` is an identifier only. Keywords count only as members of an object at a
# schema position (the root and every value reached through the Draft 2020-12 schema-valued keywords listed in
# schema_position); members inside const / enum / default / examples, property names, `required` ... are data. Within one step
# no semantic rank exists among conditions: the owning location is the first in DESCENDANTS canonical preorder, and the walk
# below visits schema positions and their members exactly in that order (object members by UTF-16 code units, array
# elements ascending), with an explicit stack: no Python recursion in the nesting depth of the operand.
_SV_KEYWORDS_SINGLE = frozenset(("additionalProperties", "items", "contains", "propertyNames", "unevaluatedItems",
                                 "unevaluatedProperties", "not", "if", "then", "else", "contentSchema"))
_SV_KEYWORDS_ARRAY = frozenset(("prefixItems", "allOf", "anyOf", "oneOf"))
_SV_KEYWORDS_OBJECT = frozenset(("properties", "patternProperties", "dependentSchemas", "$defs"))

_RFC3986_UNRESERVED = r"A-Za-z0-9\-._~"
_RFC3986_SUB_DELIMS = r"!$&'()*+,;="
_RFC3986_PCT = r"%[0-9A-Fa-f]{2}"
_RFC3986_PCHAR = rf"(?:[{_RFC3986_UNRESERVED}{_RFC3986_SUB_DELIMS}:@]|{_RFC3986_PCT})"
_RFC3986_URI = re.compile(
    r"(?P<scheme>[A-Za-z][A-Za-z0-9+\-.]*):"
    r"(?://(?P<authority>(?:(?P<userinfo>(?:[" + _RFC3986_UNRESERVED + _RFC3986_SUB_DELIMS + r":]|" + _RFC3986_PCT + r")*)@)?"
    r"(?P<host>\[(?:[0-9A-Fa-f:.]+|[vV][0-9A-Fa-f]+\.[" + _RFC3986_UNRESERVED + _RFC3986_SUB_DELIMS + r":]+)\]"
    r"|(?:[" + _RFC3986_UNRESERVED + _RFC3986_SUB_DELIMS + r"]|" + _RFC3986_PCT + r")*)"
    r"(?::(?P<port>[0-9]*))?)(?P<path_abempty>(?:/" + _RFC3986_PCHAR + r"*)*)"
    r"|(?P<path_absolute>/(?:" + _RFC3986_PCHAR + r"+(?:/" + _RFC3986_PCHAR + r"*)*)?)"
    r"|(?P<path_rootless>" + _RFC3986_PCHAR + r"+(?:/" + _RFC3986_PCHAR + r"*)*)"
    r"|(?P<path_empty>))"
    r"(?:\?(?P<query>(?:" + _RFC3986_PCHAR + r"|[/?])*))?"
    r"(?:#(?P<fragment>(?:" + _RFC3986_PCHAR + r"|[/?])*))?")
_RFC3986_FRAGMENT = re.compile(rf"(?:[{_RFC3986_UNRESERVED}{_RFC3986_SUB_DELIMS}:@/?]|{_RFC3986_PCT})*")


def _rfc3986_pct_normalize(text: str) -> str:
    """RFC 3986 6.2.2.2: percent-encoding hex digits upper case, percent-encoded unreserved characters decoded."""
    def convert(match: re.Match[str]) -> str:
        character = chr(int(match.group(1), 16))
        return character if re.fullmatch(rf"[{_RFC3986_UNRESERVED}]", character) else "%" + match.group(1).upper()
    return re.sub(r"%([0-9A-Fa-f]{2})", convert, text)


def _rfc3986_remove_dot_segments(path: str) -> str:
    """RFC 3986 5.2.4 remove_dot_segments (6.2.2.3 dot-segment removal)."""
    remaining, output = path, ""
    while remaining:
        if remaining.startswith("../"):
            remaining = remaining[3:]
        elif remaining.startswith("./"):
            remaining = remaining[2:]
        elif remaining.startswith("/./"):
            remaining = remaining[2:]
        elif remaining == "/.":
            remaining = "/"
        elif remaining.startswith("/../") or remaining == "/..":
            remaining = "/" + remaining[4:]
            output = output.rsplit("/", 1)[0] if "/" in output else ""
        elif remaining in (".", ".."):
            remaining = ""
        else:
            end = remaining.find("/", 1 if remaining.startswith("/") else 0)
            segment = remaining if end == -1 else remaining[:end]
            output += segment
            remaining = remaining[len(segment):]
    return output


def _rfc3986_ipv6_address(text: str) -> bool:
    """RFC 3986 3.2.2 IPv6address (h16 groups, at most one "::", optional trailing IPv4address as ls32)."""
    def groups(part: str) -> list[str] | None:
        return [] if part == "" else part.split(":")
    head, separator, tail = text.partition("::")
    if separator and "::" in tail:
        return False
    left = groups(head)
    right = groups(tail) if separator else []
    if left is None or right is None or (not separator and not head):
        return False
    pieces = left + right
    count = 0
    for index, piece in enumerate(pieces):
        last = index == len(pieces) - 1
        if re.fullmatch(r"[0-9A-Fa-f]{1,4}", piece):
            count += 1
        elif last and (right or not separator) and re.fullmatch(r"(?:(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])\.){3}(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])", piece):
            count += 2
        else:
            return False
    return count == 8 if not separator else count <= 7


def _rfc3986_absolute_uri_is_normalized(text: str) -> bool | None:
    """None: `text` is not an RFC 3986 URI with a scheme. Else whether it equals its syntax-based normalisation
    (6.2.2.1 case of scheme and host and of percent-encoding digits, 6.2.2.2 unreserved percent-encodings, 6.2.2.3 dot segments)."""
    match = _RFC3986_URI.fullmatch(text)
    if match is None:
        return None
    host = match.group("host")
    if host is not None and host.startswith("[") and host[1:2] not in ("v", "V") and not _rfc3986_ipv6_address(host[1:-1]):
        return None
    normalized = match.group("scheme").lower() + ":"
    if match.group("authority") is not None:
        authority = ""
        if match.group("userinfo") is not None:
            authority += _rfc3986_pct_normalize(match.group("userinfo")) + "@"
        decoded_host = host if host.startswith("[") else _rfc3986_pct_normalize(host)
        authority += re.sub(r"%[0-9A-Fa-f]{2}|.", lambda m: m.group(0) if m.group(0).startswith("%") else m.group(0).lower(), decoded_host)
        if match.group("port") is not None:
            authority += ":" + match.group("port")
        normalized += "//" + authority
    path = match.group("path_abempty") or match.group("path_absolute") or match.group("path_rootless") or ""
    normalized += _rfc3986_remove_dot_segments(_rfc3986_pct_normalize(path))
    if match.group("query") is not None:
        normalized += "?" + _rfc3986_pct_normalize(match.group("query"))
    if match.group("fragment") is not None:
        normalized += "#" + _rfc3986_pct_normalize(match.group("fragment"))
    return normalized == text


def _sv_dollar_schema_class(value: Any) -> str | None:
    """Error class of one `$schema` value: None (the supported Draft 2020-12 identifier, exact string equality),
    MALFORMED_SCHEMA (not a string, not an absolute URI with a scheme, or not normalised) or UNSUPPORTED_DIALECT."""
    if not isinstance(value, str):
        return "MALFORMED_SCHEMA"
    if value == DIALECT:
        return None
    return "UNSUPPORTED_DIALECT" if _rfc3986_absolute_uri_is_normalized(value) else "MALFORMED_SCHEMA"


def _sv_admitted_ref_tokens(reference: Any) -> tuple[str, ...] | None:
    """Decoded RFC 6901 reference tokens of an admitted ref ("#" is the root: no tokens), None when the ref is not admitted:
    exactly "#", or "#" followed by a fragment that begins with "/", is RFC 3986 fragment syntax (ASCII, valid percent
    escapes) and whose percent-decoded value (UTF-8) is a valid RFC 6901 JSON Pointer."""
    if not isinstance(reference, str):
        return None
    if reference == "#":
        return ()
    if not reference.startswith("#/") or _RFC3986_FRAGMENT.fullmatch(reference, 1) is None:
        return None
    try:
        pointer = urllib.parse.unquote_to_bytes(reference[1:]).decode("utf-8")
    except UnicodeDecodeError:
        return None
    tokens = pointer.split("/")[1:]
    if any(re.search(r"~(?![01])", token) for token in tokens):
        return None
    return tuple(token.replace("~1", "/").replace("~0", "~") for token in tokens)


def _sv_resolve_tokens(root: Any, tokens: Sequence[str]) -> tuple[bool, Any]:
    node = root
    for token in tokens:
        if isinstance(node, dict) and token in node:
            node = node[token]
        elif isinstance(node, list) and re.fullmatch(r"0|[1-9][0-9]*", token) and int(token) < len(node):
            node = node[int(token)]
        else:
            return False, None
    return True, node


def _sv_admit_schema(schema: Any) -> None:
    """Steps 2 to 4 of the SCHEMA_VALIDATE decision procedure for an operand that passed step 1; raises ExpressionError."""
    embedded_roots: set[tuple[str, ...]] = set()
    refs: list[tuple[tuple[Any, ...], tuple[str, ...]]] = []  # admitted refs: (member location tokens, decoded pointer tokens)
    faults: list[tuple[tuple[Any, ...], str]] = []  # step 3 faults: (location tokens, reason)
    dialect_faults: list[tuple[tuple[Any, ...], str]] = []
    seen_schema_positions: set[tuple[str, ...]] = set()
    target_schemas: dict[tuple[str, ...], Any] = {}
    # entries: (True, key, node, tokens, inside) a member check; (False, value, tokens, inside) a schema position
    pending: list[tuple[Any, ...]] = [(False, schema, (), False)]
    while pending:
        entry = pending.pop()
        if entry[0]:
            _, key, node, tokens, inside = entry
            if key == "$schema":
                error_class = _sv_dollar_schema_class(node[key])
                if error_class is not None:
                    dialect_faults.append((tokens + (key,), error_class))
            elif key == "$dynamicRef":
                faults.append((tokens + (key,), "$dynamicRef is not supported"))
            else:  # $ref
                admitted = _sv_admitted_ref_tokens(node[key])
                if admitted is None:
                    faults.append((tokens + (key,), "$ref is not a local JSON Pointer fragment reference"))
                elif inside:
                    faults.append((tokens + (key,), "$ref is located inside an embedded schema resource"))
                else:
                    refs.append((tokens + (key,), admitted))
                    found, target = _sv_resolve_tokens(schema, admitted)
                    target_tokens = tuple(str(token) for token in admitted)
                    if found and isinstance(target, (dict, bool)) and target_tokens not in seen_schema_positions:
                        target_schemas[target_tokens] = target
                        pending.append((False, target, target_tokens, False))
            continue
        _, node, tokens, inside = entry
        normalized_tokens = tuple(str(token) for token in tokens)
        if normalized_tokens in seen_schema_positions:
            continue
        seen_schema_positions.add(normalized_tokens)
        if not isinstance(node, dict):
            continue  # a boolean schema, or a value the meta-schema rejects in step 3
        if tokens and "$id" in node:
            embedded_roots.add(tuple(str(token) for token in tokens))
            inside = True
        members: list[tuple[Any, ...]] = []
        for key in sorted(node, key=_utf16_key):
            value = node[key]
            if key in ("$schema", "$ref", "$dynamicRef"):
                members.append((True, key, node, tokens, inside))
            elif key in _SV_KEYWORDS_SINGLE:
                members.append((False, value, tokens + (key,), inside))
            elif key in _SV_KEYWORDS_ARRAY and isinstance(value, list):
                members.extend((False, item, tokens + (key, index), inside) for index, item in enumerate(value))
            elif key in _SV_KEYWORDS_OBJECT and isinstance(value, dict):
                members.extend((False, value[name], tokens + (key, name), inside) for name in sorted(value, key=_utf16_key))
        pending.extend(reversed(members))
    if dialect_faults:
        location, error_class = min(dialect_faults, key=lambda fault: _path_key(fault[0]))
        raise ExpressionError(error_class, _pointer_of(location), f"$schema at {_pointer_of(location)} is "
                              + ("not a normalized absolute URI" if error_class == "MALFORMED_SCHEMA"
                                 else "a dialect other than Draft 2020-12"))
    if embedded_roots:
        for location, tokens in refs:
            if any(len(root) <= len(tokens) and tokens[:len(root)] == root for root in embedded_roots):
                faults.append((location, "$ref pointer path enters an embedded schema resource"))
    try:
        _check_schema(schema)
    except jsonschema.SchemaError as exc:
        located = _first_location(tuple(error.absolute_path) for error in _meta_schema_errors(schema))
        faults.append((located or (), str(exc)))
    for target_tokens, target in target_schemas.items():
        if not isinstance(target, dict):
            continue
        try:
            _check_schema(target)
        except jsonschema.SchemaError as exc:
            located = _first_location(tuple(error.absolute_path) for error in _meta_schema_errors(target))
            faults.append((target_tokens + (located or ()), str(exc)))
    if faults:
        location, reason = min(faults, key=lambda fault: _path_key(fault[0]))
        raise ExpressionError("MALFORMED_SCHEMA", _pointer_of(location), f"schema is not admissible at {_pointer_of(location)}: {reason}")
    graph: dict[tuple[Any, ...], list[tuple[Any, ...]]] = {}
    resolution_faults: list[tuple[tuple[Any, ...], str, str]] = []
    admitted_edges: list[tuple[tuple[Any, ...], tuple[Any, ...], tuple[Any, ...]]] = []
    for location, tokens in refs:
        found, target = _sv_resolve_tokens(schema, tokens)
        if not found:
            resolution_faults.append((location, "UNRESOLVED_LOCAL_FRAGMENT", "local fragment target is missing"))
        elif not isinstance(target, (dict, bool)):
            resolution_faults.append((location, "MALFORMED_SCHEMA", "local fragment target is not a schema representation"))
        else:
            source = tuple(str(token) for token in location[:-1])
            destination = tuple(tokens)
            graph.setdefault(source, []).append(destination)
            admitted_edges.append((source, destination, location))
    # Path-aware reachability distinguishes a repeated target in a DAG from a cycle.
    # Visit edges in the same canonical order used for other defects in this step.
    for source, destination, location in sorted(admitted_edges, key=lambda edge: _path_key(edge[2])):
        pending_vertices = [destination]
        seen_vertices: set[tuple[Any, ...]] = set()
        while pending_vertices:
            vertex = pending_vertices.pop()
            if vertex == source:
                resolution_faults.append((location, "MALFORMED_SCHEMA", "local reference graph contains a cycle"))
                break
            if vertex not in seen_vertices:
                seen_vertices.add(vertex)
                pending_vertices.extend(graph.get(vertex, ()))
    if resolution_faults:
        location, error_class, reason = min(resolution_faults, key=lambda fault: _path_key(fault[0]))
        raise ExpressionError(error_class, _pointer_of(location), reason)


def schema_valid(schema: Any, instance: Any, mode: str) -> bool:
    """The SCHEMA_VALIDATE boolean for schema and instance of any nesting depth, by the decision procedure above (steps 1 to 5).
    Step 5, and the meta-schema validity of step 3, are decided by _sv_is_valid (no Python recursion in the nesting depth);
    a deeply nested schema that violates the meta-schema is reported at its first invalid location."""
    if not isinstance(schema, (dict, bool)):
        raise ExpressionError("MALFORMED_SCHEMA", detail="schema must be an admitted object or boolean schema")
    if mode not in ("META_SCHEMA", "INSTANCE"):
        raise ExpressionError("INVALID_SCHEMA_MODE", detail=mode)
    try:
        schema_key = sha256(jcs(schema))
    except ExpressionError as exc:
        raise ExpressionError("MALFORMED_SCHEMA", detail=exc.detail) from exc
    validator = _SV_VALIDATOR_CACHE.get(schema_key)
    if validator is None:
        rejected = _SV_REJECTED_CACHE.get(schema_key)  # admission is deterministic: an inadmissible operand is rejected the same way
        if rejected is not None:
            raise ExpressionError(*rejected)
        try:
            _sv_admit_schema(schema)
        except ExpressionError as exc:
            _bounded_cache_put(_SV_REJECTED_CACHE, schema_key, (exc.error_class, exc.pointer, exc.detail))
            raise
        try:
            validator = (_SV_CLASS or jsonschema.Draft202012Validator)(schema, format_checker=_DATE_TIME_FORMAT_CHECKER)
        except Exception as exc:
            if _is_reference_resolution_error(exc):
                raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", detail=str(exc)) from exc
            raise
        _SV_VALIDATOR_CACHE[schema_key] = validator
    if mode == "META_SCHEMA":
        cache_key: tuple[str, str | None, str] | None = (schema_key, schema_key, mode)
        subject, subject_validator = schema, (_SV_META_VALIDATOR or _META_SCHEMA_VALIDATOR)
    else:
        try:
            instance_key: str | None = sha256(jcs(instance))
        except ExpressionError:
            instance_key = None  # not a JSON value: left uncached, the validator reports it as the library does
        cache_key = (schema_key, instance_key, mode) if instance_key is not None else None
        subject, subject_validator = instance, validator
    if cache_key is not None:
        shared = _SCHEMA_RESULT_CACHE.get(cache_key)  # an earlier schema_errors / PE-36 result for the same pair
        if shared is not None:
            return not shared
        known = _SV_RESULT_CACHE.get(cache_key)
        if known is not None:
            return known
    try:
        result = (_sv_is_valid(subject_validator, subject) if _SV_CLASS is not None
                  else next(iter(subject_validator.iter_errors(subject)), None) is None)
    except Exception as exc:
        if _is_reference_resolution_error(exc):
            raise ExpressionError("UNRESOLVED_LOCAL_FRAGMENT", detail=str(exc)) from exc
        raise
    if cache_key is not None:
        _bounded_cache_put(_SV_RESULT_CACHE, cache_key, result)
    return result


def _load_commitment(zb64: str, label: str) -> Any:
    try:
        value = json.loads(zlib.decompress(base64.b64decode(zb64)).decode("utf-8"))
        digest = hashlib.sha256(rfc8785.dumps(value)).hexdigest()
    except Exception as exc:  # a corrupted verifier is a verifier defect, never a candidate result
        raise RuntimeError(f"verifier protocol commitment {label} is unreadable") from exc
    if digest != _COMMITTED_DIGESTS[label]:
        raise RuntimeError(f"verifier protocol commitment {label} does not match its committed digest")
    return value


MODEL: dict[str, Any] = _load_commitment(_COMMITTED_MODEL_ZB64, "pre_execution_failure_model")
REG: dict[str, Any] = _load_commitment(_COMMITTED_REGISTRATION_ZB64, "registration")
PC: dict[str, Any] = MODEL["protocol_constants"]
VOCAB: dict[str, Any] = MODEL["derivation_vocabulary"]
CLOSED: dict[str, Any] = MODEL["closed_vocabularies"]
DIALECT = PC["draft_2020_12_dialect"]
PROFILE_SCHEMA_ID = PC["profile_schema_identity"]
FAMILIES: dict[str, dict[str, Any]] = {f["family_id"]: f for f in MODEL["families"]}
CONDITIONS: dict[str, dict[str, dict[str, Any]]] = {
    fid: {c["condition_id"]: c for c in f["conditions"]} for fid, f in FAMILIES.items()}
CONDITION_ORDER: dict[str, list[str]] = {
    fid: [c["condition_id"] for c in sorted(f["conditions"], key=lambda c: c["rank"])] for fid, f in FAMILIES.items()}
STAGE_ORDERING: list[dict[str, Any]] = sorted(MODEL["stage_ordering"], key=lambda s: s["stage_index"])
ENTRYPOINT_SPECS: list[dict[str, Any]] = PC["entrypoints"]
BOOTSTRAP_SPECS: dict[str, dict[str, Any]] = {b["argument"]: b for b in PC["bootstrap_objects"]}
FROZEN_SOURCES: dict[str, dict[str, Any]] = {s["profile_member"]: s for s in PC["frozen_sources"]}
CLAIMS: list[dict[str, Any]] = PC["claim_comparisons"]
SELECTOR: dict[str, Any] = PC["procedure_projection_selector"]
PACKAGE_IDENTITY_MEMBERS: list[str] = PC["package_identity_members"]
JSON_TYPE_TOKENS: list[str] = CLOSED["json_type"]["tokens"]
OPERATION_BY_CODE = {
    # const of the registered metacontract.schema.json:/$defs/pre_execution_result branch per preflight code
    "MISSING_EXTERNAL_PROFILE_SCHEMA": "READ_PROFILE_SCHEMA_ID_BYTES_AND_EXPECTED_DIGEST",
    "EXTERNAL_PROFILE_SCHEMA_DIGEST_INVALID": "VALIDATE_EXPECTED_PROFILE_SCHEMA_SHA256_FORMAT",
    "INVALID_EXTERNAL_PROFILE_SCHEMA": "VALIDATE_PROFILE_SCHEMA_ID_DIALECT_AND_DRAFT",
    "EXTERNAL_PROFILE_SCHEMA_DIGEST_MISMATCH": "VERIFY_PROFILE_SCHEMA_RAW_SHA256",
    "MISSING_EXTERNAL_ACCEPTANCE_PROFILE": "READ_PROFILE",
    "INVALID_EXTERNAL_ACCEPTANCE_PROFILE": "VALIDATE_PROFILE_SCHEMA",
    "EXTERNAL_FROZEN_R5R2_CONTENT_MISMATCH": "VERIFY_FROZEN_R5R2_CONTENT",
    "EXTERNAL_FROZEN_R5R3_CONTENT_MISMATCH": "VERIFY_FROZEN_R5R3_CONTENT",
    "EXTERNAL_ACCEPTED_BASE_CONTENT_MISMATCH": "VERIFY_ACCEPTED_BASE_CONTENT",
    "EXTERNAL_ACCEPTED_VECTOR_CONTENT_MISMATCH": "VERIFY_ACCEPTED_VECTOR_CONTENT",
    "METACONTRACT_R5R2_PIN_CLAIM_MISMATCH": "COMPARE_R5R2_PIN_CLAIM",
    "METACONTRACT_R5R3_PIN_CLAIM_MISMATCH": "COMPARE_R5R3_PIN_CLAIM",
    "METACONTRACT_ACCEPTED_ALLOWLIST_CLAIM_MISMATCH": "COMPARE_ACCEPTED_ALLOWLIST_CLAIM",
    "METACONTRACT_PROJECTION_CLAIM_MISMATCH": "COMPARE_METACONTRACT_PROJECTION_CLAIM",
    "PROCEDURE_PROJECTION_CLAIM_MISMATCH": "COMPARE_PROCEDURE_PROJECTION_CLAIMS",
}


def bounded_json_number(token: str) -> int | decimal.Decimal:
    limits = PC["json_number_resource_limits"]
    significand, separator, exponent_text = token.lower().partition("e")
    digits = significand.lstrip("-").replace(".", "")
    exponent_field_digits = exponent_text.lstrip("+-")
    exponent_digits = exponent_field_digits.lstrip("0") or "0"
    if len(digits) > limits["maximum_significand_digits"] or (separator and
        (len(exponent_field_digits) > limits["maximum_exponent_field_digits"]
         or len(exponent_digits) > len(str(limits["maximum_absolute_decimal_exponent"]))
         or int(exponent_digits) > limits["maximum_absolute_decimal_exponent"])):
        raise ValueError(limits["exceeded_error"])
    return decimal.Decimal(token) if "." in significand or separator else exact_json_integer(token)


def _utf16_key(text: str) -> bytes:
    return text.encode("utf-16-be", "surrogatepass")


def _path_key(tokens: Sequence[Any]) -> tuple[Any, ...]:
    # DESCENDANTS canonical preorder: an ancestor precedes its descendants, array
    # elements ascend by index, object members ascend by UTF-16 code-unit key.
    return tuple((0, token, b"") if isinstance(token, int) and not isinstance(token, bool)
                 else (1, 0, _utf16_key(str(token))) for token in tokens)


def _first_location(paths: Iterable[Sequence[Any]]) -> tuple[Any, ...] | None:
    best: tuple[Any, ...] | None = None
    best_key: tuple[Any, ...] | None = None
    for path in paths:
        key = _path_key(path)
        if best_key is None or key < best_key:
            best, best_key = tuple(path), key
    return best


def _pointer_of(tokens: Sequence[Any]) -> str:
    return pointer_from_tokens([str(token) for token in tokens])


def _typed_identity(value: Any) -> dict[str, str] | None:
    # TYPED_IDENTITY_WHEN_VALID_ELSE_NULL: kind, id and version each exist, are JSON strings and are non-empty.
    if not isinstance(value, Mapping):
        return None
    parts = [value.get(name) for name in ("kind", "id", "version")]
    if any(not isinstance(part, str) or not part for part in parts):
        return None
    return {"kind": parts[0], "id": parts[1], "version": parts[2]}


def _identity_triple(value: Any) -> tuple[str, str, str] | None:
    ident = _typed_identity(value)
    return None if ident is None else (ident["kind"], ident["id"], ident["version"])


def _json_type_token(value: Any, present: bool = True) -> str:
    # closed_vocabularies.json_type: exactly one token per JSON value (ABSENT for an absent member).
    if not present:
        return "ABSENT"
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "BOOLEAN"
    if isinstance(value, str):
        return "STRING"
    if isinstance(value, dict):
        return "OBJECT"
    if isinstance(value, (list, tuple)):
        return "ARRAY"
    if isinstance(value, int):
        return "INTEGER"
    if isinstance(value, (float, decimal.Decimal)):
        number = decimal.Decimal(value) if isinstance(value, float) else value
        return "INTEGER" if number.is_finite() and number == number.to_integral_value() else "NUMBER"
    return "NUMBER"


def _json_type_satisfies(token: str, required: str) -> bool:
    return token == required or (required == "NUMBER" and token == "INTEGER")


def _json_equal_pe(left: Any, right: Any) -> bool:
    try:
        return _json_equal(left, right)
    except ExpressionError:
        return False


def _resolve_pointer(document: Any, pointer: str) -> tuple[bool, Any]:
    """RFC6901 lookup that reports absence instead of raising."""
    try:
        tokens = parse_pointer(pointer)
    except ExpressionError:
        return False, None
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return False, None
            current = current[token]
        elif isinstance(current, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", token) or int(token) >= len(current):
                return False, None
            current = current[int(token)]
        else:
            return False, None
    return True, current


def _canonical_relpath(rel: Any) -> bool:
    if not isinstance(rel, str) or not rel or "\\" in rel or rel.startswith("/") or re.match(r"^[A-Za-z]:", rel):
        return False
    return not any(part in ("", ".", "..") for part in rel.split("/"))


def _read_under_root(root: Path | None, rel: Any) -> tuple[str, bytes | None]:
    """('OK', bytes) | ('NOT_CANONICAL'|'OUTSIDE_ROOT'|'UNREADABLE', None) for a root-relative path."""
    if not _canonical_relpath(rel) or root is None:
        return ("NOT_CANONICAL" if not _canonical_relpath(rel) else "UNREADABLE"), None
    try:
        base = root.resolve()
        resolved = base.joinpath(*rel.split("/")).resolve()
        resolved.relative_to(base)
    except ValueError:
        return "OUTSIDE_ROOT", None
    except (OSError, RuntimeError):
        return "UNREADABLE", None
    try:
        return "OK", resolved.read_bytes()
    except (OSError, ValueError):
        return "UNREADABLE", None


class _NumberLimit(Exception):
    pass


def _decode_json_classified(raw: bytes) -> tuple[Any, str | None]:
    """Strict candidate JSON decoding. Returns (value, None) or (None, tag) where tag is the first failing
    condition in declared rank order: INVALID_UTF8, JSON_SYNTAX, NUMBER_LIMIT, DUPLICATE_NAME."""
    try:
        text = raw.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        return None, "INVALID_UTF8"

    def no_constant(_: str) -> None:
        raise ValueError("non-JSON numeric constant")

    def limited(token: str) -> Any:
        try:
            return bounded_json_number(token)
        except ValueError as exc:
            raise _NumberLimit() from exc

    try:
        json.loads(text, parse_int=lambda _: 0, parse_float=lambda _: 0.0, parse_constant=no_constant)
    except (json.JSONDecodeError, ValueError, RecursionError):
        return None, "JSON_SYNTAX"
    try:
        json.loads(text, parse_int=limited, parse_float=limited, parse_constant=no_constant)
    except _NumberLimit:
        return None, "NUMBER_LIMIT"
    try:
        return json.loads(text, object_pairs_hook=reject_duplicate_pairs, parse_int=limited, parse_float=limited,
                          parse_constant=no_constant), None
    except DuplicateJSONName:
        return None, "DUPLICATE_NAME"
    except (json.JSONDecodeError, ValueError, RecursionError):
        return None, "JSON_SYNTAX"


def _strict_value(raw: bytes) -> tuple[bool, Any]:
    value, tag = _decode_json_classified(raw)
    return tag is None, value


def _first_uncanonicalizable_number(value: Any, tokens: tuple[Any, ...] = ()) -> tuple[Any, ...] | None:
    """First number in DESCENDANTS canonical preorder that RFC8785 cannot serialize."""
    pending: list[tuple[Any, Any]] = [(value, None)]
    while pending:
        current, path = pending.pop()
        if isinstance(current, bool) or current is None or isinstance(current, str):
            continue
        if isinstance(current, (int, float, decimal.Decimal)):
            try:
                jcs(current)
            except ExpressionError:
                suffix = []
                while path is not None:
                    path, token = path
                    suffix.append(token)
                return tokens + tuple(reversed(suffix))
            continue
        if isinstance(current, dict):
            for key in sorted(current, key=_utf16_key, reverse=True):
                pending.append((current[key], (path, key)))
        elif isinstance(current, list):
            for index in range(len(current) - 1, -1, -1):
                pending.append((current[index], (path, index)))
    return None

def _digest_or_none(value: Any) -> str | None:
    try:
        return sha256(jcs(value))
    except ExpressionError:
        return None


def _is_sha256_hex(value: Any) -> bool:
    return isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value) is not None


def _decode_base64_strict(value: Any) -> bytes | None:
    if not isinstance(value, str):
        return None
    try:
        return base64.b64decode(value.encode("ascii"), validate=True)
    except (UnicodeEncodeError, binascii.Error, ValueError):
        return None

@dataclass
class CandidateInputs:
    root: Path
    package_relpath: str
    registry_relpath: str
    package: dict[str, Any]
    package_raw: bytes
    object_registry: dict[str, Any]
    registry_raw: bytes
    profile: dict[str, Any]
    profile_schema: dict[str, Any]
    profile_schema_raw: bytes
    trust_input: dict[str, Any]
    trust_result: dict[str, Any]
    candidate_objects: tuple[ResolvedObject, ...] = ()
    bound_source_objects: tuple[ResolvedObject, ...] = ()
    universe: VerificationUniverse | None = None
    pre_execution: dict[str, Any] | None = None
    metacontract: dict[str, Any] | None = None
    package_object: ResolvedObject | None = None
    registry_object: ResolvedObject | None = None
    registration_contract: Any = None



# ---------------------------------------------------------------------------
# Pre-execution failure engine. A predicate detects a failure of one declared
# family condition and raises PreFail(family_id, condition_id, subject, ...);
# the emitted result is built only from the committed model: the family code,
# the condition's failure_kind or reason, its fixed diagnostic and every witness
# field through the model's derivation vocabulary. No predicate writes a result.
# ---------------------------------------------------------------------------
class PreFail(Exception):
    def __init__(self, family_id: str, condition_id: str, subject: Mapping[str, Any] | None = None, **extra: Any):
        super().__init__(f"{family_id}/{condition_id}")
        self.family_id = family_id
        self.condition_id = condition_id
        self.subject = dict(subject or {})
        self.extra = extra


class Ctx:
    """Derivation context of one failure."""

    def __init__(self, run: "Run", fail: PreFail):
        self.run = run
        self.fail = fail
        self.fam = FAMILIES[fail.family_id]
        self.cond = CONDITIONS[fail.family_id][fail.condition_id]
        self.subject = fail.subject
        self.extra = fail.extra

    @property
    def subject_class(self) -> str | None:
        return self.subject.get("cls")

    @property
    def case(self) -> str | None:
        return self.extra.get("case")

    @property
    def owning(self) -> str:
        owning = self.cond.get("owning_object", self.fam.get("owning_object"))
        if owning == "BINDING_DECLARING_OBJECT" or isinstance(owning, dict):
            return self.fam["owning_object"]["by_binding_site"][self.subject["site_kind"]]
        return owning

    def row_pointer(self, template: str) -> str:
        pointer = template
        for placeholder, key in (("<row_index>", "row_index"), ("<second_occurrence_index>", "second_index"),
                                 ("<member_index>", "member_index"), ("<k>", "k")):
            if placeholder in pointer:
                pointer = pointer.replace(placeholder, str(self.extra.get(key, self.subject.get(key))))
        return pointer


_DERIVE: dict[tuple[str, str], Callable[[Ctx], Any]] = {}


def _derive(field: str, token: str) -> Callable[[Callable[[Ctx], Any]], Callable[[Ctx], Any]]:
    def register(function: Callable[[Ctx], Any]) -> Callable[[Ctx], Any]:
        _DERIVE[(field, token)] = function
        return function
    return register


def _field_value(ctx: Ctx, field: str, rule: Mapping[str, Any]) -> Any:
    if "derivation" in rule:
        token = rule["derivation"]
        entry = VOCAB[field][token]
        if "constant_value" in entry:
            return copy.deepcopy(entry["constant_value"])
        value = _DERIVE[(field, token)](ctx)
        _check_value_type(entry["value_type"], value, f"{field}/{token}")
        return value
    if "constant" in rule:
        return copy.deepcopy(rule["constant"])
    if "by_subject_class" in rule:
        return _field_value(ctx, field, rule["by_subject_class"][ctx.subject_class])
    if "by_case" in rule:
        return _field_value(ctx, field, rule["by_case"][ctx.case])
    raise RuntimeError(f"unsupported witness field rule for {field}")


def _check_value_type(value_type: str, value: Any, where: str) -> None:
    def nonempty(v: Any) -> bool:
        return isinstance(v, str) and bool(v)

    def typed(v: Any) -> bool:
        return isinstance(v, dict) and set(v) == {"kind", "id", "version"} and all(nonempty(x) for x in v.values())

    def integer(v: Any) -> bool:
        return isinstance(v, int) and not isinstance(v, bool)

    ok = {
        "IDENTITY3": lambda v: isinstance(v, dict) and set(v) == {"id", "version", "digest"} and _is_sha256_hex(v["digest"])
                     and nonempty(v["id"]) and nonempty(v["version"]),
        "ID_VERSION": lambda v: isinstance(v, dict) and set(v) == {"id", "version"} and nonempty(v["id"]) and nonempty(v["version"]),
        "JSON_TYPE_TOKEN": lambda v: v in JSON_TYPE_TOKENS,
        "JSON_VALUE": lambda v: True,
        "JSON_VALUE_OR_NULL": lambda v: True,
        "NONEMPTY_STRING": nonempty,
        "NONEMPTY_STRING_OR_NULL": lambda v: v is None or nonempty(v),
        "NONNEGATIVE_INTEGER": lambda v: integer(v) and v >= 0,
        "NULL": lambda v: v is None,
        "POSITIVE_INTEGER": lambda v: integer(v) and v > 0,
        "RFC6901_POINTER": lambda v: isinstance(v, str) and re.fullmatch(r"(?:/(?:[^~/]|~[01])*)*", v) is not None,
        "RFC6901_POINTER_OR_NULL": lambda v: v is None or (isinstance(v, str) and re.fullmatch(r"(?:/(?:[^~/]|~[01])*)*", v) is not None),
        "STRING_ARRAY": lambda v: isinstance(v, list) and all(isinstance(x, str) for x in v),
        "TOKEN": nonempty,
        "TRUST_FIELD_NAME_ARRAY": lambda v: isinstance(v, list) and bool(v) and len(set(v)) == len(v)
                                  and all(x in ("expected_package_id", "expected_package_version", "expected_package_digest") for x in v),
        "TYPED_IDENTITY": typed,
        "TYPED_IDENTITY_OR_NULL": lambda v: v is None or typed(v),
    }[value_type]
    if not ok(value):
        raise RuntimeError(f"derived witness value violates {value_type} at {where}")


def _family_code(ctx: Ctx) -> str:
    fam = ctx.fam
    if "code" in fam:
        return fam["code"]
    derivation = fam["code_derivation"]
    if "BY_SUBJECT" in derivation:
        return CLAIMS[ctx.subject["claim_index"]]["failure_code"]
    if ctx.fam["family_id"] == "PE-17":
        return derivation["SOURCE_VECTOR_CATALOG"] if ctx.subject["allow_kind"] == "SOURCE_VECTOR_CATALOG" else derivation["OTHERWISE"]
    return derivation[ctx.cond["condition_id"]]


def _condition_reason(ctx: Ctx) -> str:
    reason = ctx.cond["reason"]
    if isinstance(reason, str):
        return reason
    if "by_case" in reason:
        return reason["by_case"][ctx.case]
    return reason["by_claim_index"].get(str(ctx.subject["claim_index"]), reason["otherwise"])


_STAGE = "PRE_EXECUTION"


def _prefail_result(run: "Run", fail: PreFail) -> tuple[dict[str, Any], bool]:
    """Build the registered result of a failure from the committed model. The flag marks trust results."""
    ctx = Ctx(run, fail)
    fam, cond = ctx.fam, ctx.cond
    contract_name = fam["witness_contract"]
    contract = MODEL["witness_contracts"][contract_name]
    code = _family_code(ctx)
    if contract_name == "TRUST_RESULT":
        witness = {field: _field_value(ctx, "trust_result", rule) for field, rule in cond["witness"].items()}
        return {"status": "FAIL", "code": code, "witness": witness}, True
    if contract_name in ("SEVEN_FIELD", "STATIC_VALIDATION"):
        rules = cond["witness"]
        witness = {
            "argument": _field_value(ctx, "argument", rules["argument"]),
            "object_role": _field_value(ctx, "object_role", rules["object_role"]),
            "schema_ref": _field_value(ctx, "schema_ref", rules["schema_ref"]),
            "instance_pointer": _field_value(ctx, "instance_pointer", rules["instance_pointer"]),
            "failure_kind": cond["failure_kind"],
            "diagnostic": cond["diagnostic"],
            "bound_identity": _field_value(ctx, "bound_identity", rules["bound_identity"]),
        }
        assert list(witness) == contract["fields"]
    elif contract_name == "PROFILE_PREFLIGHT":
        rules = cond["witness"]
        witness = {"operation": OPERATION_BY_CODE[code]}
        for field in ("profile_pointer", "candidate_artifact", "candidate_pointer", "source_identity", "expected", "actual"):
            witness[field] = _field_value(ctx, field, rules[field])
        witness["reason"] = _condition_reason(ctx)
        witness["diagnostic"] = cond["diagnostic"]
        assert list(witness) == contract["fields"]
    elif contract_name == "MAP_VALUE_COMPARISON":
        rules = cond["witness"]
        witness = {"stage": rules["stage"]["constant"]}
        for field in ("procedure_id", "map_argument", "map_pointer", "baseline_argument", "baseline_identity", "expected", "actual"):
            witness[field] = _field_value(ctx, "map_value_comparison", rules[field])
        witness["reason"] = cond["reason"]
    elif contract_name == "STRICT_UNION_COLLISION":
        witness = ctx.extra["witness"]
    elif contract_name == "VECTOR_REGISTRY_CLAIM":
        witness = ctx.extra["witness"]
    else:
        raise RuntimeError(f"unsupported witness contract {contract_name}")
    return {"status": "FAIL", "stage": _STAGE, "code": code, "witness": witness}, False


class Run:
    """Mutable state of one verification run; each stage only reads what earlier stages produced."""

    def __init__(self, args: argparse.Namespace):
        self.args = args
        self.root: Path | None = None
        self.entries: dict[str, dict[str, Any]] = {}
        self.trust: dict[str, Any] = {}
        self.schema_id: Any = None
        self.schema_path: Any = None
        self.schema_sha: Any = None
        self.schema_raw: bytes | None = None
        self.schema: Any = None
        self.profile_path: Any = None
        self.profile_raw: bytes | None = None
        self.profile: Any = None
        self.profile_decoded: Any = None
        self.registry_schema: Any = None
        self.package: Any = None
        self.registry: Any = None
        self.package_digest: str | None = None
        self.frozen_bytes: dict[str, bytes] = {}
        self.frozen_objects: dict[str, ResolvedObject] = {}
        self.accepted_objects: list[ResolvedObject] = []
        self.accepted_content: dict[int, tuple[bytes, Any]] = {}
        self.file_cache: dict[str, tuple[str, Any]] = {}
        self.claim_cache: dict[str, tuple[str, Any]] = {}
        self.metacontract: Any = None
        self.schema_documents: dict[str, Any] = {}
        self.candidate_rows: list[tuple[int, dict[str, Any]]] = []
        self.candidate_objects: dict[int, ResolvedObject] = {}
        self.universe: VerificationUniverse | None = None
        self.universe_view: Any = None
        self.registration_contract: Any = None
        self.documents: dict[str, Any] = {}

    # ---- registry helpers -------------------------------------------------
    def rows(self) -> list[Any]:
        registry = self.registry
        objects = registry.get("objects") if isinstance(registry, dict) else None
        return objects if isinstance(objects, list) else []

    def find_rows(self, triple: tuple[str, str, str] | None) -> list[tuple[int, dict[str, Any]]]:
        if triple is None:
            return []
        return [(i, row) for i, row in enumerate(self.rows())
                if isinstance(row, dict) and (row.get("kind"), row.get("id"), row.get("version")) == triple]

    def schema_row(self, ref: Any) -> dict[str, Any] | None:
        triple = _identity_triple(ref)
        matches = [row for _, row in self.find_rows(triple) if row.get("kind") == "SCHEMA"] if triple else []
        return matches[0] if len(matches) == 1 else None

    def package_reference(self, member: str | None) -> Any:
        if member is None:
            return None
        return self.package.get(member) if isinstance(self.package, dict) else None

    def owning_row(self, owning: str) -> dict[str, Any] | None:
        spec = BOOTSTRAP_SPECS[owning]
        for ref in (self.package_reference(spec["package_member"]), spec["identity"]):
            rows = self.find_rows(_identity_triple(ref))
            if len(rows) == 1:
                return rows[0][1]
        return None

    def row_content(self, row: Mapping[str, Any]) -> tuple[str, Any]:
        """Content of a registry row: ('OK', value) or (failure tag, None); cached by path."""
        rel = row.get("path")
        key = rel if isinstance(rel, str) else repr(rel)
        if key not in self.file_cache:
            status, raw = _read_under_root(self.root, rel)
            if status != "OK":
                self.file_cache[key] = (status, None)
            else:
                value, tag = _decode_json_classified(raw)
                self.file_cache[key] = ("OK", (raw, value)) if tag is None else (tag, None)
        status, payload = self.file_cache[key]
        return (status, payload[1] if status == "OK" else None)

    def row_raw(self, row: Mapping[str, Any]) -> bytes | None:
        status, payload = self.file_cache.get(row.get("path") if isinstance(row.get("path"), str) else repr(row.get("path")), ("", None))
        return payload[0] if status == "OK" else None

    def entry_identity(self, spec: Mapping[str, Any]) -> dict[str, str] | None:
        """ENTRYPOINT_CONTENT_IDENTITY_WHEN_VALID_ELSE_NULL."""
        content = self.package if spec["registered_kind"] == "PACKAGE" else self.registry
        if not isinstance(content, dict):
            return None
        members = PACKAGE_IDENTITY_MEMBERS if spec["registered_kind"] == "PACKAGE" else ("object_id", "object_version")
        return _typed_identity({"kind": spec["registered_kind"], "id": content.get(members[0]), "version": content.get(members[1])})

    def caller_input(self, input_name: str) -> Any:
        name = input_name[2:] if input_name.startswith("--") else input_name
        return getattr(self.args, name.replace("-", "_"), None)


def _row_identity(row: Any) -> dict[str, str] | None:
    return _typed_identity(row) if isinstance(row, Mapping) else None


def _schema_document_id(run: Run, ref: Any) -> str:
    row = run.schema_row(ref)
    value = row.get("schema_document_id") if isinstance(row, dict) else None
    if not isinstance(value, str) or not value:
        raise RuntimeError("schema row named by the registered schema_ref has no schema_document_id")
    return value


def _substitute(template: str, **values: Any) -> str:
    pointer = template
    for key, value in values.items():
        pointer = pointer.replace("<" + key + ">", str(value))
    return pointer


def _escape_token(token: Any) -> str:
    return str(token).replace("~", "~0").replace("/", "~1")


def _first_error_pointer(errors: Sequence[Any], prefix: Sequence[Any] = ()) -> str:
    location = _first_location(tuple(error.absolute_path) for error in errors)
    return _pointer_of(tuple(prefix) + (location or ()))


# ---- derivation vocabulary: one implementation per token ----------------------------------
# argument
@_derive("argument", "ENTRYPOINT_ARGUMENT")
def _d_argument_entry(c: Ctx) -> Any:
    return c.subject["spec"]["argument"]


@_derive("argument", "OWNING_BOOTSTRAP_OBJECT_ARGUMENT")
def _d_argument_owning(c: Ctx) -> Any:
    return BOOTSTRAP_SPECS[c.owning]["argument"]


@_derive("argument", "RESERVED_INPUT_NAME")
def _d_argument_reserved(c: Ctx) -> Any:
    return c.subject["reserved"]["name"]


@_derive("argument", "REGISTRATION_WITNESS_ARGUMENT")
def _d_argument_registration(c: Ctx) -> Any:
    return REG["witness_contract"]["argument"]


# object_role
@_derive("object_role", "REGISTERED_KIND_OF_FAILING_OBJECT")
def _d_role_failing(c: Ctx) -> Any:
    return c.subject["row"]["kind"]


@_derive("object_role", "ENTRYPOINT_KIND")
def _d_role_entry(c: Ctx) -> Any:
    return c.subject["spec"]["registered_kind"]


@_derive("object_role", "REGISTERED_KIND_OF_OWNING_OBJECT")
def _d_role_owning_kind(c: Ctx) -> Any:
    return BOOTSTRAP_SPECS[c.owning]["registered_kind"]


@_derive("object_role", "RESERVED_INPUT_DECLARED_TYPE")
def _d_role_reserved(c: Ctx) -> Any:
    return c.subject["reserved"]["type"]


@_derive("object_role", "REGISTRATION_WITNESS_OBJECT_ROLE")
def _d_role_registration(c: Ctx) -> Any:
    return REG["witness_contract"]["object_role"]


@_derive("object_role", "OWNING_OBJECT_REGISTRY_ROW_KIND")
def _d_role_owning_row(c: Ctx) -> Any:
    row = c.run.owning_row(c.owning)
    return row["kind"] if row is not None else BOOTSTRAP_SPECS[c.owning]["registered_kind"]


@_derive("object_role", "ALLOWLIST_REF_KIND")
def _d_role_allow_kind(c: Ctx) -> Any:
    return c.subject["allow"]["ref"]["kind"]


# schema_ref
@_derive("schema_ref", "APPLIED_SCHEMA_ROW_SCHEMA_DOCUMENT_ID")
def _d_schema_applied(c: Ctx) -> Any:
    return _schema_document_id(c.run, c.subject["row"].get("schema_ref"))


@_derive("schema_ref", "ENTRYPOINT_SCHEMA_DOCUMENT_ID")
def _d_schema_entry(c: Ctx) -> Any:
    return c.subject["spec"]["schema_document_id"]


@_derive("schema_ref", "OWNING_OBJECT_SCHEMA_DOCUMENT_ID")
def _d_schema_owning(c: Ctx) -> Any:
    return BOOTSTRAP_SPECS[c.owning]["schema_document_id"]


@_derive("schema_ref", "PRODUCER_SCHEMA_ROW_SCHEMA_DOCUMENT_ID")
def _d_schema_producer(c: Ctx) -> Any:
    return _schema_document_id(c.run, c.subject["reserved"]["profile_content_source"]["producer_schema_ref"])


@_derive("schema_ref", "DRAFT_2020_12_METASCHEMA")
def _d_schema_dialect(c: Ctx) -> Any:
    return PC["draft_2020_12_dialect"]


@_derive("schema_ref", "RUNTIME_VALUE_SCHEMA_ID")
def _d_schema_runtime(c: Ctx) -> Any:
    return c.subject["value_schema_id"]


@_derive("schema_ref", "REGISTRATION_WITNESS_SCHEMA_REF")
def _d_schema_registration(c: Ctx) -> Any:
    return REG["witness_contract"]["schema_ref"]


@_derive("schema_ref", "STRUCTURAL_APPLICATION_SCHEMA_DOCUMENT_ID")
def _d_schema_structural(c: Ctx) -> Any:
    return REG["structural_application"]["schema_id"]


@_derive("schema_ref", "OWNING_OBJECT_APPLIED_SCHEMA_ROW_SCHEMA_DOCUMENT_ID")
def _d_schema_owning_applied(c: Ctx) -> Any:
    row = c.run.owning_row(c.owning)
    if row is not None and run_has_schema(c.run, row):
        return _schema_document_id(c.run, row.get("schema_ref"))
    return BOOTSTRAP_SPECS[c.owning]["schema_document_id"]


def run_has_schema(run: Run, row: Mapping[str, Any]) -> bool:
    return run.schema_row(row.get("schema_ref")) is not None


@_derive("schema_ref", "ALLOWLIST_EXPECTED_SCHEMA_ROW_SCHEMA_DOCUMENT_ID")
def _d_schema_allow_expected(c: Ctx) -> Any:
    return _schema_document_id(c.run, c.subject["allow"].get("expected_schema_ref"))


