for _cid, _tag in (("OBJECT_INVALID_UTF8", "INVALID_UTF8"), ("OBJECT_JSON_SYNTAX", "JSON_SYNTAX"),
                   ("OBJECT_NUMBER_LIMIT", "NUMBER_LIMIT"), ("OBJECT_DUPLICATE_NAME", "DUPLICATE_NAME")):
    _PRED[("PE-31", _cid)] = (lambda tag: lambda run, subject: {} if run.row_content(subject["row"])[0] == tag else None)(_tag)


@_pred("PE-32", "OBJECT_NOT_JSON_OBJECT")
def _pe32(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    status, content = run.row_content(subject["row"])
    return {} if status == "OK" and not isinstance(content, dict) else None


# ---- stage 19: bound-source resolved construction (accepted vector source registry claim) ---------
def _utf16_sorted_unique(values: Iterable[str]) -> list[str]:
    return sorted(set(values), key=_utf16_key)


def _duplicates(values: Sequence[str]) -> list[str]:
    return _utf16_sorted_unique(v for v in values if list(values).count(v) > 1)


@_subjects("PE-34")
def _pe34_subjects(run: Run) -> list[dict[str, Any]]:
    subjects = []
    for index, allow in enumerate(run.profile["accepted_source_allowlist"]):
        ref = allow.get("ref") if isinstance(allow, dict) else None
        if isinstance(ref, dict) and ref.get("kind") == "SOURCE_VECTOR_CATALOG":
            subjects.append({"cls": "BOUND_VECTOR_SOURCE", "allow_index": index, "allow": allow})
    return subjects


def _vector_claim(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    """First matching reason of bound_source_resolved_construction.member_relation.failure_ordering."""
    allow = subject["allow"]
    ref = allow["ref"]
    key = {name: ref.get(name) for name in ("kind", "id", "version")}
    matches = [row for row in run.rows() if isinstance(row, dict) and isinstance(row.get("reference"), dict)
               and all(row["reference"].get(name) == key[name] for name in key)]
    witness: dict[str, Any] = {"source_kind": ref.get("kind"), "source_id": ref.get("id"), "source_version": ref.get("version"),
                               "source_origin": "BOUND_SOURCE_UNIVERSE", "source_path": allow.get("canonical_path"),
                               "registry_claim_key": key, "match_count": len(matches), "reason": None,
                               "diagnostic": REG["bound_source_resolved_construction"]["diagnostic"]}
    order = REG["bound_source_resolved_construction"]["member_relation"]["failure_ordering"]
    if not matches:
        witness["reason"] = order[0]
        return witness
    claim = matches[0].get("members")
    if not isinstance(claim, list) or any(not isinstance(v, str) or not v for v in claim):
        witness["reason"] = order[1]
        return witness
    if len(set(claim)) != len(claim):
        witness["reason"] = order[2]
        witness["duplicate_member_ids"] = _duplicates(claim)
        return witness
    content = _decode_json_classified(run.accepted_content[subject["allow_index"]][0])[0]
    vectors = content.get("vectors") if isinstance(content, dict) else None
    derived = None
    if isinstance(vectors, list) and all(isinstance(v, dict) and isinstance(v.get("vector_id"), str) and v["vector_id"] for v in vectors):
        derived = [v["vector_id"] for v in vectors]
    if derived is None:
        witness["reason"] = order[3]
        return witness
    if len(set(derived)) != len(derived):
        witness["reason"] = order[4]
        witness["duplicate_member_ids"] = _duplicates(derived)
        return witness
    if set(derived) != set(claim):
        witness["reason"] = order[5]
        witness["missing_member_ids"] = _utf16_sorted_unique(set(derived) - set(claim))
        witness["extra_member_ids"] = _utf16_sorted_unique(set(claim) - set(derived))
        return witness
    return None


@_pred("PE-34", "VECTOR_REGISTRY_CLAIM_INVALID")
def _pe34(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    witness = _vector_claim(run, subject)
    return None if witness is None else {"witness": witness}

# Schema-member binding declaration of the candidate metacontract (resolved_construction.schema_member_binding).
_MEMBER_BINDING_ID = "EXPLICIT_REGISTERED_SCHEMA_MEMBER"
_MEMBER_BINDING_SELECTION_ORDER = [
    "RESOLVE_THE_EXACT_OWNER_KIND_ID_VERSION_IN_THE_EXPLICIT_VERIFICATION_UNIVERSE",
    "IF_member_id_IS_ABSENT_RETURN_THE_BASE_RESOLVED_OBJECT",
    "REQUIRE_EXACTLY_ONE_EQUAL_STRING_IN_THE_RESOLVED_OBJECT_REGISTERED_members",
    "BIND_THE_SELECTED_MEMBER_TO_THE_CONSTRUCTED_ROOT_DEFS_POINTER_IN_THE_SAME_RESOLVED_CONTENT",
]
_METACONTRACT_REF_PREFIX = "metacontract:"
_REGISTRATION_CONTENT_ABSENT = object()

def _registration_pointer_tokens(pointer: Any) -> list[str] | None:
    # RFC6901 unescaping of the declared content-member pointer: no local
    # convention and no fallback member name.
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        return None
    return [token.replace("~1", "/").replace("~0", "~") for token in pointer[1:].split("/")]


def _registration_pointer_text(tokens: Sequence[str]) -> str:
    # RFC6901 serialization of the same declared content-member pointer.
    return "/" + "/".join(token.replace("~", "~0").replace("/", "~1") for token in tokens)


def _registration_pointer_value(document: Any, tokens: Sequence[str]) -> Any:
    value = document
    for token in tokens:
        if not isinstance(value, Mapping) or token not in value:
            return _REGISTRATION_CONTENT_ABSENT
        value = value[token]
    return value


class _SchemaMemberBinding:
    """Parsed metacontract:/runtime_representation/resolved_construction/schema_member_binding.

    The local target of a registered SCHEMA member is the RFC6901 pointer
    assembled from the declared reference-token sequence, where the MEMBER_ID
    token is the registered member_id itself. Registration is checked by the
    caller (RESOLVE_ONE semantics or the registered members array); this object
    only constructs and follows the declared pointer, never a raw $defs name.
    """
    __slots__ = ("binding_ref", "owner_kind", "reference_tokens")

    def __init__(self, binding_ref: str, owner_kind: str, reference_tokens: tuple[tuple[str, str | None], ...]) -> None:
        self.binding_ref = binding_ref
        self.owner_kind = owner_kind
        self.reference_tokens = reference_tokens

    def pointer(self, member_id: str) -> str:
        tokens = [member_id if source == "MEMBER_ID" else str(value) for source, value in self.reference_tokens]
        return _registration_pointer_text(tokens)

    def target(self, content: Any, member_id: Any) -> Any:
        if not isinstance(member_id, str) or not member_id:
            return _REGISTRATION_CONTENT_ABSENT
        tokens = [member_id if source == "MEMBER_ID" else str(value) for source, value in self.reference_tokens]
        return _registration_pointer_value(content, tokens)


def _metacontract_pointer_value(metacontract: Mapping[str, Any], declared_ref: Any) -> Any:
    # A declaration reference of the form "metacontract:<RFC6901 pointer>" is
    # resolved inside the same registered metacontract document only.
    if not isinstance(declared_ref, str) or not declared_ref.startswith(_METACONTRACT_REF_PREFIX):
        return _REGISTRATION_CONTENT_ABSENT
    tokens = _registration_pointer_tokens(declared_ref[len(_METACONTRACT_REF_PREFIX):])
    if tokens is None:
        return _REGISTRATION_CONTENT_ABSENT
    return _registration_pointer_value(metacontract, tokens)


def _parse_schema_member_binding(metacontract: Mapping[str, Any], binding_ref: Any) -> _SchemaMemberBinding:
    declared = _metacontract_pointer_value(metacontract, binding_ref)
    if not isinstance(declared, Mapping):
        raise _registration_unsupported()
    construction = declared.get("definition_pointer_construction")
    owner_kind = declared.get("applies_to_registry_kind")
    if (declared.get("binding_id") != _MEMBER_BINDING_ID
            or not isinstance(owner_kind, str) or not owner_kind
            or declared.get("member_id_domain") != "NONEMPTY_JSON_STRING"
            or declared.get("member_id_to_definition_name") != "EXACT_JSON_STRING_EQUALITY"
            or declared.get("absent_members") != "EMPTY_REGISTERED_MEMBER_SET"
            or declared.get("nested_definitions_eligible") is not False
            or declared.get("non_defs_locations_eligible") is not False
            or declared.get("raw_local_defs_lookup_without_registration") != "FORBIDDEN"
            or declared.get("member_inference_from_names_suffixes_or_patterns") != "FORBIDDEN"
            or declared.get("selection_order") != _MEMBER_BINDING_SELECTION_ORDER
            or not isinstance(construction, Mapping)
            or construction.get("pointer_standard") != "RFC6901"
            or construction.get("pointer_base") != "ROOT_OF_THE_DEFINITION_DOCUMENT"
            or construction.get("token_escaping") != "RFC6901_ENCODE_TILDE_AS_TILDE0_THEN_SLASH_AS_TILDE1"):
        raise _registration_unsupported()
    declared_tokens = construction.get("reference_tokens")
    if not isinstance(declared_tokens, list) or not declared_tokens:
        raise _registration_unsupported()
    reference_tokens: list[tuple[str, str | None]] = []
    for token in declared_tokens:
        if isinstance(token, Mapping) and token.get("source") == "LITERAL" and set(token) == {"source", "value"} \
                and isinstance(token.get("value"), str) and token["value"]:
            reference_tokens.append(("LITERAL", token["value"]))
        elif isinstance(token, Mapping) and token == {"source": "MEMBER_ID"}:
            reference_tokens.append(("MEMBER_ID", None))
        else:
            raise _registration_unsupported()
    # Exactly one member-id token, and it is the final token: a registered member
    # names one entry directly inside the declared literal container.
    if [source for source, _ in reference_tokens].count("MEMBER_ID") != 1 or reference_tokens[-1][0] != "MEMBER_ID":
        raise _registration_unsupported()
    return _SchemaMemberBinding(str(binding_ref), owner_kind, tuple(reference_tokens))




# ---- universe construction (used from stage 21 on) -------------------------------------------------
class _RegistrationContract:
    """Declared SCHEMA identity members and schema-member binding (registration section + candidate binding declaration)."""
    __slots__ = ("member_binding", "schema_content_id_tokens", "schema_content_id_pointer", "schema_document_id_member",
                 "row_version_member", "schema_document_version_member")


def _registration_unsupported() -> RuntimeError:
    return RuntimeError("unsupported schema member binding declaration")


def _ensure_registration_contract(run: Run) -> _RegistrationContract:
    if run.registration_contract is None:
        contract = _RegistrationContract()
        tokens = _registration_pointer_tokens(_SCHEMA_CONTENT_ID_POINTER) or []
        contract.schema_content_id_tokens = tuple(tokens)
        contract.schema_content_id_pointer = _registration_pointer_text(tokens)
        contract.schema_document_id_member = _SCHEMA_DOCUMENT_ID_MEMBER
        contract.schema_document_version_member = _SCHEMA_DOCUMENT_VERSION_MEMBER
        contract.row_version_member = _REGISTRY_IDENTITY_MEMBERS[-1]
        rule = next(r for r in REG["semantic_validation"]["rules"]
                    if r["rule_id"] == "SCHEMA_ROW_REGISTERED_MEMBERS_BIND_TO_ROOT_DEFS_ENTRIES")
        contract.member_binding = _parse_schema_member_binding(run.metacontract, rule["binding_ref"])
        run.registration_contract = contract
    return run.registration_contract


def _candidate_resolved_objects(run: Run) -> tuple[ResolvedObject, ...]:
    if not run.candidate_objects:
        for index, row in enumerate(run.rows()):
            if not _is_eligible(row):
                continue
            status, content = run.row_content(row)
            if status != "OK":
                raise RuntimeError("eligible candidate object is unreadable after RESOLVE_CANDIDATE_OBJECTS")
            run.candidate_objects[index] = ResolvedObject(dict(row["reference"]), row, content, run.row_raw(row), "CANDIDATE_UNIVERSE")
    return tuple(sorted(run.candidate_objects.values(), key=lambda o: identity_utf16_key(o.reference)))


def _accepted_content_value(run: Run, allow_index: int) -> tuple[bytes, Any]:
    raw = run.accepted_content[allow_index][0]
    return raw, _decode_json_classified(raw)[0]


def _bound_resolved_objects(run: Run) -> tuple[ResolvedObject, ...]:
    objects = []
    for index, allow in enumerate(run.profile["accepted_source_allowlist"]):
        ref = allow["ref"]
        raw, content = _accepted_content_value(run, index)
        members: list[str] = []
        if ref.get("kind") == "SOURCE_VECTOR_CATALOG" and isinstance(content, dict):
            members = _utf16_sorted_unique(v["vector_id"] for v in content.get("vectors", [])
                                           if isinstance(v, dict) and isinstance(v.get("vector_id"), str))
        registration = {
            "kind": ref.get("kind"), "id": ref.get("id"), "version": ref.get("version"), "reference": dict(ref),
            "path": allow.get("canonical_path"), "status": allow.get("status"), "classification": allow.get("classification"),
            "roles": allow.get("roles", []), "schema_ref": allow.get("expected_schema_ref"), "members": members,
            "integrity": {"mode": "DUAL_ACCEPTED_SOURCE", "algorithm": "SHA-256", "raw_sha256": sha256(raw),
                          "semantic_sha256": sha256(jcs(content)), "git_blob": git_blob(raw)},
        }
        schema_ref = allow.get("expected_schema_ref")
        schema = {"schema_ref": dict(schema_ref), "member_id": schema_ref["member_id"]} if isinstance(schema_ref, dict) and schema_ref.get("member_id") else None
        objects.append(ResolvedObject(dict(ref), registration, content, raw, "BOUND_SOURCE_UNIVERSE", schema))
    return tuple(objects)


def _candidate_universe(run: Run) -> VerificationUniverse:
    return VerificationUniverse(_candidate_resolved_objects(run))


def _full_universe(run: Run) -> VerificationUniverse:
    if run.universe is None:
        objects = (*_candidate_resolved_objects(run), *_bound_resolved_objects(run))
        run.universe = VerificationUniverse(tuple(sorted(objects, key=lambda o: identity_utf16_key(o.reference))))
        run.universe_view = run.universe.json_view()
    return run.universe


def _eligible_schema_row(run: Run, ref: Any) -> dict[str, Any] | None:
    triple = _identity_triple(ref)
    rows = [row for _, row in run.find_rows(triple) if row.get("kind") == "SCHEMA" and _is_eligible(row)] if triple else []
    return rows[0] if len(rows) == 1 else None


def _schema_member_state(run: Run, ref: Any) -> tuple[str, dict[str, Any] | None]:
    """'OK' | 'ROW_UNRESOLVED' | 'MEMBER_UNREGISTERED' for a typed schema reference."""
    row = _eligible_schema_row(run, ref)
    if row is None:
        return "ROW_UNRESOLVED", None
    if isinstance(ref, dict) and "member_id" in ref:
        member = ref["member_id"]
        members = row.get("members", [])
        if not isinstance(member, str) or not member or not isinstance(members, list) or members.count(member) != 1:
            return "MEMBER_UNREGISTERED", row
    return "OK", row


def _errors_against(run: Run, ref: Any, instance: Any) -> list[Any]:
    """JSON Schema failures of an instance against the schema (member) named by a resolved typed reference."""
    contract = _ensure_registration_contract(run)
    _, schema = _resolve_schema_object(_candidate_universe(run), dict(ref), contract)
    return schema_errors(schema, instance, "INSTANCE")


def _pe36_errors_against(run: Run, ref: Any, instance: Any) -> list[Any]:
    """_errors_against for PE-36 only: the same schema object and the same errors, obtained by _pe36_schema_errors."""
    contract = _ensure_registration_contract(run)
    _, schema = _resolve_schema_object(_candidate_universe(run), dict(ref), contract)
    return _pe36_schema_errors(schema, instance)


# ---- stage 21 group 1: strict identity union ---------------------------------------------------------
@_subjects("PE-35")
def _pe35_subjects(run: Run) -> list[dict[str, Any]]:
    candidates = sorted(((index, row) for index, row in enumerate(run.rows()) if _is_eligible(row)),
                        key=lambda item: identity_utf16_key(item[1]))
    for bound_index, allow in enumerate(run.profile["accepted_source_allowlist"]):
        triple = _identity_triple(allow.get("ref"))
        for _, row in candidates:
            if (row.get("kind"), row.get("id"), row.get("version")) == triple:
                return [{"cls": "UNION_COLLISION", "candidate": row, "allow": allow, "allow_index": bound_index}]
    return []


@_pred("PE-35", "CROSS_SET_COLLISION")
def _pe35(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    derivation = REG["strict_identity_union"]["failure"]["witness_field_derivation"]
    assert set(derivation) == {"kind", "id", "version", "candidate_origin", "candidate_path_or_source",
                               "bound_origin", "bound_path_or_source"}
    row, allow = subject["candidate"], subject["allow"]
    return {"witness": {"kind": row["kind"], "id": row["id"], "version": row["version"],
                        "candidate_origin": "CANDIDATE_UNIVERSE", "candidate_path_or_source": row["path"],
                        "bound_origin": "BOUND_SOURCE_UNIVERSE", "bound_path_or_source": allow["canonical_path"]}}


# ---- stage 21 group 2: candidate objects -------------------------------------------------------------
def _schema_row_violation(run: Run, row: Mapping[str, Any]) -> tuple[str, dict[str, Any]] | None:
    """First PE-37 condition a SCHEMA row violates: (condition_id, derivation inputs) or None."""
    cached = run.documents.setdefault("schema_violation", {})
    key = row["path"]
    if key not in cached:
        _, content = run.row_content(row)
        result = None
        if not isinstance(content, dict) or content.get("$schema") != PC["draft_2020_12_dialect"]:
            result = ("SCHEMA_DIALECT", {})
        else:
            errors = _meta_schema_errors(content)
            if errors:
                result = ("SCHEMA_METASCHEMA", {"errors": errors})
            else:
                tokens = _first_nonlocal_reference(content)
                if tokens is not None:
                    result = ("SCHEMA_NONLOCAL_REF", {"tokens": tokens})
        cached[key] = result
    return cached[key]


def _schema_violation_pred(condition_id: str) -> Callable[[Run, Mapping[str, Any]], dict[str, Any] | None]:
    def pred(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
        violation = _schema_row_violation(run, subject["row"])
        return violation[1] if violation is not None and violation[0] == condition_id else None
    return pred


for _cid in ("SCHEMA_DIALECT", "SCHEMA_METASCHEMA", "SCHEMA_NONLOCAL_REF"):
    _PRED[("PE-37", _cid)] = _schema_violation_pred(_cid)


@_pred("PE-36", "APPLIED_SCHEMA_NOT_IN_UNIVERSE")
def _pe36_universe(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    return None if _eligible_schema_row(run, subject["row"].get("schema_ref")) is not None else {}


@_pred("PE-36", "APPLIED_SCHEMA_DOCUMENT_INELIGIBLE")
def _pe36_ineligible(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    applied = _eligible_schema_row(run, subject["row"].get("schema_ref"))
    return None if _schema_row_violation(run, applied) is None else {}


@_pred("PE-36", "APPLIED_SCHEMA_MEMBER_UNREGISTERED")
def _pe36_member(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    return None if _schema_member_state(run, subject["row"].get("schema_ref"))[0] == "OK" else {}


@_pred("PE-36", "CONTENT_SCHEMA_VIOLATION")
def _pe36_content(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    content = run.row_content(subject["row"])[1]
    errors = _pe36_errors_against(run, subject["row"]["schema_ref"], content)
    return {"errors": errors} if errors else None


# ---- stage 21 group 3: accepted/bound source content ---------------------------------------------------
@_subjects("PE-38")
def _pe38_subjects(run: Run) -> list[dict[str, Any]]:
    return [{"cls": "BOUND_SOURCE", "allow_index": i, "allow": allow}
            for i, allow in enumerate(run.profile["accepted_source_allowlist"])]


@_pred("PE-38", "BOUND_SCHEMA_MEMBER_UNREGISTERED")
def _pe38_unresolved(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state, _ = _schema_member_state(run, subject["allow"].get("expected_schema_ref"))
    return None if state == "OK" else {"case": "EXPECTED_SCHEMA_ROW_UNRESOLVED" if state == "ROW_UNRESOLVED"
                                       else "EXPECTED_SCHEMA_MEMBER_UNREGISTERED"}


@_pred("PE-38", "BOUND_SCHEMA_VIOLATION")
def _pe38_violation(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    content = _accepted_content_value(run, subject["allow_index"])[1]
    errors = _errors_against(run, subject["allow"]["expected_schema_ref"], content)
    return {"errors": errors, "case": "EXPECTED_SCHEMA_RESOLVED"} if errors else None


# ---- stage 21 group 4: reserved input declarations -----------------------------------------------------
def _reserved_expectations(run: Run) -> dict[str, Any]:
    expectations = run.metacontract.get("binding_origins", {}).get("reserved_input_expectations")
    return expectations if isinstance(expectations, dict) else {}


def _reserved_rows(run: Run) -> list[Any]:
    rows = run.metacontract.get("reserved_inputs")
    return rows if isinstance(rows, list) else []


@_subjects("PE-41")
def _pe41_subjects(run: Run) -> list[dict[str, Any]]:
    subjects: list[dict[str, Any]] = [{"cls": "RESERVED_INPUT_ROW", "reserved_index": i, "reserved": row, "raw": row}
                                      for i, row in enumerate(_reserved_rows(run))]
    subjects.append({"cls": "RESERVED_INPUT_COLLECTION"})
    return subjects


def _nonempty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value)


def _reserved_location(subject: Mapping[str, Any], members: Sequence[str],
                       violates: Callable[[str, bool, Any], bool]) -> str | None:
    row, base = subject["reserved"], f"/reserved_inputs/{subject['reserved_index']}"
    if not isinstance(row, dict):
        return base
    for member in sorted(members, key=_utf16_key):
        if member.startswith("profile_content_source/"):
            container = row.get("profile_content_source")
            if not isinstance(container, dict):
                return base + "/profile_content_source"
            name = member.split("/", 1)[1]
            if violates(member, name in container, container.get(name)):
                return base + "/profile_content_source/" + _escape_token(name)
        elif violates(member, member in row, row.get(member)):
            return base + "/" + _escape_token(member)
    return None


def _reserved_pred(condition_id: str, violates: Callable[[Run, Mapping[str, Any], str, bool, Any], bool],
                   applies: Callable[[Run, Mapping[str, Any]], bool] = lambda run, subject: True) -> None:
    members = CONDITIONS["PE-41"][condition_id]["checked_members"]

    def pred(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
        if not isinstance(subject["reserved"], dict):
            return {"pointer": f"/reserved_inputs/{subject['reserved_index']}"} if condition_id == "RESERVED_INPUT_DECLARATION_INVALID" else None
        if not applies(run, subject):
            return None
        pointer = _reserved_location(subject, members, lambda m, present, value: violates(run, subject, m, present, value))
        return {"pointer": pointer} if pointer is not None else None
    _PRED[("PE-41", condition_id)] = pred


def _content_source_required(run: Run, subject: Mapping[str, Any]) -> bool:
    row = subject["reserved"]
    expectation = _reserved_expectations(run).get(row.get("name")) if isinstance(row.get("name"), str) else None
    return isinstance(row.get("profile_content_source"), dict) or (isinstance(expectation, dict) and expectation.get("pin_ref") is not None)


_CONTENT_SOURCE_FLAGS = {"profile_content_source/content_encoding": "BASE64_RAW_FILE_BYTES",
                         "profile_content_source/decode": "STRICT_BASE64_TO_RAW_UTF8_JSON",
                         "profile_content_source/use_after_pin_verification_only": True,
                         "profile_content_source/candidate_copy_authority": False}


def _flag_violation(run: Run, subject: Mapping[str, Any], member: str, present: bool, value: Any) -> bool:
    return not present or type(value) is not type(_CONTENT_SOURCE_FLAGS[member]) or value != _CONTENT_SOURCE_FLAGS[member]


def _transport_violation(run: Run, subject: Mapping[str, Any], member: str, present: bool, value: Any) -> bool:
    transport = next((name for name, expectation in _reserved_expectations(run).items()
                      if isinstance(expectation, dict) and expectation.get("type") == "EXTERNAL_ACCEPTANCE_PROFILE"), None)
    return not present or value != transport


def _pointer_tokens_violation(run: Run, subject: Mapping[str, Any], member: str, present: bool, value: Any) -> bool:
    return not present or not isinstance(value, list) or not value or any(not _nonempty_string(token) for token in value)


def _pin_violation(run: Run, subject: Mapping[str, Any], member: str, present: bool, value: Any) -> bool:
    expectation = _reserved_expectations(run).get(subject["reserved"].get("name"))
    return present is False or not _json_equal_pe(value, expectation["pin_ref"])


def _pin_applies(run: Run, subject: Mapping[str, Any]) -> bool:
    expectation = _reserved_expectations(run).get(subject["reserved"].get("name")) if _nonempty_string(subject["reserved"].get("name")) else None
    return isinstance(expectation, dict) and expectation.get("pin_ref") is not None


_reserved_pred("RESERVED_INPUT_DECLARATION_INVALID", lambda run, s, m, present, value: not present or not _nonempty_string(value))
_reserved_pred("RESERVED_INPUT_ORIGIN_UNDECLARED",
               lambda run, s, m, present, value: not present or value not in run.metacontract.get("binding_origins", {}).get("allowed_origins", []))
_reserved_pred("RESERVED_CONTENT_SOURCE_INVALID", _flag_violation, _content_source_required)
_reserved_pred("RESERVED_CONTENT_POINTER_INVALID", _pointer_tokens_violation, _content_source_required)
_reserved_pred("RESERVED_CONTENT_SOURCE_TRANSPORT_INVALID", _transport_violation, _content_source_required)
_reserved_pred("RESERVED_CONTENT_SOURCE_PIN_UNDECLARED", _pin_violation, _pin_applies)


@_pred("PE-41", "RESERVED_INPUT_DECLARATION_NOT_UNIQUE")
def _pe41_unique(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    row = subject["reserved"]
    if not isinstance(row, dict) or not _nonempty_string(row.get("name")):
        return None
    earlier = [r.get("name") for r in _reserved_rows(run)[:subject["reserved_index"]] if isinstance(r, dict)]
    return {"pointer": f"/reserved_inputs/{subject['reserved_index']}/name"} if row["name"] in earlier else None


@_pred("PE-41", "RESERVED_INPUT_NAME_LABEL_MISMATCH")
def _pe41_label(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    row = subject["reserved"]
    expectation = _reserved_expectations(run).get(row.get("name")) if _nonempty_string(row.get("name")) else None
    if not isinstance(expectation, dict):
        return None  # a name that is not a key is owned by RESERVED_INPUT_NAME_SET_MISMATCH
    pointer = _reserved_location(subject, CONDITIONS["PE-41"]["RESERVED_INPUT_NAME_LABEL_MISMATCH"]["checked_members"],
                                 lambda member, present, value: not present or type(value) is not str or value != expectation[member])
    return {"pointer": pointer} if pointer is not None else None


@_pred("PE-41", "RESERVED_INPUT_NAME_SET_MISMATCH")
def _pe41_names(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    declared = {row.get("name") for row in _reserved_rows(run) if isinstance(row, dict)}
    return None if declared == set(_reserved_expectations(run)) else {}


# ---- stage 21 group 5: producer schemas of pin-verified reserved content ------------------------------------
@_subjects("PE-39")
def _pe39_subjects(run: Run) -> list[dict[str, Any]]:
    subjects = []
    for index, row in enumerate(_reserved_rows(run)):
        source = row.get("profile_content_source") if isinstance(row, dict) else None
        if isinstance(source, dict) and "producer_schema_ref" in source:
            subjects.append({"cls": "PRODUCER_SCHEMA_RESERVED_INPUT", "reserved_index": index, "reserved": row})
    return subjects


@_pred("PE-39", "PRODUCER_SCHEMA_UNRESOLVED")
def _pe39_unresolved(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state, _ = _schema_member_state(run, subject["reserved"]["profile_content_source"]["producer_schema_ref"])
    return None if state == "OK" else {}


def _reserved_content(run: Run, reserved: Mapping[str, Any]) -> Any:
    source = reserved["profile_content_source"]
    found, encoded = _resolve_pointer(run.profile, pointer_from_tokens(source["content_pointer_tokens"]))
    raw = _decode_base64_strict(encoded) if found else None
    return _decode_json_classified(raw)[0] if raw is not None else None


@_pred("PE-39", "PRODUCER_SCHEMA_VIOLATION")
def _pe39_violation(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    errors = _errors_against(run, subject["reserved"]["profile_content_source"]["producer_schema_ref"],
                             _reserved_content(run, subject["reserved"]))
    return {"errors": errors} if errors else None


# ---- stage 21 group 6: runtime representation ---------------------------------------------------------------
@_subjects("PE-40")
def _pe40_subjects(run: Run) -> list[dict[str, Any]]:
    schemas = run.metacontract["runtime_representation"]["value_schemas"]
    subjects: list[dict[str, Any]] = [{"cls": "RUNTIME_VALUE_SCHEMA", "value_schema_name": name, "value_schema_id": schemas[name].get("$id")}
                                      for name in sorted(schemas, key=_utf16_key)]
    universe = _full_universe(run)
    subjects.append({"cls": "UNIVERSE_VALUE", "value_schema_id": schemas["verification_universe"].get("$id")})
    subjects.extend({"cls": "UNIVERSE_OBJECT_RECORD", "record_index": k, "value_schema_id": schemas["resolved_object"].get("$id")}
                    for k in range(len(universe.objects)))
    return subjects


@_pred("PE-40", "VALUE_SCHEMA_INVALID")
def _pe40_schema(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    name = subject["value_schema_name"]
    errors = _meta_schema_errors(run.metacontract["runtime_representation"]["value_schemas"][name])
    scope = tuple(parse_pointer(CONDITIONS["PE-40"]["VALUE_SCHEMA_INVALID"]["pointer_scope"].replace("<escaped_value_schema_name>", _escape_token(name))))
    return {"errors": errors, "scope_tokens": scope} if errors else None


def _runtime_validator(run: Run, name: str) -> Any:
    validators = run.documents.setdefault("runtime_validators", {})
    if name not in validators:
        validators[name] = jsonschema.Draft202012Validator(run.metacontract["runtime_representation"]["value_schemas"][name])
    return validators[name]


@_pred("PE-40", "UNIVERSE_REPRESENTATION")
def _pe40_universe(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    errors = list(_runtime_validator(run, "verification_universe").iter_errors(run.universe_view))
    if not errors:
        return None
    return {"errors": errors, "location_tokens": _first_location(tuple(e.absolute_path) for e in errors)}


@_pred("PE-40", "RESOLVED_OBJECT_REPRESENTATION")
def _pe40_record(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    index = subject["record_index"]
    errors = list(_runtime_validator(run, "resolved_object").iter_errors(run.universe_view["objects"][index]))
    if not errors:
        return None
    scope = tuple(parse_pointer(CONDITIONS["PE-40"]["RESOLVED_OBJECT_REPRESENTATION"]["pointer_scope"].replace("<k>", str(index))))
    return {"errors": errors, "scope_tokens": scope, "location_tokens": scope + (_first_location(tuple(e.absolute_path) for e in errors) or ())}

def _resolve_schema_object(universe: VerificationUniverse, schema_ref: Any,
                           registration_contract: _RegistrationContract | None = None) -> tuple[ResolvedObject, Any]:
    if not isinstance(schema_ref, dict):
        raise ExpressionError("INVALID_TYPED_REFERENCE", detail="schema_ref must be a typed reference")
    # RESOLVE_ONE semantics: the exact owner, then exactly one equal string in
    # its registered members (MEMBER_NOT_FOUND otherwise, never a $defs fallback).
    obj = universe.resolve(schema_ref)
    schema = obj.content
    if "member_id" in schema_ref:
        member = schema_ref["member_id"]
        binding = registration_contract.member_binding if registration_contract is not None else None
        if binding is None or obj.reference.get("kind") != binding.owner_kind:
            raise ExpressionError("MEMBER_NOT_FOUND", detail=f"no declared member binding for {schema_ref!r}")
        target = binding.target(schema, member)
        if not isinstance(target, (dict, bool)):
            # Unreachable once SEMANTIC_REGISTRATION_VALIDATE_ALL_ROWS passes:
            # every registered member binds there or fails with
            # UNRESOLVED_SCHEMA_MEMBER_DEFINITION.
            raise ExpressionError("MEMBER_NOT_FOUND", detail=f"registered member {member!r} does not bind at {binding.pointer(member)}")
        schema = target
        if isinstance(schema, bool):
            schema = {"allOf": [schema]}
        # A member schema is nested under the pinned parent schema; local refs resolve against the parent document.
        schema = dict(schema)
        schema.setdefault("$schema", obj.content.get("$schema", DIALECT))
        # The nested base URI is the parent document identity member declared by
        # schema_document_identity.schema_content_id_member. A parent document
        # without an exact JSON string at that declared pointer fails closed; no
        # evaluator-side derivation from the typed reference is substituted.
        parent_id = (_registration_pointer_value(obj.content, registration_contract.schema_content_id_tokens)
                     if registration_contract is not None else _REGISTRATION_CONTENT_ABSENT)
        if not isinstance(parent_id, str) or not parent_id:
            raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"argument":"candidate_schema","object_role":"SCHEMA_AUTHORITY",
                "failure_kind":"TYPE",
                "instance_pointer":(registration_contract.schema_content_id_pointer if registration_contract is not None else ""),
                "diagnostic":"schema document content identity is absent under the declared projection",
                "bound_identity":identity_object(obj.reference)})
        schema["$id"] = parent_id
    return obj, schema



# ---- stage 22: static validation of the procedure registry and the result projection selector ------------
def _listing(document: Any, key: str) -> list[Any]:
    value = document.get(key) if isinstance(document, dict) else None
    return value if isinstance(value, list) else []


def _static_context(run: Run) -> dict[str, Any]:
    context = run.documents.get("static")
    if context is None:
        universe = _full_universe(run)

        def content(member: str) -> Any:
            return universe.resolve(run.package_reference(member)).content

        metacontract = run.metacontract
        calculus = metacontract["runtime_representation"]["static_type_calculus"]
        primitives_document = content(BOOTSTRAP_SPECS["primitive_registry"]["package_member"])
        procedures_document = content(BOOTSTRAP_SPECS["procedure_registry"]["package_member"])
        invariants_document = content(BOOTSTRAP_SPECS["invariant_registry"]["package_member"])
        rules_document = content(BOOTSTRAP_SPECS["rule_registry"]["package_member"])
        context = {
            "metacontract": metacontract,
            "primitives_document": primitives_document, "procedures_document": procedures_document,
            "invariants_document": invariants_document, "rules_document": rules_document,
            "primitives": _listing(primitives_document, "primitives"), "procedures": _listing(procedures_document, "procedures"),
            "invariants": _listing(invariants_document, "invariants"), "rules": _listing(rules_document, "rules"),
            "operators": calculus["operator_rules"]["operators"],
            "slot_kinds": calculus["operator_rules"]["argument_type_slot_kinds"],
            "limits": metacontract.get("resource_limits", {}),
        }
        context["primitive_by_id"] = {p["primitive_id"]: p for p in context["primitives"]
                                      if isinstance(p, dict) and isinstance(p.get("primitive_id"), str)}
        context["invariant_by_id"] = {i["invariant_id"]: i for i in context["invariants"]
                                      if isinstance(i, dict) and isinstance(i.get("invariant_id"), str)}
        context["procedure_by_id"] = {p["procedure_id"]: p for p in context["procedures"]
                                      if isinstance(p, dict) and isinstance(p.get("procedure_id"), str)}
        run.documents["static"] = context
    return context


def _set_exact_pointer(ids: Sequence[Any], required: Iterable[Any], collection: str) -> str | None:
    """SET_EXACT: pointer of the first extra (unknown or repeated) element by ascending index, else the collection pointer."""
    required_set = {x for x in required if isinstance(x, str)}
    seen: set[str] = set()
    for index, value in enumerate(ids):
        if not isinstance(value, str) or value not in required_set or value in seen:
            return f"{collection}/{index}"
        seen.add(value)
    return collection if seen != required_set else None


def _lookup(mapping: Mapping[Any, Any], key: Any) -> Any:
    return mapping.get(key) if isinstance(key, str) else None


def _ids(items: Sequence[Any], key: str) -> list[Any]:
    return [item.get(key) if isinstance(item, dict) else None for item in items]


_single_static = _single("STATIC_DECLARATION_SITE")
for _fid in ("PE-45",):
    _SUBJECTS[_fid] = _single_static
_SUBJECTS["PE-44"] = lambda run: [{"cls": "PROCEDURE_DECLARATION", "procedure_index": i}
                                  for i in range(len(_static_context(run)["procedures"]))]
_SUBJECTS["PE-46"] = lambda run: [{"cls": "PROTOCOL_SECTION"}, {"cls": "WITNESS_OPERAND_TERMINAL"}]


def _static_pred(condition_id: str) -> Callable[[Callable[[Run, dict[str, Any]], str | None]], Callable[..., Any]]:
    def register(function: Callable[[Run, dict[str, Any]], str | None]) -> Callable[..., Any]:
        def pred(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
            pointer = function(run, _static_context(run))
            return {"pointer": pointer} if pointer is not None else None
        _PRED[("PE-45", condition_id)] = pred
        return pred
    return register


@_static_pred("PRIMITIVE_SET_EXACT_TO_STATIC_TYPE_CALCULUS")
def _pe45_primitive_set(run: Run, st: dict[str, Any]) -> str | None:
    return _set_exact_pointer(_ids(st["primitives"], "primitive_id"), st["operators"], "/primitives")


@_static_pred("PRIMITIVE_SIGNATURE_MATCHES_STATIC_TYPE_CALCULUS")
def _pe45_primitive_signature(run: Run, st: dict[str, Any]) -> str | None:
    for index, primitive in enumerate(st["primitives"]):
        operator = st["operators"].get(primitive.get("primitive_id")) if isinstance(primitive, dict) else None
        if operator is None:
            continue
        arguments = primitive.get("arguments")
        slots = operator["slots"]
        ok = (isinstance(arguments, list) and len(arguments) == len(slots)
              and all(isinstance(a, dict) and a.get("name") == slot[0] and a.get("type") in st["slot_kinds"]
                      and st["slot_kinds"][a["type"]] == slot[1] for a, slot in zip(arguments, slots))
              and primitive.get("output_type") == operator["result"])
        if not ok:
            return f"/primitives/{index}"
    return None


def _descendant_vector_failure(vector: Any, max_depth: int, max_nodes: int) -> bool:
    if not isinstance(vector, dict):
        return True
    try:
        actual = _descendant_rows(vector.get("input"), max_depth, max_nodes)
    except ExpressionError:
        return True
    if len(actual) != vector.get("expected_record_count") or actual != vector.get("expected_records"):
        return True
    for row in actual:
        chain = row["ancestor_pointers"]
        if not chain or chain[0] != "" or chain[-1] != row["pointer"]:
            return True
    probe = vector.get("ancestry_semantics_probe")
    if isinstance(probe, dict):
        observed = next((row["ancestor_pointers"] for row in actual if row["pointer"] == probe.get("probe_pointer")), None)
        if (probe.get("selected_semantics") != "INCLUSIVE_ROOT_THROUGH_SELF"
                or observed != probe.get("inclusive_expected_ancestor_pointers")
                or observed != probe.get("observed_ancestor_pointers")
                or observed == probe.get("strict_expected_ancestor_pointers")):
            return True
    exclusion = vector.get("exclusion_probe")
    if isinstance(exclusion, dict):
        excluded = exclusion.get("excluded_pointer")
        excluded_nodes = [row["pointer"] for row in actual if excluded in row["ancestor_pointers"]]
        included_nodes = [row["pointer"] for row in actual if excluded not in row["ancestor_pointers"]]
        if (exclusion.get("governing_token") != "EXACT_POINTER_EQUALITY_AGAINST_ANCESTOR_POINTERS"
                or excluded_nodes != exclusion.get("expected_excluded_node_pointers")
                or included_nodes != exclusion.get("expected_included_node_pointers")):
            return True
    return False


@_static_pred("DESCENDANT_CONFORMANCE_VECTORS_REPRODUCED")
def _pe45_descendant_vectors(run: Run, st: dict[str, Any]) -> str | None:
    document = st["primitives_document"]
    vectors = document.get("descendant_conformance_vectors") if isinstance(document, dict) else None
    limits = st["limits"]
    max_depth = int(limits.get("max_json_traversal_depth", 256))
    max_nodes = int(limits.get("max_json_nodes_visited_per_value", 1_000_000))
    if not isinstance(vectors, list):
        return "/descendant_conformance_vectors"
    report = _descendant_conformance_report(document, limits)
    for index, vector in enumerate(vectors):
        if _descendant_vector_failure(vector, max_depth, max_nodes):
            return f"/descendant_conformance_vectors/{index}"
    return None if report["declaration_closed"] and vectors else "/descendant_conformance_vectors/0"


@_static_pred("PROCEDURE_ID_SET_EXACT")
def _pe45_procedure_set(run: Run, st: dict[str, Any]) -> str | None:
    return _set_exact_pointer(_ids(st["procedures"], "procedure_id"), _ids(st["invariants"], "procedure_id"), "/procedures")


@_static_pred("INVARIANT_SET_EXACT_TO_PACKAGE_REQUIRED_INVARIANT_IDS")
def _pe45_invariant_set(run: Run, st: dict[str, Any]) -> str | None:
    required = run.package.get("required_invariant_ids")
    return _set_exact_pointer(_ids(st["invariants"], "invariant_id"), required if isinstance(required, list) else [], "/invariants")


def _bootstrap_document(run: Run, st: dict[str, Any], argument: str) -> Any:
    """The decoded document of a bootstrap object named by its declared argument."""
    return {"candidate_package": run.package, "object_registry": run.registry, "metacontract": run.metacontract,
            "rule_registry": st["rules_document"], "invariant_registry": st["invariants_document"],
            "procedure_registry": st["procedures_document"], "primitive_registry": st["primitives_document"]}.get(argument)


def _resolve_label_pointer(run: Run, st: dict[str, Any], reference: Any) -> tuple[bool, Any]:
    """LABEL_COLON_POINTER_RESOLVED_IN_THE_NAMED_BOOTSTRAP_OBJECT: the label names the bootstrap object by the final
    segment of its declared identity id (equivalently its argument name with '-' for '_')."""
    if not isinstance(reference, str) or ":" not in reference:
        return False, None
    label, pointer = reference.split(":", 1)
    for spec in PC["bootstrap_objects"]:
        if label in (spec["identity"]["id"].rsplit(":", 1)[-1], spec["argument"].replace("_", "-")):
            return _resolve_pointer(_bootstrap_document(run, st, spec["argument"]), pointer)
    return False, None


@_static_pred("BOUND_RULE_SET_EXACT_TO_REQUIRED_RULE_IDS")
def _pe45_rule_set(run: Run, st: dict[str, Any]) -> str | None:
    # compared_sets: the rule_id of EVERY item of the bound rule registry collection (whatever its declared_class)
    # against the COMPLETE array referenced by the candidate package's required_rule_ids_ref; there is no
    # executable-only reading.
    compared = CONDITIONS["PE-45"]["BOUND_RULE_SET_EXACT_TO_REQUIRED_RULE_IDS"]["compared_sets"]
    bound, required_spec = compared["bound"], compared["required"]
    if (compared["relation"] != "BOUND_IDS_UNIQUE_AND_SET_EQUAL_TO_REQUIRED_IDS" or bound["object"] != "rule_registry"
            or bound["member"] != "rule_id" or bound["scope"] != "EVERY_RULE_WHATEVER_ITS_DECLARED_CLASS"
            or required_spec["object"] != "candidate_package" or required_spec["scope"] != "THE_COMPLETE_REFERENCED_ARRAY"
            or required_spec["resolution"] != "LABEL_COLON_POINTER_RESOLVED_IN_THE_NAMED_BOOTSTRAP_OBJECT"
            or compared["executable_subset_is_the_compared_set"] is not False):
        raise RuntimeError("unsupported compared_sets declaration of BOUND_RULE_SET_EXACT_TO_REQUIRED_RULE_IDS")
    found_reference, reference = _resolve_pointer(run.package, required_spec["reference_member"])
    found, value = _resolve_label_pointer(run, st, reference) if found_reference else (False, None)
    required = value if found and isinstance(value, list) else []
    found_collection, collection = _resolve_pointer(_bootstrap_document(run, st, bound["object"]), bound["collection_pointer"])
    items = collection if found_collection and isinstance(collection, list) else []
    return _set_exact_pointer(_ids(items, bound["member"]), required, bound["collection_pointer"])


@_static_pred("INVARIANT_PROCEDURE_BINDINGS_EXACT")
def _pe45_procedure_bindings(run: Run, st: dict[str, Any]) -> str | None:
    bindings = st["metacontract"].get("procedure_bindings")
    bindings = bindings if isinstance(bindings, list) else []
    seen: set[str] = set()
    for index, binding in enumerate(bindings):
        invariant = _lookup(st["invariant_by_id"], binding.get("invariant_id")) if isinstance(binding, dict) else None
        if invariant is None or binding["invariant_id"] in seen or binding.get("procedure_id") != invariant.get("procedure_id"):
            return f"/procedure_bindings/{index}"
        seen.add(binding["invariant_id"])
    return "/procedure_bindings" if seen != set(st["invariant_by_id"]) else None


def _rule_binding_arguments(procedure: Mapping[str, Any]) -> list[dict[str, Any]]:
    arguments = procedure.get("arguments") if isinstance(procedure, dict) else None
    return [a for a in (arguments if isinstance(arguments, list) else []) if isinstance(a, dict) and a.get("origin") == "RULE_BINDING"]


@_static_pred("RULE_INVARIANT_BINDING_RESOLVES")
def _pe45_rule_binding(run: Run, st: dict[str, Any]) -> str | None:
    for index, rule in enumerate(st["rules"]):
        binding = rule.get("invariant_binding") if isinstance(rule, dict) else None
        if not isinstance(binding, dict):
            continue
        invariant = _lookup(st["invariant_by_id"], binding.get("invariant_id"))
        procedure = _lookup(st["procedure_by_id"], invariant.get("procedure_id")) if invariant else None
        arguments = binding.get("arguments")
        declared = {a.get("name") for a in _rule_binding_arguments(procedure)} if procedure else set()
        if invariant is None or procedure is None or not isinstance(arguments, dict) or not set(arguments) <= declared:
            return f"/rules/{index}/invariant_binding"
    return None


@_static_pred("RESERVED_BINDINGS_IMMUTABLE")
def _pe45_reserved_bindings(run: Run, st: dict[str, Any]) -> str | None:
    declarations = {row.get("name"): row for row in (st["metacontract"].get("reserved_inputs") or []) if isinstance(row, dict)}
    bindings = st["metacontract"].get("procedure_bindings")
    for index, binding in enumerate(bindings if isinstance(bindings, list) else []):
        if not isinstance(binding, dict):
            continue
        invariant = _lookup(st["invariant_by_id"], binding.get("invariant_id"))
        procedure = _lookup(st["procedure_by_id"], invariant.get("procedure_id")) if invariant else None
        if procedure is None:
            continue
        reserved_arguments = {a.get("name"): a for a in procedure.get("arguments", []) if isinstance(a, dict) and a.get("origin") != "RULE_BINDING"}
        rows = binding.get("reserved_bindings")
        rows = rows if isinstance(rows, list) else []
        seen: set[Any] = set()
        for j, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            argument, declaration = _lookup(reserved_arguments, name), _lookup(declarations, name)
            if (not isinstance(row, dict) or argument is None or name in seen
                    or row.get("type") != argument.get("type") or row.get("origin") != argument.get("origin")
                    or (declaration is not None and (row.get("type") != declaration.get("type") or row.get("origin") != declaration.get("origin")))):
                return f"/procedure_bindings/{index}/reserved_bindings/{j}"
            seen.add(name)
        if seen != set(reserved_arguments):
            return f"/procedure_bindings/{index}/reserved_bindings"
    return None


def _source_constraint_validator(run: Run) -> Any:
    validator = run.documents.get("source_constraint_validator")
    if validator is None:
        row = _eligible_schema_row(run, _procedure_registry_schema_ref(run))
        _, schema_document = run.row_content(row)
        validator = jsonschema.Draft202012Validator({"$schema": schema_document.get("$schema", PC["draft_2020_12_dialect"]),
                                                      "$id": schema_document.get("$id"), "$defs": schema_document["$defs"],
                                                      "$ref": "#/$defs/source_constraint"}, format_checker=_DATE_TIME_FORMAT_CHECKER)
        run.documents["source_constraint_validator"] = validator
    return validator


def _procedure_registry_schema_ref(run: Run) -> Any:
    row = run.owning_row("procedure_registry")
    return row.get("schema_ref") if row is not None else None


@_static_pred("RULE_BINDING_SOURCE_CONSTRAINTS_VALID")
def _pe45_source_constraints(run: Run, st: dict[str, Any]) -> str | None:
    for index, procedure in enumerate(st["procedures"]):
        arguments = procedure.get("arguments") if isinstance(procedure, dict) else None
        for j, argument in enumerate(arguments if isinstance(arguments, list) else []):
            if isinstance(argument, dict) and argument.get("origin") == "RULE_BINDING":
                if "source_constraint" not in argument or any(True for _ in _source_constraint_validator(run).iter_errors(argument["source_constraint"])):
                    return f"/procedures/{index}/arguments/{j}/source_constraint"
    return None


@_static_pred("PROCEDURE_RESULT_TYPE_DECLARED")
def _pe45_result_type(run: Run, st: dict[str, Any]) -> str | None:
    for index, procedure in enumerate(st["procedures"]):
        result = procedure.get("result") if isinstance(procedure, dict) else None
        if not isinstance(result, dict) or result.get("type") not in ("BOOLEAN", "TRUST_RESULT"):
            return f"/procedures/{index}/result/type"
    return None


@_static_pred("TRUST_RESULT_OWNER_EXACT")
def _pe45_trust_owner(run: Run, st: dict[str, Any]) -> str | None:
    owner = st["metacontract"].get("result_contracts", {}).get("trust_result", {}).get("owner_procedure_id")
    typed = [(i, p) for i, p in enumerate(st["procedures"]) if isinstance(p, dict) and isinstance(p.get("result"), dict)
             and p["result"].get("type") == "TRUST_RESULT"]
    for index, procedure in typed:
        if procedure.get("procedure_id") != owner:
            return f"/procedures/{index}"
    return "/procedures" if len(typed) != 1 or not typed or typed[0][1].get("procedure_id") != owner else None


def _code_set(value: Any) -> set[str]:
    return {code for code in value if isinstance(code, str)} if isinstance(value, list) else set()


def _assertion_code_pointer(st: dict[str, Any], allowed_for: Callable[[dict[str, Any]], list[set[Any]]]) -> str | None:
    for index, procedure in enumerate(st["procedures"]):
        if not isinstance(procedure, dict):
            continue
        assertions = procedure.get("assertions")
        for j, assertion in enumerate(assertions if isinstance(assertions, list) else []):
            code = assertion.get("failure_code") if isinstance(assertion, dict) else None
            if not isinstance(code, str) or any(code not in allowed for allowed in allowed_for(procedure)):
                return f"/procedures/{index}/assertions/{j}/failure_code"
    return None


@_static_pred("ASSERTION_CODES_IN_PROCEDURE_COMPATIBLE_SET")
def _pe45_codes_procedure(run: Run, st: dict[str, Any]) -> str | None:
    return _assertion_code_pointer(st, lambda p: [_code_set(p.get("compatible_failure_codes"))])


@_static_pred("ASSERTION_CODES_IN_EVERY_BOUND_INVARIANT_SET")
def _pe45_codes_invariants(run: Run, st: dict[str, Any]) -> str | None:
    def allowed(procedure: dict[str, Any]) -> list[set[Any]]:
        return [_code_set(i.get("compatible_failure_codes"))
                for i in st["invariants"] if isinstance(i, dict) and i.get("procedure_id") == procedure.get("procedure_id")]
    return _assertion_code_pointer(st, allowed)


# ---- PE-44: abstract syntax of every procedure (canonical postorder) ---------------------------------------
# The AST law (roots, node forms, child edges by slot kind, terminals, traversal, collection binders) is the
# verifier's committed model:/protocol_constants/ast_resource_limits; the resource-limit measurements are the
# `measurement` objects of the PE-44 conditions. Both are consumed declaratively below.
class _StaticViolation(Exception):
    def __init__(self, condition_id: str, tokens: Sequence[Any]):
        super().__init__(condition_id)
        self.condition_id = condition_id
        self.tokens = tuple(tokens)


_AST_LAW: dict[str, Any] = PC["ast_resource_limits"]
_PE44_CONDITIONS: dict[str, dict[str, Any]] = CONDITIONS["PE-44"]


def _edge_whole_value(value: Any) -> list[tuple[str | None, Any]]:
    return [(None, value)]


def _edge_object_members(value: Any) -> list[tuple[str | None, Any]]:
    return [(name, value[name]) for name in sorted(value, key=_utf16_key)] if isinstance(value, dict) else []


def _edge_object_value(value: Any) -> list[tuple[str | None, Any]]:
    return [(None, value)] if isinstance(value, dict) else []


def _edge_none(value: Any) -> list[tuple[str | None, Any]]:
    return []


# the declared by_slot_kind child-edge tokens
_EDGE_RULES: dict[str, Callable[[Any], list[tuple[str | None, Any]]]] = {
    "THE_VALUE_PRESENT_AT_THE_SLOT": _edge_whole_value,
    "EACH_MEMBER_VALUE_OF_THE_JSON_OBJECT_PRESENT_AT_THE_SLOT": _edge_object_members,
    "THE_VALUE_PRESENT_AT_THE_SLOT_WHEN_IT_IS_A_JSON_OBJECT": _edge_object_value,
    "NO_CHILD_EDGE": _edge_none,
}
_EDGE_RULE_BY_SLOT_KIND: dict[str, Callable[[Any], list[tuple[str | None, Any]]]] = {
    kind: _EDGE_RULES[token] for kind, token in _AST_LAW["ast"]["child_edges"]["by_slot_kind"].items()}
_COLLECTION_BINDERS: dict[str, dict[str, Any]] = _AST_LAW["collection_binders"]["operators"]


def _assert_resource_limit_law() -> None:
    """Every declared measurement token is supported by this verifier; an unsupported declaration is a verifier defect."""
    functions, comparisons = CLOSED["resource_limit_function"], CLOSED["limit_comparison"]
    supported_functions = {"ARRAY_LENGTH", "AST_NODE_COUNT", "NODE_DEPTH", "ACTIVE_COLLECTION_BINDER_COUNT"}
    supported_comparisons = {"VALUE_LESS_THAN_OR_EQUAL_TO_LIMIT", "LOWER_BOUND_AND_VALUE_LESS_THAN_OR_EQUAL_TO_LIMIT"}
    if (set(functions) != supported_functions or set(comparisons) != supported_comparisons
            or _AST_LAW["traversal"]["order"] != "CANONICAL_POSTORDER"
            or _AST_LAW["traversal"]["first_failure"] != "FIRST_INVALID_SUBJECT_IN_TRAVERSAL_ORDER"
            or _AST_LAW["collection_binders"]["complete"] is not True
            or _AST_LAW["ast"]["terminals"]["measured"] is not True
            or _AST_LAW["ast"]["terminals"]["literal_payload_is_ast"] is not False):
        raise RuntimeError("unsupported ast_resource_limits declaration")
    for token in _AST_LAW["ast"]["child_edges"]["by_slot_kind"].values():
        if token not in _EDGE_RULES:
            raise RuntimeError("unsupported ast_resource_limits child edge declaration")
    for condition in _PE44_CONDITIONS.values():
        measurement = condition.get("measurement")
        if measurement is None:
            continue
        if (measurement["function"] not in supported_functions or measurement["comparison"] not in supported_comparisons
                or measurement["limit_inclusive"] is not True or "limit_ref" not in measurement):
            raise RuntimeError("unsupported PE-44 measurement declaration")


_assert_resource_limit_law()


# ---- static typing of SCHEMA_INSTANCE<S> (static_type_calculus: static_type_at_path / schema_keyword_following) ------
_OPAQUE: dict[str, Any] = {"x-opaque": "UNRESOLVED_REFERENCE"}   # a reference this typing cannot follow: no type information
_SCALAR_KINDS = ("STRING", "NUMBER", "BOOLEAN", "NULL")
_TYPE_KEYWORD_KINDS = {"string": "STRING", "integer": "NUMBER", "number": "NUMBER", "boolean": "BOOLEAN", "null": "NULL",
                       "object": "OBJECT", "array": "ARRAY"}
_KIND_TOKENS = {"OBJECT": "JSON_OBJECT", "STRING": "STRING", "NUMBER": "JSON_NUMBER", "BOOLEAN": "BOOLEAN", "NULL": "NULL"}
_MAX_ALTERNATIVES = 256


class _SchemaTyped(str):
    """The static type of a value projected from a registered schema document.

    The str value is the normalized type token of the legacy vocabulary; the instance additionally carries the declared
    schema alternatives it was projected from (so that a further pointer or an array element keeps following the schema)
    and the branch-ambiguity mark of the branch law (incompatible branch types yield JSON marked branch ambiguous)."""
    follower: "_SchemaFollower | None"
    alternatives: tuple[tuple[dict[str, Any], ...], ...]
    ambiguous: bool

    def __new__(cls, token: str, follower: "_SchemaFollower | None" = None,
                alternatives: Sequence[tuple[dict[str, Any], ...]] = (), ambiguous: bool = False) -> "_SchemaTyped":
        value = super().__new__(cls, token)
        value.follower = follower
        value.alternatives = tuple(alternatives)
        value.ambiguous = ambiguous
        return value


class _SchemaFollower:
    """Follows the declared keywords of one registered schema document: properties, items, $ref, type, const, enum, if/then/else,
    allOf, oneOf, anyOf, not and additionalProperties. A schema node is expanded into alternatives (oneOf/anyOf branches),
    each a conjunction of schema fragments (the node, its $ref target, its allOf members and its then/else branches)."""

    def __init__(self, root: Any):
        self.root = root
        self._flat: dict[int, tuple[dict[str, Any], ...]] = {}
        self._alts: dict[int, tuple[tuple[dict[str, Any], ...], ...]] = {}

    # -- expansion --------------------------------------------------------------------------------------
    def resolve_ref(self, reference: Any) -> Any:
        """A local fragment reference of the same schema document; any other reference is not followed."""
        if not isinstance(reference, str) or not reference.startswith("#"):
            return None
        fragment = reference[1:]
        if re.search(r"%(?![0-9A-Fa-f]{2})", fragment):
            return None
        try:
            decoded = urllib.parse.unquote(fragment, errors="strict")
        except UnicodeDecodeError:
            return None
        if decoded == "":
            return self.root if isinstance(self.root, dict) else None
        if not decoded.startswith("/"):
            return None
        found, target = _resolve_pointer(self.root, decoded)
        return target if found and isinstance(target, dict) else None

    def flat(self, node: Any, active: tuple[int, ...] = ()) -> tuple[dict[str, Any], ...]:
        if not isinstance(node, dict):
            return ()
        key = id(node)
        if key in self._flat:
            return self._flat[key]
        if key in active:
            return (node,)
        out: list[dict[str, Any]] = [node]
        if "$ref" in node:
            target = self.resolve_ref(node["$ref"])
            out.extend(self.flat(target, active + (key,)) if target is not None else (_OPAQUE,))
        for keyword in ("allOf",):
            branches = node.get(keyword)
            for branch in branches if isinstance(branches, list) else []:
                out.extend(self.flat(branch, active + (key,)))
        for keyword in ("then", "else"):
            out.extend(self.flat(node.get(keyword), active + (key,)))
        result = tuple(out)
        self._flat[key] = result
        return result

    def alternatives(self, node: Any) -> tuple[tuple[dict[str, Any], ...], ...]:
        if not isinstance(node, dict):
            return ((),)
        key = id(node)
        if key in self._alts:
            return self._alts[key]
        self._alts[key] = ((_OPAQUE,),)   # a self-referential branch carries no type information
        base = self.flat(node)
        result: tuple[tuple[dict[str, Any], ...], ...] = (base,)
        for conjunct in base:
            for keyword in ("oneOf", "anyOf"):
                branches = conjunct.get(keyword)
                if isinstance(branches, list) and branches:
                    result = self.cross([result] + [self.union([self.alternatives(b) for b in branches])])
        self._alts[key] = result
        return result

    @staticmethod
    def union(groups: Sequence[Sequence[tuple[dict[str, Any], ...]]]) -> tuple[tuple[dict[str, Any], ...], ...]:
        return tuple(alt for group in groups for alt in group)

    @staticmethod
    def cross(groups: Sequence[Sequence[tuple[dict[str, Any], ...]]]) -> tuple[tuple[dict[str, Any], ...], ...]:
        result: tuple[tuple[dict[str, Any], ...], ...] = ((),)
        for group in groups:
            result = tuple(left + right for left in result for right in group)
            if len(result) > _MAX_ALTERNATIVES:
                return ((_OPAQUE,),)
        return result

    # -- kinds ------------------------------------------------------------------------------------------
    @staticmethod
    def value_kind(value: Any) -> str:
        if value is None:
            return "NULL"
        if isinstance(value, bool):
            return "BOOLEAN"
        if isinstance(value, (int, float, decimal.Decimal)):
            return "NUMBER"
        if isinstance(value, str):
            return "STRING"
        return "OBJECT" if isinstance(value, dict) else "ARRAY"

    def conjunct_kinds(self, conjunct: dict[str, Any]) -> set[str] | None:
        if conjunct is _OPAQUE:
            return None
        kinds: set[str] | None = None
        if "const" in conjunct:
            kinds = {self.value_kind(conjunct["const"])}
        elif isinstance(conjunct.get("enum"), list) and conjunct["enum"]:
            kinds = {self.value_kind(member) for member in conjunct["enum"]}
        declared = conjunct.get("type")
        if isinstance(declared, str):
            declared = [declared]
        if isinstance(declared, list) and declared and all(isinstance(t, str) and t in _TYPE_KEYWORD_KINDS for t in declared):
            typed = {_TYPE_KEYWORD_KINDS[t] for t in declared}
            kinds = typed if kinds is None else kinds & typed
        return kinds

    def alternative_kind(self, alternative: tuple[dict[str, Any], ...]) -> str | None:
        """The unique normalized kind of a conjunction, or None when it is not determined."""
        if any(conjunct is _OPAQUE for conjunct in alternative):
            return None
        determined: set[str] = set()
        for conjunct in alternative:
            kinds = self.conjunct_kinds(conjunct)
            if kinds is not None:
                if len(kinds) != 1:
                    return None
                determined |= kinds
        return next(iter(determined)) if len(determined) == 1 else None

    # -- typing -----------------------------------------------------------------------------------------
    def element_alternatives(self, alternative: tuple[dict[str, Any], ...]) -> tuple[tuple[dict[str, Any], ...], ...]:
        items = [conjunct["items"] for conjunct in alternative if isinstance(conjunct.get("items"), dict)]
        return self.cross([self.alternatives(item) for item in items]) if items else ((),)

    def typed(self, alternatives: Sequence[tuple[dict[str, Any], ...]]) -> _SchemaTyped:
        """The projected type of a set of alternatives: one normalized type, or JSON (marked branch ambiguous when the
        valid branches have incompatible normalized types)."""
        kinds = [self.alternative_kind(alternative) for alternative in alternatives]
        if not kinds or None in kinds:
            return _SchemaTyped("JSON", self, alternatives)
        distinct = set(kinds)
        if len(distinct) != 1:
            return _SchemaTyped("JSON", self, alternatives, ambiguous=True)
        kind = next(iter(distinct))
        if kind != "ARRAY":
            return _SchemaTyped(_KIND_TOKENS[kind], self, alternatives)
        element_kinds = {self.alternative_kind(element) for alternative in alternatives
                         for element in self.element_alternatives(alternative)}
        token = "ARRAY<JSON>"
        if len(element_kinds) == 1:
            element_kind = next(iter(element_kinds))
            token = {"STRING": "ARRAY<STRING>", "OBJECT": "ARRAY<JSON_OBJECT>"}.get(element_kind or "", "ARRAY<JSON>")
        return _SchemaTyped(token, self, alternatives)

    def project_alternative(self, alternative: tuple[dict[str, Any], ...], token: str) -> tuple[str, Any]:
        """One pointer token applied to one alternative: ('OK', alternatives) | ('ERROR', None) | ('UNKNOWN', None)."""
        if any(conjunct is _OPAQUE for conjunct in alternative):
            return "UNKNOWN", None
        kind = self.alternative_kind(alternative)
        if kind in _SCALAR_KINDS:
            return "ERROR", None   # a known scalar with a nonempty pointer remainder
        if kind == "ARRAY":
            if re.fullmatch(r"0|[1-9][0-9]*", token) is None:
                return "ERROR", None   # a non-index token on an array
            return "OK", self.element_alternatives(alternative)
        declared: list[Any] = []
        for conjunct in alternative:
            properties = conjunct.get("properties")
            if isinstance(properties, dict) and token in properties:
                declared.append(properties[token])
        if not declared:
            for conjunct in alternative:
                patterns = conjunct.get("patternProperties")
                for pattern, schema in (patterns.items() if isinstance(patterns, dict) else ()):
                    try:
                        if re.search(pattern, token):
                            declared.append(schema)
                    except re.error:
                        return "UNKNOWN", None
        if not declared:
            additional = [conjunct["additionalProperties"] for conjunct in alternative if "additionalProperties" in conjunct]
            declared = [schema for schema in additional if isinstance(schema, dict)]
            if not declared:
                if kind == "OBJECT" and any(value is False for value in additional):
                    return "ERROR", None   # a closed record has no such declared field
                return "UNKNOWN", None
        return "OK", self.cross([self.alternatives(schema) for schema in declared])

    def project(self, value: _SchemaTyped, tokens: Sequence[str]) -> _SchemaTyped | None:
        """The static type at an RFC6901 token sequence, or None for a static type error."""
        if value.ambiguous or value.follower is not self:
            return _SchemaTyped("JSON")
        alternatives: Sequence[tuple[dict[str, Any], ...]] = value.alternatives
        for token in tokens:
            outcomes = [self.project_alternative(alternative, token) for alternative in alternatives]
            statuses = {status for status, _ in outcomes}
            if statuses == {"ERROR"}:
                return None
            if statuses != {"OK"}:
                return _SchemaTyped("JSON")   # not determined for every branch: no refinement
            alternatives = self.union([group for _, group in outcomes])
            if len(alternatives) > _MAX_ALTERNATIVES:
                return _SchemaTyped("JSON")
        return self.typed(alternatives)

    def element(self, value: _SchemaTyped) -> _SchemaTyped | None:
        """The exact element type of a projected array type."""
        if value.ambiguous or value.follower is not self or not value.startswith("ARRAY<") or not value.alternatives:
            return None
        return self.typed(self.union([self.element_alternatives(alternative) for alternative in value.alternatives]))


# a narrow consumer: any declared operand type other than the JSON top domains
_NON_NARROW_OPERANDS = ("JSON", "JSON_EXPRESSION", "MODE_EXPRESSION", "JSON_OR_RESOLVED_OBJECT", "FINITE_JSON")


class _AstChecker:
    def __init__(self, run: Run, st: dict[str, Any], procedure: Mapping[str, Any]):
        self.run, self.st = run, st
        self.metacontract = st["metacontract"]
        self.arg_types = {a["name"]: a.get("type") for a in (procedure.get("arguments") or [])
                          if isinstance(a, dict) and isinstance(a.get("name"), str)}
        # SCHEMA_INSTANCE<expected_schema_ref> is bound only from a declared RULE_BINDING argument's expected_schema_ref
        self.schema_refs = {a["name"]: a["source_constraint"]["expected_schema_ref"] for a in (procedure.get("arguments") or [])
                            if isinstance(a, dict) and isinstance(a.get("name"), str) and a.get("origin") == "RULE_BINDING"
                            and isinstance(a.get("source_constraint"), dict)
                            and isinstance(a["source_constraint"].get("expected_schema_ref"), dict)}
        self.paths = self.metacontract.get("runtime_representation", {}).get("static_paths", {})
        depth, nesting = (_PE44_CONDITIONS[name]["measurement"]
                          for name in ("MAX_EXPRESSION_DEPTH_EXCEEDED", "MAX_LEXICAL_COLLECTION_NESTING_EXCEEDED"))
        self.max_depth, self.max_nesting = self.limit(depth), self.limit(nesting)
        self.root_depth, self.edge_increment = depth["root_value"], depth["edge_increment"]
        self.root_nesting, self.entry_increment = nesting["root_value"], nesting["entry_increment"]
        if nesting["exit_decrement"] != nesting["entry_increment"] or nesting["binder_node_value"] != "CURRENT_COUNT" \
                or nesting["unbound_slot_value"] != "CURRENT_COUNT" \
                or nesting["binder_set_ref"] != "model:/protocol_constants/ast_resource_limits/collection_binders/operators":
            raise RuntimeError("unsupported MAX_LEXICAL_COLLECTION_NESTING_EXCEEDED measurement declaration")

    def limit(self, measurement: Mapping[str, Any]) -> int:
        value = _metacontract_pointer_value(self.metacontract, measurement["limit_ref"])
        if value is _REGISTRATION_CONTENT_ABSENT or isinstance(value, bool) or not isinstance(value, int):
            raise RuntimeError(f"resource limit {measurement['limit_ref']} is not declared as an integer")
        return value

    def violation(self, condition_id: str, tokens: Sequence[Any]) -> "NoReturn":  # type: ignore[name-defined]
        raise _StaticViolation(condition_id, tokens)

    # -- child edges and node counting -----------------------------------------------------------------------
    def edges(self, node: Any) -> list[tuple[str, str | None, Any]]:
        """(slot, named-map member or None, child value) of every declared child edge, in canonical child order."""
        operator = self.st["operators"].get(node.get("op")) if isinstance(node, dict) and isinstance(node.get("op"), str) else None
        edges: list[tuple[str, str | None, Any]] = []
        for slot, kind in (operator["slots"] if operator else []):
            if slot in node:
                edges.extend((slot, member, child) for member, child in _EDGE_RULE_BY_SLOT_KIND[kind](node[slot]))
        return edges

    def count_nodes(self, node: Any) -> int:
        count = 0
        pending = [node]
        while pending:
            count += 1
            pending.extend(child for _, _, child in self.edges(pending.pop()))
        return count

    @staticmethod
    def path_tokens(frame: Mapping[str, Any]) -> tuple[Any, ...]:
        """Materialize the node path only when a violation needs a witness."""
        segments: list[tuple[Any, ...]] = []
        while frame["parent"] is not None:
            segments.append(frame["edge_tokens"])
            frame = frame["parent"]
        tokens = list(frame["root_tokens"])
        for segment in reversed(segments):
            tokens.extend(segment)
        return tuple(tokens)

    # -- expressions ---------------------------------------------------------------------------------------
    def measure(self, depth: int, nesting: int, frame: Mapping[str, Any]) -> None:
        """MAX_EXPRESSION_DEPTH_EXCEEDED then MAX_LEXICAL_COLLECTION_NESTING_EXCEEDED of one node (every node is measured)."""
        if depth > self.max_depth:
            self.violation("MAX_EXPRESSION_DEPTH_EXCEEDED", self.path_tokens(frame))
        if nesting > self.max_nesting:
            self.violation("MAX_LEXICAL_COLLECTION_NESTING_EXCEEDED", self.path_tokens(frame))

    def argument_type(self, name: str) -> str:
        declared = "VERIFICATION_UNIVERSE" if self.arg_types[name] == "VERIFICATION_UNIVERSE" else "JSON_OBJECT"
        reference = self.schema_refs.get(name)
        if reference is None:
            return declared   # rule_binding_without_schema_ref: the declared argument type
        instance = self.schema_instance(reference)
        return instance if instance is not None else declared

    def schema_instance(self, reference: Mapping[str, Any]) -> _SchemaTyped | None:
        """SCHEMA_INSTANCE<expected_schema_ref>: the registered schema document (and optional member) named by the reference."""
        cache = self.run.documents.setdefault("schema_instance_types", {})
        key = json.dumps(reference, sort_keys=True, ensure_ascii=False)
        if key not in cache:
            try:
                parent, schema = _resolve_schema_object(_candidate_universe(self.run), dict(reference),
                                                        _ensure_registration_contract(self.run))
                follower = _SchemaFollower(parent.content)
                cache[key] = follower.typed(follower.alternatives(schema))
            except (ExpressionError, GateError):
                cache[key] = None
        return cache[key]

    def analyze(self, node: Any, tokens: tuple[Any, ...], scopes: Mapping[str, str], depth: int, nesting: int) -> str:
        """Canonical postorder analysis without Python call-stack growth per AST edge."""
        root = {"node": node, "parent": None, "root_tokens": tokens, "scopes": scopes,
                "depth": depth, "nesting": nesting}
        pending = [root]
        while pending:
            frame = pending[-1]
            current = frame["node"]
            if "slots" not in frame:
                if not isinstance(current, dict):
                    self.violation("EXACT_OPERATOR_OPERANDS", self.path_tokens(frame))
                if "op" not in current:
                    result = self.analyze_terminal(frame)
                    pending.pop()
                    if not pending:
                        return result
                    pending[-1]["types"][frame["assign"]] = result
                    continue
                op = current.get("op")
                operator = self.st["operators"].get(op) if isinstance(op, str) else None
                frame["slots"] = operator["slots"] if operator else []
                frame["binder"] = _COLLECTION_BINDERS.get(op) if operator is not None else None
                frame["types"] = {}
                frame["slot_index"] = 0
                frame["members"] = []
                frame["member_index"] = 0
            if frame["member_index"] < len(frame["members"]):
                member, child = frame["members"][frame["member_index"]]
                frame["member_index"] += 1
                slot = frame["active_slot"]
                extension = (slot,) if member is None else (slot, member)
                child_frame = {"node": child, "parent": frame, "edge_tokens": extension,
                               "scopes": frame["child_scopes"], "depth": frame["depth"] + self.edge_increment,
                               "nesting": frame["child_nesting"],
                               "assign": slot if member is None else (slot, member)}
                pending.append(child_frame)
                continue
            if frame["slot_index"] < len(frame["slots"]):
                slot, kind = frame["slots"][frame["slot_index"]]
                frame["slot_index"] += 1
                if slot not in current:
                    continue
                binder = frame["binder"]
                bound = binder is not None and slot in binder["bound_slots"]
                frame["child_scopes"] = self.bind(current, frame["scopes"], frame["types"], binder) if bound else frame["scopes"]
                frame["child_nesting"] = frame["nesting"] + self.entry_increment if bound else frame["nesting"]
                frame["active_slot"] = slot
                frame["members"] = _EDGE_RULE_BY_SLOT_KIND[kind](current[slot])
                frame["member_index"] = 0
                continue
            result = self.analyze_operator(frame)
            pending.pop()
            if not pending:
                return result
            pending[-1]["types"][frame["assign"]] = result
        raise RuntimeError("AST analysis ended without a root result")

    def analyze_terminal(self, frame: Mapping[str, Any]) -> str:
        node = frame["node"]
        scopes = frame["scopes"]
        fail = lambda condition_id: self.violation(condition_id, self.path_tokens(frame))
        for form in ("arg", "item", "literal"):
            if form in node:
                if set(node) != {form} or (form != "literal" and not isinstance(node[form], str)):
                    fail("EXACT_OPERATOR_OPERANDS")
                if form == "arg" and node["arg"] not in self.arg_types:
                    fail("DECLARED_ARGUMENTS_ONLY")
                if form == "item" and node["item"] not in scopes:
                    fail("LEXICAL_SCOPE_NO_SHADOW_OR_ESCAPE_ON_ACTIVE_PATH")
                self.measure(frame["depth"], frame["nesting"], frame)
                if form == "arg":
                    return self.argument_type(node["arg"])
                if form == "item":
                    return scopes[node["item"]]
                value = node["literal"]
                if isinstance(value, bool):
                    return "BOOLEAN"
                if isinstance(value, (int, float, decimal.Decimal)):
                    return "JSON_NUMBER"
                if isinstance(value, str):
                    return "STRING"
                if isinstance(value, list):
                    return "ARRAY<JSON>"
                return "JSON_OBJECT" if isinstance(value, dict) else "JSON"
        fail("EXACT_OPERATOR_OPERANDS")
        return "JSON"

    def analyze_operator(self, frame: Mapping[str, Any]) -> str:
        node = frame["node"]
        scopes = frame["scopes"]
        depth, nesting = frame["depth"], frame["nesting"]
        fail = lambda condition_id: self.violation(condition_id, self.path_tokens(frame))
        op = node.get("op")
        operator = self.st["operators"].get(op) if isinstance(op, str) else None
        primitive = self.st["primitive_by_id"].get(op) if isinstance(op, str) else None
        slots = frame["slots"]
        binder = frame["binder"]
        types = frame["types"]
        # node conditions in declared rank order
        if operator is not None:
            expected_members = {"op"} | {slot for slot, _ in slots}
            shape_ok = set(node) == expected_members
            for slot, kind in slots:
                if slot not in node:
                    continue
                value = node[slot]
                if kind == "NAMED_EXPRESSION_MAP" and (not isinstance(value, dict) or not value
                                                       or any(not isinstance(k, str) for k in value)):
                    shape_ok = False
                elif kind == "SCOPE_BINDER" and (not isinstance(value, str) or not value):
                    shape_ok = False
                elif kind == "POINTER_ARRAY_SLOT" and not isinstance(value, dict) and (not isinstance(value, list) or not value):
                    shape_ok = False
                elif kind in ("COMPARATOR_SLOT", "MODE_SLOT") and not isinstance(value, (str, dict)):
                    shape_ok = False
            if not shape_ok:
                fail("EXACT_OPERATOR_OPERANDS")
        if operator is None or primitive is None:
            fail("OPERATOR_IN_CLOSED_OPERATOR_LANGUAGE")
        if binder is not None and isinstance(node.get(binder["binder_slot"]), str) and node[binder["binder_slot"]] in scopes:
            fail("LEXICAL_SCOPE_NO_SHADOW_OR_ESCAPE_ON_ACTIVE_PATH")
        self.measure(depth, nesting, frame)
        for slot, kind in slots:
            value = node.get(slot)
            if kind == "POINTER_SLOT" and slot in node and not isinstance(value, dict):
                if not isinstance(value, str) or not self.valid_pointer(value):
                    fail("POINTER_LITERAL_RFC6901_VALID")
            elif kind == "POINTER_ARRAY_SLOT" and slot in node and not isinstance(value, dict):
                if not all(isinstance(p, str) and self.valid_pointer(p) for p in value):
                    fail("POINTER_LITERAL_RFC6901_VALID")
        if op == "RESOLVE_ONE" and node.get("universe") != {"arg": "verification_universe"}:
            fail("RESOLVE_ONE_USES_EXACT_VERIFICATION_UNIVERSE_TERMINAL")
        if op == "DIGEST_VERIFY":
            for slot in ("algorithm", "serialization", "excluded_pointers"):
                if not _has_dynamic_source(node.get(slot), scopes, self.arg_types):
                    fail("DIGEST_MODE_FIELDS_ARE_DYNAMIC_EXPRESSIONS")
        result = primitive["output_type"]
        if op == "GET" and isinstance(node.get("pointer"), str):
            value_type = types.get("value")
            if value_type in ("VERIFICATION_UNIVERSE", "RESOLVED_OBJECT"):
                paths = self.paths.get(value_type, {})
                pointer = node["pointer"]
                if pointer in paths:
                    result = paths[pointer]
                else:
                    pointer_tokens = parse_pointer(pointer)
                    root_pointer = pointer_from_tokens(pointer_tokens[:1])
                    descendable = {"JSON", "INTEGRITY", "TYPED_REFERENCE", "BASE_TYPED_REFERENCE", "TYPED_REFERENCE_OR_NULL",
                                   "ARRAY<STRING>", "ARRAY<RESOLVED_OBJECT>"}
                    if root_pointer in paths and paths[root_pointer] in descendable and len(pointer_tokens) > 1:
                        result = "JSON"
                    else:
                        fail("STATIC_TYPE_AT_PATH_SCHEMA_NOMINAL_AND_STRUCTURAL")
            elif isinstance(value_type, _SchemaTyped) and value_type.follower is not None:
                # SCHEMA_INSTANCE<S>: follow the declared schema document from its root along the static pointer
                projected = value_type.follower.project(value_type, parse_pointer(node["pointer"]))
                if projected is None:
                    fail("STATIC_TYPE_AT_PATH_SCHEMA_NOMINAL_AND_STRUCTURAL")
                result = projected
        declared = {a["name"]: a["type"] for a in primitive.get("arguments", []) if isinstance(a, dict)}
        for slot, kind in slots:
            if slot not in node:
                continue
            value = node[slot]
            if kind == "EXPRESSION" or (kind in ("POINTER_SLOT", "POINTER_ARRAY_SLOT") and isinstance(value, dict)):
                # R2e SCHEMA_VALIDATE admits a boolean schema operand in either mode.
                if not (op == "SCHEMA_VALIDATE" and slot == "schema" and types.get(slot) == "BOOLEAN") \
                        and not _compatible_type(declared.get(slot, "JSON"), types.get(slot, "JSON")):
                    fail("OPERAND_RESULT_TYPES_VALID")
            elif kind == "MODE_SLOT" and isinstance(value, str):
                members = re.fullmatch(r"ENUM<(.*)>", declared.get(slot, ""))
                if members is not None and value not in members.group(1).split(","):
                    fail("OPERAND_RESULT_TYPES_VALID")
        for slot, kind in slots:
            # branch law: a narrow consumer of a branch-ambiguous result is underdetermined and fails closed
            operand = types.get(slot)
            if (kind == "EXPRESSION" and isinstance(operand, _SchemaTyped) and operand.ambiguous
                    and declared.get(slot, "JSON") not in _NON_NARROW_OPERANDS):
                fail("AST_TYPE_UNDERDETERMINED_FAILS_CLOSED")
        if binder is not None and op == "FILTER":
            result = types.get(binder["unbound_slots"][0], "JSON")
        return result

    def bind(self, node: Mapping[str, Any], scopes: Mapping[str, str], types: Mapping[Any, Any],
             binder: Mapping[str, Any]) -> dict[str, str]:
        bound = dict(scopes)
        name = node.get(binder["binder_slot"])
        if isinstance(name, str) and name:
            array_type = types.get(binder["unbound_slots"][0])
            element = array_type.follower.element(array_type) if isinstance(array_type, _SchemaTyped) \
                and array_type.follower is not None else None
            bound[name] = element if element is not None else ("RESOLVED_OBJECT" if array_type == "ARRAY<RESOLVED_OBJECT>" else "JSON")
        return bound

    @staticmethod
    def valid_pointer(pointer: str) -> bool:
        try:
            parse_pointer(pointer)
        except ExpressionError:
            return False
        return True

    # -- procedures ------------------------------------------------------------------------------------------
    def procedure_value(self, condition_id: str, procedure: Mapping[str, Any]) -> bool:
        """Evaluate one procedure-level measurement (model:/families/PE-44 conditions[].measurement): True when the
        procedure violates it. A member that is not a JSON array is not measured by an ARRAY_LENGTH condition."""
        measurement = _PE44_CONDITIONS[condition_id]["measurement"]
        if measurement["function"] == "ARRAY_LENGTH":
            member = procedure.get(measurement["measured_member"])
            if not isinstance(member, list):
                return False
            value = len(member)
        else:   # AST_NODE_COUNT: every node of every AST root (terminals and malformed values counted, no literal payload)
            assertions = procedure.get("assertions")
            value = sum(self.count_nodes(a[member]) for a in (assertions if isinstance(assertions, list) else [])
                        if isinstance(a, dict) for member in ("condition", "witness") if member in a)
        if value > self.limit(measurement):
            return True
        return measurement["comparison"] == "LOWER_BOUND_AND_VALUE_LESS_THAN_OR_EQUAL_TO_LIMIT" and value < measurement["lower_bound"]

    def check_procedure(self, index: int, procedure: Mapping[str, Any]) -> None:
        base = ("procedures", index)
        arguments = procedure.get("arguments")
        arguments = arguments if isinstance(arguments, list) else []
        seen: set[Any] = set()
        for j, argument in enumerate(arguments):
            name = argument.get("name") if isinstance(argument, dict) else None
            if isinstance(name, str):
                if name in seen:
                    self.violation("ARGUMENT_NAMES_UNIQUE", base + ("arguments", j))
                seen.add(name)
        if self.procedure_value("MAX_ARGUMENTS_PER_PROCEDURE_EXCEEDED", procedure):
            self.violation("MAX_ARGUMENTS_PER_PROCEDURE_EXCEEDED", base + ("arguments",))
        assertions = procedure.get("assertions")
        assertions = assertions if isinstance(assertions, list) else []
        seen = set()
        for j, assertion in enumerate(assertions):
            identifier = assertion.get("assertion_id") if isinstance(assertion, dict) else None
            if isinstance(identifier, str):
                if identifier in seen:
                    self.violation("ASSERTION_IDS_UNIQUE", base + ("assertions", j))
                seen.add(identifier)
        if self.procedure_value("MAX_ASSERTIONS_PER_PROCEDURE_EXCEEDED", procedure):
            self.violation("MAX_ASSERTIONS_PER_PROCEDURE_EXCEEDED", base + ("assertions",))
        if self.procedure_value("MAX_AST_NODES_PER_PROCEDURE_EXCEEDED", procedure):
            self.violation("MAX_AST_NODES_PER_PROCEDURE_EXCEEDED", base + ("assertions",))
        for j, assertion in enumerate(assertions):
            if not isinstance(assertion, dict):
                continue
            condition_tokens = base + ("assertions", j, "condition")
            if self.analyze(assertion.get("condition"), condition_tokens, {}, self.root_depth, self.root_nesting) != "BOOLEAN":
                self.violation("ASSERTION_CONDITION_ROOTS_BOOLEAN_NO_TRUTHINESS", condition_tokens)
            self.analyze(assertion.get("witness"), base + ("assertions", j, "witness"), {}, self.root_depth, self.root_nesting)


def _run_pe44(run: Run) -> None:
    st = _static_context(run)
    for index, procedure in enumerate(st["procedures"]):
        if not isinstance(procedure, dict):
            continue
        try:
            _AstChecker(run, st, procedure).check_procedure(index, procedure)
        except _StaticViolation as violation:
            raise PreFail("PE-44", violation.condition_id, {"cls": "AST_NODE", "procedure_index": index},
                          pointer=_pointer_of(violation.tokens)) from None


# ---- PE-46: witness operand identity totality -------------------------------------------------------------------
@_pred("PE-46", "GENERIC_WITNESS_DECLARATION_UNSUPPORTED")
def _pe46_declaration(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    pointer = CONDITIONS["PE-46"]["GENERIC_WITNESS_DECLARATION_UNSUPPORTED"]["section_pointer"]
    found, section = _resolve_pointer(run.metacontract, pointer)
    digest = _digest_or_none(section) if found else None
    return None if digest == _COMMITTED_DIGESTS[pointer.rstrip("/").split("/")[-1]] else {}


def _witness_terminals(st: dict[str, Any], node: Any, tokens: tuple[Any, ...]) -> Iterator[tuple[str, tuple[Any, ...]]]:
    """(argument, node tokens) of every {arg} terminal of a declared witness in first-occurrence preorder."""
    if not isinstance(node, dict):
        return
    if set(node) == {"arg"} and isinstance(node["arg"], str):
        yield node["arg"], tokens
        return
    operator = st["operators"].get(node.get("op")) if isinstance(node.get("op"), str) else None
    for slot, kind in (operator["slots"] if operator else []):
        value = node.get(slot)
        if kind == "EXPRESSION":
            yield from _witness_terminals(st, value, tokens + (slot,))
        elif kind == "NAMED_EXPRESSION_MAP" and isinstance(value, dict):
            for name in sorted(value, key=_utf16_key):
                yield from _witness_terminals(st, value[name], tokens + (slot, name))


@_pred("PE-46", "MISSING_WITNESS_OPERAND_IDENTITY")
def _pe46_identity(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    st = _static_context(run)
    declared = st["metacontract"].get("failure_semantics", {}).get("generic_failure_witness", {})
    only = {row.get("argument"): row for row in declared.get("operand_only_identities", []) if isinstance(row, dict)}
    for index, procedure in enumerate(st["procedures"]):
        if not isinstance(procedure, dict) or not isinstance(procedure.get("result"), dict) or procedure["result"].get("type") != "BOOLEAN":
            continue
        arguments = {a.get("name"): a for a in procedure.get("arguments", []) if isinstance(a, dict)}
        for j, assertion in enumerate(procedure.get("assertions") or []):
            for name, tokens in _witness_terminals(st, assertion.get("witness") if isinstance(assertion, dict) else None,
                                                   ("procedures", index, "assertions", j, "witness")):
                argument = arguments.get(name)
                if argument is None:
                    return {"pointer": _pointer_of(tokens)}
                if argument.get("origin") == "RULE_BINDING" and isinstance(argument.get("source_constraint"), dict):
                    continue
                row = only.get(name)
                if row is None or row.get("argument_origin") != argument.get("origin") or row.get("argument_type") != argument.get("type"):
                    return {"pointer": _pointer_of(tokens)}
    return None


# ---- PE-48: required binding resolution ------------------------------------------------------------------------
@_subjects("PE-48")
def _pe48_subjects(run: Run) -> list[dict[str, Any]]:
    st = _static_context(run)
    sites: list[dict[str, Any]] = []
    for inv_index, invariant in enumerate(st["invariants"]):
        procedure = _lookup(st["procedure_by_id"], invariant.get("procedure_id")) if isinstance(invariant, dict) else None
        if procedure is None:
            continue
        defaults = invariant.get("default_arguments")
        for spec in _rule_binding_arguments(procedure):
            present = isinstance(defaults, dict) and spec["name"] in defaults
            sites.append({"cls": "BINDING_SITE", "site_kind": "INVARIANT_DEFAULT_ARGUMENT", "spec": spec, "present": present,
                          "ref": defaults[spec["name"]] if present else None,
                          "pointer": (f"/invariants/{inv_index}/default_arguments/{_escape_token(spec['name'])}" if present
                                      else f"/invariants/{inv_index}/default_arguments")})
    for rule_index, rule in enumerate(st["rules"]):
        binding = rule.get("invariant_binding") if isinstance(rule, dict) else None
        if not isinstance(binding, dict):
            continue
        invariant = _lookup(st["invariant_by_id"], binding.get("invariant_id"))
        procedure = _lookup(st["procedure_by_id"], invariant.get("procedure_id")) if invariant else None
        overrides = binding.get("arguments")
        if procedure is None or not isinstance(overrides, dict):
            continue
        for spec in _rule_binding_arguments(procedure):
            if spec["name"] in overrides:
                sites.append({"cls": "BINDING_SITE", "site_kind": "RULE_INVARIANT_BINDING_ARGUMENT", "spec": spec, "present": True,
                              "ref": overrides[spec["name"]],
                              "pointer": f"/rules/{rule_index}/invariant_binding/arguments/{_escape_token(spec['name'])}"})
    return sites


def _site_fail(site: Mapping[str, Any]) -> dict[str, Any]:
    return {"pointer": site["pointer"]}


def _constraint(site: Mapping[str, Any]) -> Mapping[str, Any]:
    constraint = site["spec"].get("source_constraint")
    return constraint if isinstance(constraint, dict) else {}


def _strict_reference(ref: Any) -> bool:
    return (isinstance(ref, dict) and {"kind", "id", "version"} <= set(ref) and set(ref) <= {"kind", "id", "version", "member_id"}
            and all(_nonempty_string(ref[name]) for name in ref))


def _binding_targets(run: Run, site: Mapping[str, Any]) -> list[ResolvedObject] | None:
    universe_name = _constraint(site).get("universe")
    if universe_name == "CANDIDATE_UNIVERSE":
        objects = _candidate_resolved_objects(run)
    elif universe_name == "BOUND_SOURCE_UNIVERSE":
        objects = _bound_resolved_objects(run)
    else:
        return None
    triple = _identity_triple(site["ref"])
    return [obj for obj in objects if identity_tuple(obj.reference) == triple]


def _exact_allowlist_row(run: Run, ref: Any) -> Mapping[str, Any] | None:
    return next((row for row in run.profile["accepted_source_allowlist"] if isinstance(row, dict) and _json_equal_pe(row.get("ref"), ref)), None)


def _site_pred(condition_id: str, violates: Callable[[Run, Mapping[str, Any]], bool]) -> None:
    def pred(run: Run, site: Mapping[str, Any]) -> dict[str, Any] | None:
        return _site_fail(site) if violates(run, site) else None
    _PRED[("PE-48", condition_id)] = pred


def _v_missing(run: Run, site: Mapping[str, Any]) -> bool:
    return not site["present"]


def _v_not_strict(run: Run, site: Mapping[str, Any]) -> bool:
    return not _strict_reference(site["ref"])


def _v_kind(run: Run, site: Mapping[str, Any]) -> bool:
    return site["ref"]["kind"] != _constraint(site).get("expected_kind")


def _v_universe(run: Run, site: Mapping[str, Any]) -> bool:
    targets = _binding_targets(run, site)
    return targets is None or len(targets) != 1


def _v_status(run: Run, site: Mapping[str, Any]) -> bool:
    registration = _binding_targets(run, site)[0].registration
    constraint = _constraint(site)
    required_roles = constraint.get("required_roles", [])
    roles = registration.get("roles", [])
    return (registration.get("status") != constraint.get("status") or registration.get("classification") != constraint.get("classification")
            or not isinstance(required_roles, list) or not isinstance(roles, list) or any(role not in roles for role in required_roles))


def _v_schema_reference(run: Run, site: Mapping[str, Any]) -> bool:
    expected = _constraint(site).get("expected_schema_ref")
    registration = _binding_targets(run, site)[0].registration
    return expected is not None and _digest_or_none(registration.get("schema_ref")) != _digest_or_none(expected)


def _v_member(run: Run, site: Mapping[str, Any]) -> bool:
    constraint = _constraint(site)
    target = _binding_targets(run, site)[0]
    if "member_id" in site["ref"] and target.registration.get("members", []).count(site["ref"]["member_id"]) != 1:
        return True
    return constraint.get("schema_required") is True and _schema_member_state(run, constraint.get("expected_schema_ref"))[0] != "OK"


def _v_exact(run: Run, site: Mapping[str, Any]) -> bool:
    identity = _constraint(site).get("identity_constraint", {})
    if not isinstance(identity, dict) or identity.get("mode") != "EXACT_REFERENCE":
        return False
    allow = _exact_allowlist_row(run, site["ref"])
    return (not _json_equal_pe(identity.get("ref"), site["ref"]) or allow is None
            or identity.get("canonical_path") != allow.get("canonical_path"))


def _v_metadata(run: Run, site: Mapping[str, Any]) -> bool:
    identity = _constraint(site).get("identity_constraint", {})
    if not isinstance(identity, dict) or identity.get("mode") != "EXACT_REFERENCE":
        return False
    allow = _exact_allowlist_row(run, site["ref"])
    registration = _binding_targets(run, site)[0].registration
    integrity = registration.get("integrity", {})
    actual = {"canonical_path": registration.get("path"), "raw_sha256": integrity.get("raw_sha256"),
              "semantic_sha256": integrity.get("semantic_sha256"), "git_blob": integrity.get("git_blob"),
              "status": registration.get("status"), "classification": registration.get("classification"),
              "roles": registration.get("roles"), "expected_schema_ref": registration.get("schema_ref")}
    expected = {name: allow.get(name) for name in actual}
    return (any(identity.get(name) != allow.get(name) for name in ("raw_sha256", "semantic_sha256", "git_blob"))
            or _digest_or_none(actual) != _digest_or_none(expected))


for _cid, _violates in (("BINDING_REQUIRED_ARGUMENT_MISSING", _v_missing), ("BINDING_NOT_STRICT_TYPED_REFERENCE", _v_not_strict),
                        ("BINDING_KIND_DIFFERS_FROM_SOURCE_CONSTRAINT", _v_kind), ("BINDING_TARGET_NOT_IN_DECLARED_UNIVERSE", _v_universe),
                        ("BINDING_TARGET_STATUS_CLASSIFICATION_OR_ROLES_INELIGIBLE", _v_status),
                        ("BINDING_TARGET_SCHEMA_REFERENCE_MISMATCH", _v_schema_reference),
                        ("BINDING_TARGET_SCHEMA_MEMBER_UNRESOLVED", _v_member),
                        ("BINDING_EXACT_REFERENCE_OR_PATH_MISMATCH", _v_exact),
                        ("BINDING_ACCEPTED_SOURCE_METADATA_MISMATCH", _v_metadata)):
    _site_pred(_cid, _violates)


# ---- PE-47: result projection map value ------------------------------------------------------------------------
_SUBJECTS["PE-47"] = _single("SELECTED_PROJECTION_PROCEDURE")


def _projection_state(run: Run) -> dict[str, Any]:
    state = run.documents.get("projection")
    if state is None:
        st = _static_context(run)
        descriptor = run.profile[_selector_profile_pointer().lstrip("/")]
        items = _selector_items(st["procedures_document"])[1]
        selected = items[_selector_matches(items)[0]]
        baseline = run.frozen_objects[_descriptor_baseline_member(run, descriptor)].content
        state = {"descriptor": descriptor, "selected": selected, "baseline": baseline,
                 "projection": {"procedure_id": selected["procedure_id"], "descriptor": descriptor}}
        pointers = {status: pointer_from_tokens(tokens) for status, tokens in descriptor["baseline"]["status_pointer_tokens"].items()}
        found = {status: _resolve_pointer(baseline, pointer) for status, pointer in pointers.items()}
        state["baseline_values"] = {status: value for status, (ok, value) in found.items()}
        state["baseline_resolved"] = all(ok for ok, _ in found.values())
        binding_rows = [b for b in st["metacontract"].get("procedure_bindings", []) if isinstance(b, dict) and b.get("procedure_id") == selected["procedure_id"]]
        map_ref = None
        map_object = None
        map_found, mapping = False, None
        if len(binding_rows) == 1 and isinstance(binding_rows[0].get("rule_bindings"), dict) and descriptor["argument"] in binding_rows[0]["rule_bindings"]:
            map_ref = binding_rows[0]["rule_bindings"][descriptor["argument"]]
            try:
                map_object = run.universe.resolve(map_ref)
            except ExpressionError:
                map_object = None
            if map_object is not None:
                map_found, mapping = _resolve_pointer(map_object.content, pointer_from_tokens(descriptor["pointer_tokens"]))
        state.update({"map_reference": map_ref, "map_found": map_found, "map_value": mapping})
        run.documents["projection"] = state
    return state


def _selector_profile_pointer() -> str:
    return next(claim["profile_pointer_rfc6901"] for claim in CLAIMS if "candidate_selector" in claim)


def _descriptor_baseline_member(run: Run, descriptor: Mapping[str, Any]) -> str:
    """Profile member of the frozen source that backs the descriptor's baseline argument (reserved_input_expectations pin_ref)."""
    expectation = _reserved_expectations(run).get(descriptor["baseline"]["argument"])
    member = expectation["pin_ref"][1] if isinstance(expectation, dict) and expectation.get("pin_ref") else None
    if member not in FROZEN_SOURCES:
        raise RuntimeError("descriptor baseline argument is not a pin-verified frozen source")
    return member


def _projection_extra(state: Mapping[str, Any], **more: Any) -> dict[str, Any]:
    return {"projection": state["projection"], "baseline_values": state["baseline_values"], "map_value": state["map_value"], **more}


@_pred("PE-47", "PROJECTION_PATH_INVALID")
def _pe47_path(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state = _projection_state(run)
    return None if state["baseline_resolved"] and state["map_found"] else _projection_extra(state)


@_pred("PE-47", "BASELINE_VALUE_TYPE")
def _pe47_baseline_type(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state = _projection_state(run)
    return None if all(isinstance(v, str) for v in state["baseline_values"].values()) else _projection_extra(state)


@_pred("PE-47", "BASELINE_LITERAL_MISMATCH")
def _pe47_baseline_literal(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state = _projection_state(run)
    expected = state["descriptor"]["expected_literals"]
    return None if all(state["baseline_values"].get(status) == expected.get(status) for status in state["baseline_values"]) else _projection_extra(state)


@_pred("PE-47", "MAP_VALUE_TYPE")
def _pe47_map_type(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state = _projection_state(run)
    mapping = state["map_value"]
    return None if isinstance(mapping, dict) and all(isinstance(v, str) for v in mapping.values()) else _projection_extra(state)


@_pred("PE-47", "MAP_MISSING_OR_EXTRA_KEY")
def _pe47_map_keys(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state = _projection_state(run)
    descriptor, mapping = state["descriptor"], state["map_value"]
    return None if set(mapping) == set(descriptor["expected_literals"]) and len(mapping) == descriptor["mapping_cardinality"] else _projection_extra(state)


@_pred("PE-47", "LITERAL_MISMATCH")
def _pe47_literal(run: Run, subject: Mapping[str, Any]) -> dict[str, Any] | None:
    state = _projection_state(run)
    return None if state["map_value"] == state["descriptor"]["expected_literals"] else _projection_extra(state)


# ---------------------------------------------------------------------------
# Scheduler: first-failure selection over the committed stage ordering.
# ---------------------------------------------------------------------------
_GROUP_SUBJECTS: dict[str, Callable[[Run], list[dict[str, Any]]]] = {
    "REGISTRY_SOURCE_ORDER": _registry_row_subjects,
    "ELIGIBLE_ROWS_REGISTRY_SOURCE_ORDER": _eligible_row_subjects,
}


def _in_scope(family_id: str, condition_id: str, subject: Mapping[str, Any]) -> bool:
    scope = CONDITIONS[family_id][condition_id].get("subject_scope")
    return scope is None or subject.get("cls") in scope


def _check_condition(run: Run, family_id: str, condition_id: str, subject: Mapping[str, Any]) -> None:
    if not _in_scope(family_id, condition_id, subject):
        return
    extra = _PRED[(family_id, condition_id)](run, subject)
    if extra is not None:
        raise PreFail(family_id, condition_id, subject, **extra)


def _execute_family(run: Run, family_id: str) -> None:
    if family_id == "PE-21":
        _run_pe21(run)
        return
    if family_id == "PE-44":
        _run_pe44(run)
        return
    order = FAMILIES[family_id]["within_family_order"]
    subjects = _SUBJECTS[family_id](run)
    if order in ("SUBJECT_ORDER_THEN_CONDITION_RANK", "REGISTRATION_DECLARED_ORDER"):
        for subject in subjects:
            for condition_id in CONDITION_ORDER[family_id]:
                _check_condition(run, family_id, condition_id, subject)
    else:
        for condition_id in CONDITION_ORDER[family_id]:
            for subject in subjects:
                _check_condition(run, family_id, condition_id, subject)


def _execute_group(run: Run, group: Mapping[str, Any]) -> None:
    if group["group_order"] == "SINGLE_FAMILY":
        _execute_family(run, group["families"][0])
        return
    ranks = group["family_rank_within_subject"]
    families = sorted(group["families"], key=lambda family_id: ranks[family_id])
    for subject in _GROUP_SUBJECTS[group["group_order"].split(":", 1)[1]](run):
        for family_id in families:
            if subject["cls"] not in FAMILIES[family_id]["subject_classes"]:
                continue
            for condition_id in CONDITION_ORDER[family_id]:
                _check_condition(run, family_id, condition_id, subject)


def _after_stage5(run: Run) -> None:
    run.package = _entry_decode(run, ENTRYPOINT_SPECS[0])[0]
    run.registry = _entry_decode(run, ENTRYPOINT_SPECS[1])[0]


def _after_stage8(run: Run) -> None:
    run.profile = _profile_decode(run)[0]


def _after_frozen(run: Run, family_id: str) -> None:
    member = FAMILIES[family_id]["profile_member"]
    run.frozen_objects[member] = ResolvedObject(
        {"kind": "FROZEN_SOURCE", "id": f"urn:moirae:external:{member}", "version": "external"},
        {"kind": "FROZEN_SOURCE", "id": f"urn:moirae:external:{member}", "version": "external", "path": None,
         "status": "EXTERNALLY_PINNED", "classification": "EXTERNAL_AUTHORITY", "roles": ["FROZEN_SOURCE"],
         "integrity": {"mode": "GIT_BLOB_OBJECT", "algorithm": "SHA-1", "digest": git_blob(run.frozen_bytes[member])}},
        _decode_json_classified(run.frozen_bytes[member])[0], run.frozen_bytes[member], "EXTERNAL_ACCEPTANCE_PROFILE")


def _after_stage12(run: Run) -> None:
    run.metacontract = _claim_artifact(run, "metacontract")[1]


_AFTER: dict[int, Callable[[Run], None]] = {
    5: _after_stage5, 8: _after_stage8, 9: lambda run: _after_frozen(run, "PE-16A"),
    10: lambda run: _after_frozen(run, "PE-16B"), 12: _after_stage12,
}


def _verify_pre_execution(run: Run) -> None:
    """Evaluate the stages in committed order; the first failure is raised as PreFail, later stages are not evaluated."""
    for stage in STAGE_ORDERING:
        for group in stage["groups"]:
            _execute_group(run, group)
        hook = _AFTER.get(stage["stage_index"])
        if hook is not None:
            hook(run)
    _leap_second_labels(run)  # fail closed (internal error) when the governed leap-second table cannot be bound or verified
    _ensure_registration_contract(run)
    _full_universe(run)


def _assert_predicate_coverage() -> None:
    """Every declared condition has a predicate (PE-21 group 1 and PE-44 are evaluated by their own runners) and vice versa."""
    declared = {(fid, cid) for fid, conditions in CONDITIONS.items() for cid in conditions
                if fid != "PE-44" and (fid, cid) != ("PE-21", "OBJECT_REGISTRY_DOCUMENT_LEVEL_SCHEMA_VIOLATION")}
    if declared != set(_PRED):
        raise RuntimeError(f"predicate coverage differs from the model: {sorted(declared ^ set(_PRED))[:6]}")
    for fid in FAMILIES:
        if fid not in ("PE-21", "PE-44") and fid not in _SUBJECTS:
            raise RuntimeError(f"no subject enumeration for {fid}")


_assert_predicate_coverage()

@dataclass
class Program:
    inputs: CandidateInputs
    package: dict[str, Any]
    object_registry: dict[str, Any]
    metacontract: dict[str, Any]
    primitive_registry: dict[str, Any]
    procedure_registry: dict[str, Any]
    invariant_registry: dict[str, Any]
    rule_registry: dict[str, Any]
    schema_registry: dict[tuple[str,str,str], Any]
    procedures: dict[str, dict[str, Any]]
    invariants: dict[str, dict[str, Any]]
    primitives: dict[str, dict[str, Any]]
    bindings: dict[str, dict[str, Any]]
    reserved_values: dict[str, Any]


def _copy_json_value(value: Any) -> Any:
    """Structural deep copy of a governed JSON value by an explicit work stack (no dependence on Python call-stack depth).

    DIGEST_VERIFY (JCS mode) must be able to apply excluded-pointer deletions to a private copy of a value of any
    nesting depth: the primitive declares no traversal-limit error class. Containers (dict, list and their subclasses)
    are rebuilt member by member in the original member order; every other value keeps the behavior of copy.deepcopy."""
    def shell(node: Any) -> Any:
        if isinstance(node, (dict, list)):
            return {} if type(node) is dict else [] if type(node) is list else type(node).__new__(type(node))
        return copy.deepcopy(node)
    if not isinstance(value, (dict, list)):
        return copy.deepcopy(value)
    root = shell(value)
    pending: list[tuple[Any, Any]] = [(value, root)]
    while pending:
        source, target = pending.pop()
        if isinstance(source, dict):
            for key, item in source.items():
                clone = shell(item)
                target[key] = clone
                if isinstance(item, (dict, list)):
                    pending.append((item, clone))
        else:
            for item in source:
                clone = shell(item)
                target.append(clone)
                if isinstance(item, (dict, list)):
                    pending.append((item, clone))
    return root

def _is_number(x: Any) -> bool:
    return not isinstance(x, bool) and isinstance(x, (int, float, decimal.Decimal))

def _numeric(x: Any) -> decimal.Decimal:
    if not _is_number(x):
        raise ExpressionError("NON_NUMERIC_OPERAND", detail=f"not a JSON number: {type(x).__name__}")
    if isinstance(x, float) and not math.isfinite(x):
        raise ExpressionError("NONFINITE_NUMBER", detail="nonfinite float")
    try:
        result = x if isinstance(x, decimal.Decimal) else decimal.Decimal(str(x))
        if not result.is_finite():
            raise ExpressionError("NONFINITE_NUMBER", detail="nonfinite JSON number")
        return result
    except decimal.InvalidOperation as exc:
        raise ExpressionError("NON_NUMERIC_OPERAND", detail=str(exc)) from exc

def _json_equal(left: Any, right: Any) -> bool:
    # metacontract:/numeric_representation/json_equal. Pairs are compared in the same depth-first,
    # left-to-right order as the structural definition, using an explicit LIFO stack (children pushed
    # reversed) so the comparison does not depend on Python call-stack depth: JSON_EQUAL declares no
    # traversal-limit error class, so values of any nesting depth compare to a Boolean (or raise the
    # same ExpressionError at the same first offending pair) exactly as before.
    pending: list[tuple[Any, Any]] = [(left, right)]
    while pending:
        left, right = pending.pop()
        left, right = _json_view(left), _json_view(right)
        if _is_number(left) or _is_number(right):
            if not (_is_number(left) and _is_number(right) and _numeric(left) == _numeric(right)):
                return False
        elif isinstance(left, dict) and isinstance(right, dict):
            if left.keys() != right.keys():
                return False
            pending.extend((left[key], right[key]) for key in reversed(list(left)))
        elif isinstance(left, list) and isinstance(right, list):
            if len(left) != len(right):
                return False
            pending.extend(zip(reversed(left), reversed(right)))
        elif type(left) is not type(right) or not (left == right):
            return False
    return True

_RFC3339_RE = re.compile(r"^([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})(?:\.([0-9]+))?(Z|[+-][0-9]{2}:[0-9]{2})$")
def _timestamp_seconds(value: Any) -> decimal.Decimal:
    if not isinstance(value, str):
        raise ExpressionError("MALFORMED_RFC3339", detail="timestamp must be a string")
    m = _RFC3339_RE.fullmatch(value)
    if not m:
        raise ExpressionError("MALFORMED_RFC3339", detail="timestamp does not match the closed RFC3339 profile")
    y, mo, day, hour, minute, sec = map(int, m.group(1,2,3,4,5,6))
    frac = m.group(7) or ""
    zone = m.group(8)
    if sec > 59 or hour > 23 or minute > 59 or len(frac) > 9 or zone == "-00:00":
        raise ExpressionError("MALFORMED_RFC3339", detail="invalid clock component")
    try:
        base = dt.datetime(y, mo, day, hour, minute, sec, tzinfo=dt.timezone.utc)
    except ValueError as exc:
        raise ExpressionError("MALFORMED_RFC3339", detail=str(exc)) from exc
    offset = decimal.Decimal(0)
    if zone != "Z":
        sign = 1 if zone[0] == "+" else -1
        zhour, zminute = int(zone[1:3]), int(zone[4:6])
        if zhour > 23 or zminute > 59:
            raise ExpressionError("MALFORMED_RFC3339", detail="invalid UTC offset")
        offset = decimal.Decimal(sign * (zhour * 3600 + zminute * 60))
    epoch = dt.datetime(1970,1,1,tzinfo=dt.timezone.utc)
    delta = base - epoch
    whole = decimal.Decimal(delta.days * 86400 + delta.seconds)
    fractional = decimal.Decimal("0." + frac) if frac else decimal.Decimal(0)
    normalized = whole - offset + fractional
    earliest = decimal.Decimal((dt.datetime(1,1,1,tzinfo=dt.timezone.utc) - epoch).days * 86400)
    latest_delta = dt.datetime(9999,12,31,23,59,59,tzinfo=dt.timezone.utc) - epoch
    latest = decimal.Decimal(latest_delta.days * 86400 + latest_delta.seconds) + decimal.Decimal("0.999999999")
    if normalized < earliest or normalized > latest:
        raise ExpressionError("DURATION_OVERFLOW", detail="normalized UTC year lies outside 0001..9999")
    return normalized

def _compare(a: Any, comparator: str, b: Any) -> bool:
    if comparator not in {"LT","LTE","EQ","NE","GTE","GT"}:
        raise ExpressionError("INVALID_COMPARATOR", detail=str(comparator))
    if comparator == "LT": return a < b
    if comparator == "LTE": return a <= b
    if comparator == "EQ": return a == b
    if comparator == "NE": return a != b
    if comparator == "GTE": return a >= b
    return a > b

def _descendant_rows(root: Any, max_depth: int | None, max_nodes: int | None) -> list[dict[str, Any]]:
    # max_depth / max_nodes None: no traversal limit. The DESCENDANTS primitive and its conformance vectors always pass the
    # declared max_json_traversal_depth and max_json_nodes_visited_per_value (both attached to DESCENDANTS /
    # descendant_record only); ENUMERATE_TYPED_REFERENCES (which declares neither limit and no TRAVERSAL_RESOURCE_LIMIT error
    # class) passes None for both for the owner JSON tree it only needs for the declared preorder.
    # Normative DESCENDANT_RECORD emission as declared by the closed primitive registry:
    # preorder depth-first traversal emitting every visited node, object member keys in
    # UTF-16 code unit ascending order, array children in ascending canonical decimal
    # index order, ancestor_pointers an inclusive root-through-self chain whose last
    # element is the node pointer, keys the ordered object member keys ([] otherwise),
    # member_key the exact object member name for object children and null for the root
    # and for every array child, and fail-closed typed errors for non-JSON input,
    # duplicate descendant pointers and traversal resource limits.
    rows: list[dict[str, Any]] = []
    visited = 0
    seen_pointers: set[str] = set()
    def value_type(v: Any) -> str:
        if v is None: return "NULL"
        if isinstance(v, bool): return "BOOLEAN"
        if isinstance(v, int): return "NUMBER"
        if isinstance(v, decimal.Decimal):
            if not v.is_finite():
                raise ExpressionError("NON_JSON_VALUE", detail="non-finite number is not JSON")
            return "NUMBER"
        if isinstance(v, float):
            if v != v or v == float("inf") or v == float("-inf"):
                raise ExpressionError("NON_JSON_VALUE", detail="non-finite number is not JSON")
            return "NUMBER"
        if isinstance(v,str): return "STRING"
        if isinstance(v,list): return "ARRAY"
        if isinstance(v,dict): return "OBJECT"
        raise ExpressionError("NON_JSON_VALUE", detail=f"non-JSON value {type(v).__name__}")
    # primitive-registry:/descendant_record/emission/traversal is
    # PREORDER_DEPTH_FIRST_EXPLICIT_LIFO_STACK_PUSH_CHILDREN_REVERSED: one explicit LIFO stack, children pushed in
    # reverse child order so the first child is popped (visited) first. The first violation in preorder (depth, node
    # count, non-JSON value, duplicate pointer) is raised at the node that causes it, exactly as the declared preorder
    # visits nodes; no Python call-stack depth is consumed per JSON nesting level.
    # Stack entry: (value, parent path tokens, edge token, parent ancestor chain, depth, member_key).
    stack: list[tuple[Any, list[str] | None, str, list[str], int, Any]] = [(root, None, "", [], 0, None)]
    while stack:
        value, parent_tokens, edge_token, ancestors, depth, member_key = stack.pop()
        tokens = [] if parent_tokens is None else parent_tokens + [edge_token]
        if max_depth is not None and depth > max_depth:
            raise ExpressionError("TRAVERSAL_RESOURCE_LIMIT", pointer_from_tokens(tokens), "DESCENDANTS traversal depth limit exceeded")
        visited += 1
        if max_nodes is not None and visited > max_nodes:
            raise ExpressionError("TRAVERSAL_RESOURCE_LIMIT", pointer_from_tokens(tokens), "DESCENDANTS traversal node limit exceeded")
        kind = value_type(value)
        ptr = pointer_from_tokens(tokens)
        if ptr in seen_pointers:
            raise ExpressionError("NON_JSON_VALUE", ptr, "duplicate descendant pointer")
        seen_pointers.add(ptr)
        chain = list(ancestors) + [ptr]
        keys = sorted(value.keys(), key=lambda k:k.encode("utf-16-be")) if isinstance(value,dict) else []
        rows.append({"pointer":ptr,"value":value,"path_tokens":list(tokens),"ancestor_pointers":chain,"value_type":kind,"keys":keys,"member_key":member_key})
        if isinstance(value, dict):
            for key in reversed(keys):
                stack.append((value[key], tokens, key, chain, depth+1, key))
        elif isinstance(value, list):
            for index in range(len(value) - 1, -1, -1):
                stack.append((value[index], tokens, str(index), chain, depth+1, None))
    return rows

def _reference_domain_failure(detail: str, pointer: str = "") -> None:
    raise ExpressionError("REFERENCE_DOMAIN_UNDERDETERMINED", pointer, detail)

def _typed_reference_parts(reference: Any, allow_member: bool = True) -> tuple[str, str, str, str]:
    if (not isinstance(reference, dict)
            or not {"kind", "id", "version"}.issubset(reference)
            or set(reference) - ({"kind", "id", "version", "member_id"} if allow_member else {"kind", "id", "version"})
            or any(not isinstance(reference.get(name), str) or not reference[name]
                   for name in ("kind", "id", "version"))
            or ("member_id" in reference and
                (not isinstance(reference["member_id"], str) or not reference["member_id"]))):
        raise ExpressionError("INVALID_TYPED_REFERENCE", detail="reference is not a closed, nonempty typed reference")
    return (reference["kind"], reference["id"], reference["version"], reference.get("member_id", ""))

_DEFINITION_BINDING_TOKENS = {
    "owner_selector": "reference_definition_ref_KIND_ID_VERSION",
    "owner_resolution": "RESOLVE_ONE_SEMANTICS_AGAINST_THE_EXPLICIT_VERIFICATION_UNIVERSE_ARGUMENT",
    "member_selection": "EXACTLY_ONE_EQUAL_STRING_IN_THE_RESOLVED_SCHEMA_OBJECT_REGISTERED_members",
    "definition_target": "THE_SELECTED_MEMBER_BINDING_POINTER_IN_THE_SAME_RESOLVED_SCHEMA_CONTENT",
    "definition_pointer_role": "DECLARED_EXPLICIT_PROJECTION_OF_THE_MEMBER_BINDING_POINTER",
    "definition_pointer_equality": "EXACT_JSON_STRING_EQUALITY_TO_THE_MEMBER_BINDING_POINTER",
    "raw_local_defs_lookup_without_registration": "FORBIDDEN",
    "binding_phase": "BEFORE_OWNER_SELECTION;EVERY_DECLARED_DEFINITION_REF_IN_ARRAY_ORDER",
}


def _bind_declared_reference_definitions(universe: VerificationUniverse, model: Mapping[str, Any],
                                         registration_contract: Any) -> dict[tuple[str, str, str, str], str]:
    """reference-model.json:/reference_type/definition_binding, applied before owner selection.

    Each declared definition, in array order: the exact SCHEMA owner resolves in
    the explicit universe, its member_id is exactly one registered member (the
    RESOLVE_ONE rule, no $defs fallback), the declared definition_pointer equals
    the pointer constructed by the declared member binding, and that pointer
    resolves in the same resolved content. Any failure leaves the declared
    reference domain unbound and fails closed.
    """
    reference_type = model.get("reference_type")
    definitions = reference_type.get("definition_refs") if isinstance(reference_type, Mapping) else None
    declaration = reference_type.get("definition_binding") if isinstance(reference_type, Mapping) else None
    if not isinstance(definitions, list) or not isinstance(declaration, Mapping):
        _reference_domain_failure("typed-reference definition binding is not declared")
    binding = getattr(registration_contract, "member_binding", None)
    failure = declaration.get("binding_failure")
    if (binding is None or declaration.get("binding_ref") != binding.binding_ref
            or declaration.get("required_owner_kind") != binding.owner_kind
            or declaration.get("member_id_required") is not True
            or any(declaration.get(name) != token for name, token in _DEFINITION_BINDING_TOKENS.items())
            or failure != {"primitive_id": "ENUMERATE_TYPED_REFERENCES", "error_class": "REFERENCE_DOMAIN_UNDERDETERMINED", "fail_closed": True}):
        _reference_domain_failure("unsupported typed-reference definition binding declaration")
    if declaration.get("bound_definition_count") != len(definitions):
        _reference_domain_failure("declared bound-definition count differs from the declared definitions")
    bound: dict[tuple[str, str, str, str], str] = {}
    for index, entry in enumerate(definitions):
        where = f"/reference_type/definition_refs/{index}"
        if not isinstance(entry, Mapping) or set(entry) != {"reference_definition_ref", "definition_pointer"}:
            _reference_domain_failure("typed-reference definition row is malformed", where)
        ref = entry["reference_definition_ref"]
        try:
            key = _typed_reference_parts(ref, allow_member=True)
        except ExpressionError:
            _reference_domain_failure("typed-reference definition owner is not a typed reference", where)
        if key[0] != binding.owner_kind or not key[3]:
            _reference_domain_failure("typed-reference definition is not a registered SCHEMA member reference", where)
        if key in bound:
            _reference_domain_failure("typed-reference definition is declared twice", where)
        try:
            owner = universe.resolve(ref)
        except ExpressionError as exc:
            _reference_domain_failure(f"typed-reference definition does not resolve to a registered member ({exc.error_class})", where)
        constructed = binding.pointer(key[3])
        if entry["definition_pointer"] != constructed:
            _reference_domain_failure("definition_pointer differs from the registered member binding pointer", where)
        if not isinstance(binding.target(owner.content, key[3]), (dict, bool)):
            _reference_domain_failure("registered member binding pointer does not resolve", where)
        bound[key] = constructed
    return bound


def _reference_model_link(model: Mapping[str, Any], domain: Mapping[str, Any], name: str) -> Any:
    link = domain.get(name)
    if not isinstance(link, str) or ":" not in link:
        _reference_domain_failure(f"{name} is not a machine-readable model pointer")
    _, pointer = link.split(":", 1)
    if pointer and not pointer.startswith("/"):
        _reference_domain_failure(f"{name} is not an RFC6901 model pointer")
    try:
        return get_pointer(model, pointer)
    except ExpressionError as exc:
        raise ExpressionError("REFERENCE_DOMAIN_UNDERDETERMINED", pointer, exc.detail) from exc

def _reference_schema_document(universe: VerificationUniverse, schema_ref: Any,
                               registration_contract: Any = None) -> tuple[ResolvedObject, Any]:
    try:
        schema_object, applied_schema = _resolve_schema_object(universe, schema_ref, registration_contract)
    except ExpressionError as exc:
        if exc.error_class == "RESOLUTION_AMBIGUOUS":
            raise
        raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", exc.pointer, exc.detail) from exc
    if (schema_object.reference.get("kind") != "SCHEMA"
            or schema_object.origin != "CANDIDATE_UNIVERSE"
            or not isinstance(schema_object.content, dict)
            or schema_object.content.get("$schema") != DIALECT):
        raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA",
                              detail="selected producer schema is not a verified candidate Draft 2020-12 schema")
    return schema_object, applied_schema

def _route_instance_values(instance: Any, schema_root: Mapping[str, Any],
                           schema_pointer: str, definition_pointer: str, path_tokens: Any,
                           route_applications: Sequence[Mapping[str, Any]]) -> list[tuple[Any, str]]:
    if not isinstance(definition_pointer, str):
        _reference_domain_failure("typed-reference definition pointer is missing", schema_pointer)
    try:
        get_pointer(schema_root, definition_pointer)
    except ExpressionError as exc:
        raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", definition_pointer, exc.detail) from exc
    if not isinstance(path_tokens, list) or any(not isinstance(token, dict) for token in path_tokens):
        _reference_domain_failure("route instance_path_tokens is not an array")
    if not isinstance(route_applications, (list, tuple)) or not route_applications:
        _reference_domain_failure("producer schema has no applicator trace for its declared reference route",
                                  schema_pointer)
    try:
        for token in path_tokens:
            if not isinstance(token, dict) or not isinstance(token.get("kind"), str):
                _reference_domain_failure("route path token is malformed")
            kind = token["kind"]
            if kind in ("PROPERTY", "PATTERN_PROPERTY", "ARRAY_INDEX"):
                if set(token) != {"kind", "value"} or not isinstance(token.get("value"), str):
                    _reference_domain_failure(f"{kind} path token has no closed string value")
            elif kind in ("ADDITIONAL_PROPERTY", "ARRAY_ITEM"):
                if set(token) != {"kind"}:
                    _reference_domain_failure(f"{kind} path token has unexpected members")
            else:
                _reference_domain_failure(f"unsupported route path token {kind!r}")

        validator: Any = None

        def valid_at(pointer: Any, value: Any) -> bool:
            nonlocal validator
            if not isinstance(pointer, str):
                _reference_domain_failure("applicator trace lacks a schema pointer")
            try:
                subschema = get_pointer(schema_root, pointer)
                if validator is None:
                    validator = jsonschema.Draft202012Validator(schema_root, format_checker=_DATE_TIME_FORMAT_CHECKER)
                return validator.evolve(schema=subschema).is_valid(value)
            except ExpressionError:
                raise
            except Exception as exc:
                _reference_domain_failure(f"cannot evaluate Draft 2020-12 route applicability: {exc}", pointer)

        def unevaluated(keyword: str, parent_schema_pointer: Any, value: Any) -> set[Any]:
            nonlocal validator
            if not isinstance(parent_schema_pointer, str):
                _reference_domain_failure(f"{keyword} trace lacks its containing schema pointer")
            try:
                parent_schema = get_pointer(schema_root, parent_schema_pointer)
                if not isinstance(parent_schema, dict) or keyword not in parent_schema:
                    _reference_domain_failure(f"{keyword} trace does not identify its declared schema keyword",
                                              parent_schema_pointer)
                sibling_schema = {key: child for key, child in parent_schema.items() if key != keyword}
                if validator is None:
                    validator = jsonschema.Draft202012Validator(schema_root, format_checker=_DATE_TIME_FORMAT_CHECKER)
                from jsonschema._utils import (find_evaluated_item_indexes_by_schema,
                                               find_evaluated_property_keys_by_schema)
                if keyword == "unevaluatedProperties":
                    return set(find_evaluated_property_keys_by_schema(validator, value, sibling_schema))
                return set(find_evaluated_item_indexes_by_schema(validator, value, sibling_schema))
            except ExpressionError:
                raise
            except Exception as exc:
                _reference_domain_failure(f"cannot determine Draft 2020-12 {keyword} annotations: {exc}",
                                          parent_schema_pointer)

        output: list[tuple[Any, str]] = []

        def apply_trace(application: Mapping[str, Any]) -> None:
            steps = application.get("steps")
            guards = application.get("guards")
            if not isinstance(steps, list) or not isinstance(guards, list):
                _reference_domain_failure("producer-schema applicator trace is malformed", schema_pointer)
            if jcs([step.get("token") for step in steps if isinstance(step, dict)]) != jcs(path_tokens):
                _reference_domain_failure("producer-schema trace differs from the declared instance path", schema_pointer)
            guards_by_step: dict[int, list[Mapping[str, Any]]] = {}
            for guard in guards:
                if not isinstance(guard, Mapping) or not isinstance(guard.get("at_step"), int):
                    _reference_domain_failure("producer-schema applicability guard is malformed", schema_pointer)
                guards_by_step.setdefault(guard["at_step"], []).append(guard)
            states: list[tuple[Any, list[str]]] = [(instance, [])]

            def filter_guards(position: int) -> None:
                nonlocal states, validator
                for guard in guards_by_step.get(position, []):
                    survivors: list[tuple[Any, list[str]]] = []
                    for current, path in states:
                        kind = guard.get("kind")
                        if kind == "DEPENDENT_PROPERTY_PRESENT":
                            trigger = guard.get("trigger")
                            applies = isinstance(current, dict) and isinstance(trigger, str) and trigger in current
                        elif kind in ("SCHEMA_BRANCH_VALID", "IF_CONDITION_RESULT"):
                            condition_pointer = guard.get("schema_pointer")
                            try:
                                schema_value = get_pointer(schema_root, condition_pointer)
                                if validator is None:
                                    validator = jsonschema.Draft202012Validator(schema_root, format_checker=_DATE_TIME_FORMAT_CHECKER)
                                is_valid = validator.evolve(schema=schema_value).is_valid(current)
                            except Exception as exc:
                                _reference_domain_failure(f"cannot evaluate schema-applicator guard: {exc}",
                                                          condition_pointer if isinstance(condition_pointer, str) else schema_pointer)
                            applies = is_valid is guard.get("expected_valid")
                        else:
                            _reference_domain_failure(f"unsupported route-applicability guard {kind!r}", schema_pointer)
                        if applies:
                            survivors.append((current, path))
                    states = survivors
                    if not states:
                        return

            for position, step in enumerate(steps):
                if not isinstance(step, Mapping) or not isinstance(step.get("token"), dict):
                    _reference_domain_failure("producer-schema applicator step is malformed", schema_pointer)
                filter_guards(position)
                if not states:
                    return
                token = step["token"]
                kind = token.get("kind")
                value = token.get("value")
                keyword = step.get("keyword")
                parent_schema_pointer = step.get("parent_schema_pointer")
                subschema_pointer = step.get("subschema_pointer")
                next_states: list[tuple[Any, list[str]]] = []
                if kind == "PROPERTY":
                    for current, path in states:
                        if isinstance(current, dict) and value in current:
                            next_states.append((current[value], path + [value]))
                elif kind == "PATTERN_PROPERTY":
                    if keyword != "patternProperties" or not isinstance(value, str):
                        _reference_domain_failure("PATTERN_PROPERTY trace does not match its schema applicator", schema_pointer)
                    try:
                        for current, path in states:
                            if isinstance(current, dict):
                                for key in sorted(current, key=lambda item: item.encode("utf-16-be")):
                                    if re.search(value, key):
                                        next_states.append((current[key], path + [key]))
                    except (re.error, UnicodeError) as exc:
                        _reference_domain_failure(f"unsupported JSON Schema pattern: {exc}")
                elif kind == "ADDITIONAL_PROPERTY":
                    if keyword not in ("additionalProperties", "unevaluatedProperties"):
                        _reference_domain_failure("ADDITIONAL_PROPERTY trace does not name a property applicator", schema_pointer)
                    parent_schema = get_pointer(schema_root, parent_schema_pointer)
                    if not isinstance(parent_schema, dict):
                        _reference_domain_failure(f"{keyword} parent is not a schema object", parent_schema_pointer)
                    declared_properties = parent_schema.get("properties", {})
                    declared_patterns = parent_schema.get("patternProperties", {})
                    if not isinstance(declared_properties, dict) or not isinstance(declared_patterns, dict):
                        _reference_domain_failure(f"{keyword} sibling declarations are malformed", parent_schema_pointer)
                    for current, path in states:
                        if not isinstance(current, dict):
                            continue
                        already_evaluated = (unevaluated("unevaluatedProperties", parent_schema_pointer, current)
                                             if keyword == "unevaluatedProperties" else set())
                        try:
                            for key in sorted(current, key=lambda item: item.encode("utf-16-be")):
                                if keyword == "additionalProperties":
                                    pattern_match = any(re.search(pattern, key) for pattern in declared_patterns)
                                    selected = key not in declared_properties and not pattern_match
                                else:
                                    selected = key not in already_evaluated
                                if selected:
                                    if not valid_at(subschema_pointer, current[key]):
                                        _reference_domain_failure(f"owner property is not admitted by {keyword}",
                                                                  pointer_from_tokens(path + [key]))
                                    next_states.append((current[key], path + [key]))
                        except (re.error, UnicodeError) as exc:
                            _reference_domain_failure(f"unsupported JSON Schema pattern: {exc}")
                elif kind == "ARRAY_INDEX":
                    if not isinstance(value, str) or not re.fullmatch(r"0|[1-9][0-9]*", value):
                        _reference_domain_failure("ARRAY_INDEX is not a canonical decimal index")
                    index = int(value)
                    for current, path in states:
                        if isinstance(current, list) and index < len(current):
                            next_states.append((current[index], path + [value]))
                elif kind == "ARRAY_ITEM":
                    if keyword not in ("items", "contains", "unevaluatedItems"):
                        _reference_domain_failure("ARRAY_ITEM trace does not name an array applicator", schema_pointer)
                    parent_schema = get_pointer(schema_root, parent_schema_pointer)
                    if not isinstance(parent_schema, dict):
                        _reference_domain_failure(f"{keyword} parent is not a schema object", parent_schema_pointer)
                    for current, path in states:
                        if not isinstance(current, list):
                            continue
                        if keyword == "items":
                            prefix_items = parent_schema.get("prefixItems", [])
                            if not isinstance(prefix_items, list):
                                _reference_domain_failure("prefixItems sibling is not an array", parent_schema_pointer)
                            selected_indexes = range(len(prefix_items), len(current))
                        elif keyword == "contains":
                            selected_indexes = [index for index, item in enumerate(current)
                                                if valid_at(subschema_pointer, item)]
                        else:
                            already_evaluated = unevaluated("unevaluatedItems", parent_schema_pointer, current)
                            selected_indexes = [index for index in range(len(current))
                                                if index not in already_evaluated]
                            for index in selected_indexes:
                                if not valid_at(subschema_pointer, current[index]):
                                    _reference_domain_failure("owner array item is not admitted by unevaluatedItems",
                                                              pointer_from_tokens(path + [str(index)]))
                        next_states.extend((current[index], path + [str(index)])
                                           for index in selected_indexes if index < len(current))
                else:
                    _reference_domain_failure(f"unsupported route applicator token {kind!r}", schema_pointer)
                states = next_states
                if not states:
                    return
            filter_guards(len(steps))
            # A route only discovers candidates at its exact declared typed-reference
            # definition. Representation shape is checked later; it is not authority.
            output.extend((value, pointer_from_tokens(path)) for value, path in states
                          if valid_at(definition_pointer, value))

        for application in route_applications:
            if not isinstance(application, Mapping):
                _reference_domain_failure("producer-schema applicator trace is malformed", schema_pointer)
            apply_trace(application)
        unique: dict[str, Any] = {}
        for value, pointer in output:
            unique.setdefault(pointer, value)
        return [(value, pointer) for pointer, value in unique.items()]
    except ExpressionError:
        raise
    except Exception as exc:
        _reference_domain_failure(f"cannot apply reference route: {exc}")

def _schema_reference_route_paths(schema_root: Mapping[str, Any],
                                  declared_applicators: Any,
                                  expected_routes: Sequence[Mapping[str, Any]]) -> dict[tuple[str, bytes], list[dict[str, Any]]]:
    if not isinstance(declared_applicators, list) or any(not isinstance(item, str) for item in declared_applicators):
        _reference_domain_failure("schema applicator declaration is malformed")
    if not isinstance(expected_routes, (list, tuple)) or not expected_routes:
        _reference_domain_failure("producer-schema route declarations are missing")
    supported = set(declared_applicators)
    expected_paths: set[tuple[str, bytes]] = set()
    expected_instance_paths: list[list[dict[str, str]]] = []
    for route in expected_routes:
        if not isinstance(route, Mapping) or not isinstance(route.get("schema_pointer"), str):
            _reference_domain_failure("producer-schema route declaration is malformed")
        route_tokens = route.get("instance_path_tokens")
        if not isinstance(route_tokens, list) or any(not isinstance(token, dict) for token in route_tokens):
            _reference_domain_failure("producer-schema route instance path is malformed")
        expected_paths.add((route["schema_pointer"], jcs(route_tokens)))
        expected_instance_paths.append(route_tokens)
    paths: dict[tuple[str, bytes], list[dict[str, Any]]] = {}

    def follows_declared_path(instance_tokens: list[dict[str, str]]) -> bool:
        return any(len(instance_tokens) <= len(expected) and expected[:len(instance_tokens)] == instance_tokens
                   for expected in expected_instance_paths)

    # The producer-schema walk is depth-first. Each visit is a generator that yields the arguments of the visits it
    # makes next; the loop at the end resumes the innermost suspended visit first, so the order of every check, every
    # trace and every raised failure is exactly that of the recursive formulation, while a producer schema of any
    # nesting depth consumes no Python call-stack depth. The walk declares no traversal limit (neither depth nor node count).
    def walk(schema: Any, schema_tokens: list[str], instance_tokens: list[dict[str, str]],
             active_ref_states: set[tuple[str, bytes]],
             route_steps: list[dict[str, Any]], guards: list[dict[str, Any]]) -> Iterator[tuple[Any, ...]]:
        if not follows_declared_path(instance_tokens):
            return
        if isinstance(schema, bool):
            return
        if not isinstance(schema, dict):
            _reference_domain_failure("producer schema contains a non-schema applicator value",
                                      pointer_from_tokens(schema_tokens))
        current_pointer = pointer_from_tokens(schema_tokens)
        if "$dynamicRef" in schema:
            _reference_domain_failure("dynamic schema references are outside the declared reference model",
                                      current_pointer)
        if "$ref" in schema:
            if "$ref" not in supported:
                _reference_domain_failure("$ref schema applicator is not declared as supported", current_pointer)
            current_path = (current_pointer, jcs(instance_tokens))
            if current_path in expected_paths:
                trace = {"steps": copy.deepcopy(route_steps), "guards": copy.deepcopy(guards)}
                if jcs([step.get("token") for step in route_steps]) != current_path[1]:
                    _reference_domain_failure("schema applicator trace differs from its instance path", current_pointer)
                traces = paths.setdefault(current_path, [])
                if all(jcs(existing) != jcs(trace) for existing in traces):
                    traces.append(trace)
            reference = schema["$ref"]
            if not isinstance(reference, str) or not reference.startswith("#") or re.search(r"%(?![0-9A-Fa-f]{2})", reference[1:]):
                raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", current_pointer,
                                      "producer schema $ref is not a resolvable local fragment")
            try:
                target_pointer = urllib.parse.unquote(reference[1:], errors="strict")
                target_tokens = parse_pointer(target_pointer) if target_pointer else []
                normalized_target = pointer_from_tokens(target_tokens)
                target_schema = schema_root if not target_tokens else get_pointer(schema_root, normalized_target)
            except (UnicodeDecodeError, ExpressionError) as exc:
                raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", current_pointer,
                                      f"producer schema $ref cannot be resolved: {exc}") from exc
            ref_state = (normalized_target, jcs(instance_tokens))
            if ref_state not in active_ref_states:
                yield (target_schema, target_tokens, instance_tokens,
                       active_ref_states | {ref_state}, route_steps, guards)

        def walk_child(child: Any, keyword_tokens: list[str],
                       child_instance_tokens: list[dict[str, str]],
                       route_step: dict[str, Any] | None = None,
                       guard: dict[str, Any] | None = None) -> tuple[Any, ...]:
            child_steps = route_steps + ([route_step] if route_step is not None else [])
            child_guards = guards + ([guard] if guard is not None else [])
            return (child, schema_tokens + keyword_tokens, child_instance_tokens,
                    active_ref_states, child_steps, child_guards)

        for keyword in ("properties", "patternProperties"):
            mapping = schema.get(keyword)
            if mapping is not None:
                if keyword not in supported or not isinstance(mapping, dict):
                    _reference_domain_failure(f"unsupported or malformed {keyword} applicator", current_pointer)
                for name, child in mapping.items():
                    kind = "PROPERTY" if keyword == "properties" else "PATTERN_PROPERTY"
                    yield walk_child(child, [keyword, name],
                                     instance_tokens + [{"kind": kind, "value": name}],
                                     {"token": {"kind": kind, "value": name}, "keyword": keyword,
                                      "parent_schema_pointer": current_pointer,
                                      "subschema_pointer": pointer_from_tokens(schema_tokens + [keyword, name])})
        for keyword, kind in (("additionalProperties", "ADDITIONAL_PROPERTY"),
                              ("unevaluatedProperties", "ADDITIONAL_PROPERTY")):
            if keyword in schema:
                if keyword not in supported:
                    _reference_domain_failure(f"unsupported {keyword} applicator", current_pointer)
                yield walk_child(schema[keyword], [keyword], instance_tokens + [{"kind": kind}],
                                 {"token": {"kind": kind}, "keyword": keyword,
                                  "parent_schema_pointer": current_pointer,
                                  "subschema_pointer": pointer_from_tokens(schema_tokens + [keyword])})
        if "prefixItems" in schema:
            prefix = schema["prefixItems"]
            if "prefixItems" not in supported or not isinstance(prefix, list):
                _reference_domain_failure("unsupported or malformed prefixItems applicator", current_pointer)
            for index, child in enumerate(prefix):
                index_text = str(index)
                yield walk_child(child, ["prefixItems", index_text],
                                 instance_tokens + [{"kind": "ARRAY_INDEX", "value": index_text}],
                                 {"token": {"kind": "ARRAY_INDEX", "value": index_text},
                                  "keyword": "prefixItems", "parent_schema_pointer": current_pointer,
                                  "subschema_pointer": pointer_from_tokens(schema_tokens + ["prefixItems", index_text])})
        for keyword in ("items", "contains", "unevaluatedItems"):
            if keyword in schema:
                if keyword not in supported:
                    _reference_domain_failure(f"unsupported {keyword} applicator", current_pointer)
                yield walk_child(schema[keyword], [keyword], instance_tokens + [{"kind": "ARRAY_ITEM"}],
                                 {"token": {"kind": "ARRAY_ITEM"}, "keyword": keyword,
                                  "parent_schema_pointer": current_pointer,
                                  "subschema_pointer": pointer_from_tokens(schema_tokens + [keyword])})
        for keyword in ("allOf", "anyOf", "oneOf"):
            if keyword in schema:
                if keyword not in supported or not isinstance(schema[keyword], list):
                    _reference_domain_failure(f"unsupported or malformed {keyword} applicator", current_pointer)
                for index, child in enumerate(schema[keyword]):
                    guard = ({"kind": "SCHEMA_BRANCH_VALID", "at_step": len(route_steps),
                              "schema_pointer": pointer_from_tokens(schema_tokens + [keyword, str(index)]),
                              "expected_valid": True}
                             if keyword in ("anyOf", "oneOf") else None)
                    yield walk_child(child, [keyword, str(index)], instance_tokens, guard=guard)
        if any(keyword in schema for keyword in ("if", "then", "else")):
            if "if_then_else" not in supported:
                _reference_domain_failure("unsupported if/then/else applicator", current_pointer)
            for keyword in ("if", "then", "else"):
                if keyword in schema:
                    guard = ({"kind": "IF_CONDITION_RESULT", "at_step": len(route_steps),
                              "schema_pointer": pointer_from_tokens(schema_tokens + ["if"]),
                              "expected_valid": keyword != "else"}
                             if keyword in ("if", "then", "else") else None)
                    yield walk_child(schema[keyword], [keyword], instance_tokens, guard=guard)
        if "dependentSchemas" in schema:
            dependent = schema["dependentSchemas"]
            if "dependentSchemas" not in supported or not isinstance(dependent, dict):
                _reference_domain_failure("unsupported or malformed dependentSchemas applicator", current_pointer)
            for trigger, child in dependent.items():
                yield walk_child(child, ["dependentSchemas", trigger], instance_tokens,
                                 guard={"kind": "DEPENDENT_PROPERTY_PRESENT", "at_step": len(route_steps),
                                        "trigger": trigger})

    suspended = [walk(schema_root, [], [], set(), [], [])]
    while suspended:
        try:
            visit = next(suspended[-1])
        except StopIteration:
            suspended.pop()
            continue
        suspended.append(walk(*visit))
    return paths

def _enumerate_typed_references(universe: Any, registry_argument: Any,
                                reference_model_argument: Any, reference_form: Any,
                                registration_contract: Any = None) -> list[dict[str, Any]]:
    # ENUMERATE_TYPED_REFERENCES declares no traversal limit and no TRAVERSAL_RESOURCE_LIMIT error class
    # (reference-model.json:/enumeration/nested_reference_values is EMIT_EVERY_SCHEMA_ADMITTED_REFERENCE_VALUE_AT_ANY_
    # NESTING_DEPTH): max_json_traversal_depth and max_json_nodes_visited_per_value belong to DESCENDANTS / descendant_record
    # only (primitive-registry.json:/descendant_record/limits) and are not consumed here; no other frozen rule restricts the
    # node count of the enumeration.
    if not isinstance(universe, VerificationUniverse):
        raise ExpressionError("REFERENCE_DOMAIN_UNDERDETERMINED",
                              detail="ENUMERATE_TYPED_REFERENCES requires the exact verification universe")
    if reference_form not in ("BASE", "MEMBER"):
        _reference_domain_failure("reference_form must select BASE or MEMBER")
    for value, label in ((registry_argument, "registry"),
                         (reference_model_argument, "reference_model")):
        if not isinstance(value, BoundArgumentValue):
            _reference_domain_failure(f"{label} must retain resolved-object provenance")
        if value.object.origin != "CANDIDATE_UNIVERSE":
            _reference_domain_failure(f"{label} is not a candidate-universe object")
        try:
            resolved = universe.resolve(value.object.reference)
        except ExpressionError as exc:
            raise ExpressionError("REFERENCE_DOMAIN_UNDERDETERMINED", exc.pointer,
                                  f"{label} is not a unique verification-universe member: {exc.detail}") from exc
        if (resolved.origin != value.object.origin
                or resolved.registration != value.object.registration
                or resolved.raw_bytes != value.object.raw_bytes
                or resolved.content is not value.object.content):
            _reference_domain_failure(f"{label} provenance differs from its verification-universe member")
    registry = registry_argument.object.content
    model = reference_model_argument.object.content
    if not isinstance(registry, dict) or not isinstance(model, dict):
        _reference_domain_failure("registry and reference model must be JSON objects")
    owner_domain = model.get("typed_reference_owner_universe")
    enumeration = model.get("enumeration")
    route_inventory = model.get("route_inventory")
    if not isinstance(owner_domain, dict) or not isinstance(enumeration, dict) or not isinstance(route_inventory, dict):
        _reference_domain_failure("reference model lacks its owner or route declarations")
    if enumeration.get("unsupported_schema_handling") != "FAIL_CLOSED_WITH_REFERENCE_DOMAIN_UNDERDETERMINED":
        _reference_domain_failure("unsupported schema behavior is not fail-closed")
    # Declared binding phase: every definition binds through its registered
    # SCHEMA member before any owner is selected or traversed.
    bound_definitions = _bind_declared_reference_definitions(universe, model, registration_contract)
    registry_owner_refs = _reference_model_link(model, owner_domain, "registry_owner_candidate_set_ref")
    schema_owner_refs = _reference_model_link(model, owner_domain, "schema_validation_subject_set_ref")
    bound_source_rows = _reference_model_link(model, owner_domain, "verified_bound_source_owner_set_ref")
    if not isinstance(registry_owner_refs, list) or not isinstance(schema_owner_refs, list) or not isinstance(bound_source_rows, list):
        _reference_domain_failure("declared owner sets are not arrays")
    registry_membership = owner_domain.get("registry_row_membership")
    kind_rows = owner_domain.get("declared_kind_roles")
    if not isinstance(registry_membership, dict) or not isinstance(kind_rows, list):
        _reference_domain_failure("owner membership or kind-role declaration is malformed")
    kind_roles: dict[str, dict[str, Any]] = {}
    for role in kind_rows:
        if not isinstance(role, dict) or not isinstance(role.get("declared_kind"), str):
            _reference_domain_failure("declared kind role is malformed")
        kind = role["declared_kind"]
        if kind in kind_roles:
            _reference_domain_failure(f"declared kind role {kind!r} is duplicated")
        kind_roles[kind] = role
    registry_rows = registry.get("objects")
    if not isinstance(registry_rows, list):
        _reference_domain_failure("registry objects is not an array")

    def exact_base_ref(value: Any) -> tuple[str, str, str, str]:
        parts = _typed_reference_parts(value, allow_member=False)
        return parts

    schema_subject_keys: set[tuple[str, str, str, str]] = set()
    for ref in schema_owner_refs:
        key = exact_base_ref(ref)
        if key in schema_subject_keys:
            _reference_domain_failure("schema validation subject is duplicated")
        schema_subject_keys.add(key)
        try:
            subject = universe.resolve(ref)
        except ExpressionError as exc:
            raise ExpressionError("RESOLUTION_NOT_FOUND" if exc.error_class == "RESOLUTION_NOT_FOUND"
                                  else "RESOLUTION_AMBIGUOUS", exc.pointer, exc.detail) from exc
        if subject.reference.get("kind") != "SCHEMA" or subject.origin != "CANDIDATE_UNIVERSE":
            _reference_domain_failure("schema validation subject is not a candidate schema object")

    selected_owners: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    schema_role_keys: set[tuple[str, str, str, str]] = set()
    for owner_ref in registry_owner_refs:
        owner_key = exact_base_ref(owner_ref)
        if owner_key in selected_owners:
            _reference_domain_failure("registry owner candidate is duplicated")
        try:
            owner = universe.resolve(owner_ref)
        except ExpressionError as exc:
            raise ExpressionError("RESOLUTION_NOT_FOUND" if exc.error_class == "RESOLUTION_NOT_FOUND"
                                  else "RESOLUTION_AMBIGUOUS", exc.pointer, exc.detail) from exc
        if owner.origin != "CANDIDATE_UNIVERSE":
            _reference_domain_failure("registry owner candidate is not a candidate-universe member")
        rows = [row for row in registry_rows
                if isinstance(row, dict) and row.get("reference") == owner_ref]
        if not rows:
            _reference_domain_failure("declared registry owner has no exact registry row")
        if len(rows) != 1:
            raise ExpressionError("RESOLUTION_AMBIGUOUS", detail="declared registry owner has multiple registry rows")
        row = rows[0]
        if row != owner.registration or row.get("kind") != owner.reference.get("kind"):
            _reference_domain_failure("registry row differs from the resolved owner registration")
        if (row.get("status") != registry_membership.get("status")
                or row.get("classification") != registry_membership.get("classification")):
            _reference_domain_failure("declared registry owner is not an active normative row")
        role = kind_roles.get(row.get("kind"))
        if role is None:
            _reference_domain_failure(f"registry kind {row.get('kind')!r} has no declared semantic role")
        is_schema_subject = role.get("schema_validation_subject") is True
        eligible = role.get("typed_reference_owner_eligible") is True
        if is_schema_subject:
            if eligible or owner_key not in schema_subject_keys:
                _reference_domain_failure("schema-language owner role conflicts with its declared validation subject")
            schema_role_keys.add(owner_key)
            continue
        if not eligible:
            if owner_key in schema_subject_keys:
                _reference_domain_failure("non-schema owner is unexpectedly declared as a schema validation subject")
            continue
        if role.get("semantic_role") != "INSTANCE_DOCUMENT" or owner_key in schema_subject_keys:
            _reference_domain_failure("eligible registry owner has a conflicting semantic role")
        selected_owners[owner_key] = {
            "owner": owner,
            "owner_ref": dict(owner_ref),
            "semantic_role": role.get("semantic_role"),
            "owner_origin": "ACTIVE_NORMATIVE_REGISTRY",
            "selection_source": "EXACT_ACTIVE_NORMATIVE_REGISTRY_ROW_SCHEMA_REF",
            "schema_ref": row.get("schema_ref"),
            "registration": row,
        }
    if schema_role_keys != schema_subject_keys:
        _reference_domain_failure("schema owner candidates do not exactly match schema validation subjects")

    for source_row in bound_source_rows:
        if not isinstance(source_row, dict):
            _reference_domain_failure("verified bound-source declaration is malformed")
        source_ref = source_row.get("reference")
        source_key = exact_base_ref(source_ref)
        if source_key in selected_owners:
            _reference_domain_failure("candidate and bound-source owner identities collide")
        if source_row.get("selection") != "EXACT_VERIFIED_ALLOWLIST_ENTRY":
            _reference_domain_failure("bound-source owner is not an exact verified allowlist entry")
        try:
            owner = universe.resolve(source_ref)
        except ExpressionError as exc:
            raise ExpressionError("RESOLUTION_NOT_FOUND" if exc.error_class == "RESOLUTION_NOT_FOUND"
                                  else "RESOLUTION_AMBIGUOUS", exc.pointer, exc.detail) from exc
        if owner.origin != "BOUND_SOURCE_UNIVERSE":
            _reference_domain_failure("bound-source owner is not a verified bound-source universe member")
        schema_ref = source_row.get("producer_schema_ref")
        if not isinstance(schema_ref, dict) or owner.registration.get("schema_ref") != schema_ref:
            raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA",
                                  detail="bound-source schema differs from its verified allowlist binding")
        selected_owners[source_key] = {
            "owner": owner,
            "owner_ref": dict(source_ref),
            "semantic_role": owner_domain.get("bound_source_semantic_role"),
            "owner_origin": "VERIFIED_BOUND_SOURCE",
            "selection_source": "EXACT_VERIFIED_BOUND_SOURCE_SCHEMA_REF",
            "schema_ref": schema_ref,
            "registration": owner.registration,
        }

    declared_routes = route_inventory.get("declared_routes")
    model_routes = model.get("producer_schema_routes")
    eligible_rows = route_inventory.get("eligible_owners")
    applications = route_inventory.get("effective_owner_route_applications")
    if not all(isinstance(value, list) for value in (declared_routes, model_routes, eligible_rows, applications)):
        _reference_domain_failure("route inventory is incomplete")
    if jcs(declared_routes) != jcs(model_routes):
        _reference_domain_failure("route inventory differs from the model's declared producer routes")
    if not isinstance(model.get("reference_type"), dict) or model["reference_type"].get("shape_alone_sufficient") is not False:
        _reference_domain_failure("typed-reference admission does not prohibit shape-only referencehood")
    representation = model.get("representation_validation")
    definitions = model["reference_type"].get("definition_refs")
    if not isinstance(representation, dict) or not isinstance(definitions, list):
        _reference_domain_failure("typed-reference definition or representation rules are malformed")

    eligible_by_key: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    for owner_key, selected in selected_owners.items():
        schema_ref = selected.get("schema_ref")
        if not isinstance(schema_ref, dict):
            raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA",
                                  detail=f"eligible owner {selected['owner_ref']!r} has no producer schema_ref")
        _typed_reference_parts(schema_ref, allow_member=True)
        schema_object, applied_schema = _reference_schema_document(universe, schema_ref, registration_contract)
        # Interpreter universes are constructed only after _validate_universe_objects
        # validates these exact resolved contents against their registered schemas.
        # The selector equality below preserves that producer/content pairing here.
        selected["schema_object"] = schema_object
        selected["applied_schema"] = applied_schema
        if owner_key in eligible_by_key:
            _reference_domain_failure("eligible owner identity is duplicated")
        eligible_by_key[owner_key] = selected

    actual_eligible: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    for row in eligible_rows:
        if not isinstance(row, dict):
            _reference_domain_failure("eligible owner route summary is malformed")
        key = exact_base_ref(row.get("owner_ref"))
        if key in actual_eligible:
            _reference_domain_failure("eligible owner route summary is duplicated")
        actual_eligible[key] = row
    if set(actual_eligible) != set(eligible_by_key):
        _reference_domain_failure("declared eligible-owner set differs from verified owner selection")

    expected_applications: list[dict[str, Any]] = []
    routes_by_schema: dict[bytes, list[tuple[int, dict[str, Any]]]] = {}
    for index, route in enumerate(declared_routes):
        if not isinstance(route, dict) or not isinstance(route.get("producer_schema_ref"), dict):
            _reference_domain_failure("declared producer route is malformed")
        _typed_reference_parts(route["producer_schema_ref"], allow_member=True)
        routes_by_schema.setdefault(jcs(route["producer_schema_ref"]), []).append((index, route))
    for owner_key, selected in eligible_by_key.items():
        owner_summary = actual_eligible[owner_key]
        schema_ref = selected["schema_ref"]
        expected_role = selected["semantic_role"]
        if (owner_summary.get("owner_origin") != selected["owner_origin"]
                or owner_summary.get("owner_semantic_role") != expected_role
                or owner_summary.get("producer_schema_selection_source") != selected["selection_source"]
                or owner_summary.get("producer_schema_ref") != schema_ref):
            _reference_domain_failure("eligible-owner route summary differs from exact producer-schema selection")
        owner_routes = routes_by_schema.get(jcs(schema_ref), [])
        if owner_summary.get("effective_route_count") != len(owner_routes):
            _reference_domain_failure("eligible-owner effective route count differs from its selected schema")
        for index, route in owner_routes:
            expected_applications.append({
                "owner_ref": selected["owner_ref"],
                "owner_origin": selected["owner_origin"],
                "producer_schema_ref": schema_ref,
                "declared_route_index": index,
                "schema_pointer": route.get("schema_pointer"),
                "instance_path_tokens": route.get("instance_path_tokens"),
                "reference_definition_ref": route.get("reference_definition_ref"),
            })
    actual_application_keys = sorted(jcs(row) for row in applications if isinstance(row, dict))
    expected_application_keys = sorted(jcs(row) for row in expected_applications)
    if actual_application_keys != expected_application_keys or len(applications) != len(expected_applications):
        _reference_domain_failure("effective owner route applications do not match the declared owner/schema product")
    route_counts = route_inventory.get("counts", {})
    if (not isinstance(route_counts, dict)
            or route_counts.get("declared_routes") != len(declared_routes)
            or route_counts.get("eligible_typed_reference_owners") != len(eligible_by_key)
            or route_counts.get("effective_owner_route_applications") != len(applications)):
        _reference_domain_failure("route inventory counts differ from the machine-readable declarations")
    owner_counts = owner_domain.get("counts", {})
    if (not isinstance(owner_counts, dict)
            or owner_counts.get("active_normative_registry_owner_candidates") != len(registry_owner_refs)
            or owner_counts.get("schema_language_artifact_validation_subjects") != len(schema_subject_keys)
            or owner_counts.get("eligible_active_normative_instance_registry_owners")
               != sum(1 for row in eligible_rows if isinstance(row, dict) and row.get("owner_origin") == "ACTIVE_NORMATIVE_REGISTRY")
            or owner_counts.get("eligible_verified_bound_source_owners")
               != sum(1 for row in eligible_rows if isinstance(row, dict) and row.get("owner_origin") == "VERIFIED_BOUND_SOURCE")
            or owner_counts.get("eligible_typed_reference_owners") != len(eligible_by_key)):
        _reference_domain_failure("typed-reference owner counts differ from the derived owner domain")

    def schema_ref_for_route(route: Mapping[str, Any], selected: Mapping[str, Any]) -> tuple[ResolvedObject, Mapping[str, Any]]:
        producer_ref = route.get("producer_schema_ref")
        if producer_ref != selected.get("schema_ref"):
            raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", detail="route producer schema differs from the selected owner schema")
        producer_object, _ = _reference_schema_document(universe, producer_ref, registration_contract)
        return producer_object, producer_object.content

    schema_route_paths_cache: dict[bytes, dict[tuple[str, bytes], list[dict[str, Any]]]] = {}

    def validate_route_definition(route: Mapping[str, Any], schema_root: Mapping[str, Any]) -> tuple[str, list[dict[str, Any]]]:
        route_ref = route.get("reference_definition_ref")
        matches = [entry for entry in definitions
                   if isinstance(entry, dict) and entry.get("reference_definition_ref") == route_ref]
        if len(matches) != 1:
            _reference_domain_failure("route does not name exactly one declared typed-reference definition")
        definition_parts = _typed_reference_parts(route_ref, allow_member=True)
        # The definition location is the registered member binding established
        # before owner selection; the stored pointer is never followed on its own.
        definition_pointer = bound_definitions.get(definition_parts)
        if definition_pointer is None:
            _reference_domain_failure("route definition is not a bound registered SCHEMA member")
        route_schema_parts = _typed_reference_parts(route.get("producer_schema_ref"), allow_member=True)
        if route_schema_parts[:3] != definition_parts[:3]:
            _reference_domain_failure("typed-reference definition is outside its producer-schema document")
        schema_pointer = route.get("schema_pointer")
        try:
            parse_pointer(schema_pointer)
            route_schema = get_pointer(schema_root, schema_pointer)
        except ExpressionError as exc:
            raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", schema_pointer if isinstance(schema_pointer, str) else "", exc.detail) from exc
        route_schema_key = jcs(route.get("producer_schema_ref"))
        schema_paths = schema_route_paths_cache.get(route_schema_key)
        if schema_paths is None:
            schema_paths = _schema_reference_route_paths(
                schema_root, enumeration.get("schema_applicators"),
                [row for _, row in routes_by_schema.get(route_schema_key, [])])
            schema_route_paths_cache[route_schema_key] = schema_paths
        route_path_key = (schema_pointer, jcs(route.get("instance_path_tokens")))
        if route_path_key not in schema_paths:
            _reference_domain_failure("route instance path is not reached through its producer-schema applicators")
        route_applications = schema_paths[route_path_key]
        if not isinstance(route_schema, dict) or not isinstance(route_schema.get("$ref"), str):
            _reference_domain_failure("route schema location does not declare a direct local $ref")
        reference = route_schema["$ref"]
        if not reference.startswith("#") or re.search(r"%(?![0-9A-Fa-f]{2})", reference[1:]):
            raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", schema_pointer,
                                  "route $ref is not a resolvable local fragment")
        try:
            target_pointer = urllib.parse.unquote(reference[1:], errors="strict")
            target = schema_root if target_pointer == "" else get_pointer(schema_root, target_pointer)
        except (UnicodeDecodeError, ExpressionError) as exc:
            raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", schema_pointer,
                                  f"route $ref does not resolve: {exc}") from exc
        if target_pointer != definition_pointer or not isinstance(target, (dict, bool)):
            _reference_domain_failure("route $ref does not target the declared typed-reference definition")
        return definition_pointer, route_applications

    route_applications_by_owner: dict[tuple[str, str, str, str], list[dict[str, Any]]] = {}
    for application in applications:
        if not isinstance(application, dict):
            _reference_domain_failure("effective owner route application is malformed")
        owner_key = exact_base_ref(application.get("owner_ref"))
        route_applications_by_owner.setdefault(owner_key, []).append(application)
    for rows in route_applications_by_owner.values():
        rows.sort(key=lambda row: row.get("declared_route_index", -1))

    discovered: list[tuple[tuple[bytes, bytes, bytes], int, int, dict[str, Any], tuple[Any, ...]]] = []
    for owner_key, selected in eligible_by_key.items():
        owner = selected["owner"]
        try:
            preorder_rows = _descendant_rows(owner.content, None, None)
        except ExpressionError as exc:
            if exc.error_class == "NON_JSON_VALUE":
                _reference_domain_failure(f"owner traversal cannot determine typed-reference order: {exc.detail}",
                                          exc.pointer)
            raise
        preorder = {row["pointer"]: index for index, row in enumerate(preorder_rows)}
        for application in route_applications_by_owner.get(owner_key, []):
            index = application["declared_route_index"]
            route = declared_routes[index]
            producer_object, schema_root = schema_ref_for_route(route, selected)
            if producer_object.reference.get("kind") != "SCHEMA":
                raise ExpressionError("UNRESOLVED_PRODUCER_SCHEMA", detail="route producer is not a schema object")
            definition_pointer, route_applications = validate_route_definition(route, schema_root)
            route_values = _route_instance_values(owner.content, schema_root,
                                                  route["schema_pointer"], definition_pointer,
                                                  route["instance_path_tokens"],
                                                  route_applications)
            for value, instance_pointer in route_values:
                if not isinstance(value, dict):
                    raise ExpressionError("INVALID_TYPED_REFERENCE", instance_pointer,
                                          "schema-admitted typed-reference value is not an object")
                reference_key = _typed_reference_parts(value, allow_member=True)
                keys = set(value)
                required = set(representation.get("required_keys", []))
                optional = set(representation.get("optional_keys", []))
                if (not required.issubset(keys) or keys - required - optional
                        or (not representation.get("member_id_nonempty", False) and "member_id" in value)
                        or any(not isinstance(value.get(name), str) or not value[name]
                               for name in required)
                        or ("member_id" in value and
                            (not isinstance(value["member_id"], str) or not value["member_id"]))):
                    raise ExpressionError("INVALID_TYPED_REFERENCE", instance_pointer,
                                          "schema-admitted reference fails the declared representation shape")
                if (reference_form == "BASE" and reference_key[3]) or (reference_form == "MEMBER" and not reference_key[3]):
                    continue
                if instance_pointer not in preorder:
                    _reference_domain_failure("route instance pointer is absent from the owner JSON tree", instance_pointer)
                record = {
                    "owner_ref": dict(selected["owner_ref"]),
                    "producer_schema_ref": dict(selected["schema_ref"]),
                    "schema_pointer": route["schema_pointer"],
                    "instance_pointer": instance_pointer,
                    "reference_form": reference_form,
                    "reference": dict(value),
                }
                edge = (owner_key, instance_pointer, reference_key[:3], reference_key[3])
                discovered.append((identity_utf16_key(selected["owner_ref"]),
                                   preorder[instance_pointer], index, record, edge))
    discovered.sort(key=lambda row: (row[0], row[1], row[2]))
    output: list[dict[str, Any]] = []
    emitted_edges: set[tuple[Any, ...]] = set()
    for _, _, _, record, edge in discovered:
        if edge in emitted_edges:
            continue
        emitted_edges.add(edge)
        output.append(record)
    return output

def _descendant_conformance_report(registry: Mapping[str, Any], resource_limits: Mapping[str, Any]) -> dict[str, Any]:
    # Reproduces every registered DESCENDANT_RECORD conformance vector with the normative
    # traversal and reports whether the closed declaration and the emitted records agree.
    failures: list[str] = []
    definition = registry.get("descendant_record") if isinstance(registry,dict) else None
    vectors = registry.get("descendant_conformance_vectors") if isinstance(registry,dict) else None
    max_depth = int(resource_limits.get("max_json_traversal_depth",256))
    max_nodes = int(resource_limits.get("max_json_nodes_visited_per_value",1_000_000))
    declaration_closed = False
    if not isinstance(definition,dict):
        failures.append("DESCENDANT_RECORD definition missing")
    elif not isinstance(vectors,list) or not vectors:
        failures.append("DESCENDANT_RECORD conformance vectors are missing")
    else:
        shape = definition.get("record_shape",{}) if isinstance(definition.get("record_shape"),dict) else {}
        fields = definition.get("fields",{}) if isinstance(definition.get("fields"),dict) else {}
        limits = definition.get("limits",{}) if isinstance(definition.get("limits"),dict) else {}
        emitted_order = list(_descendant_rows({},max_depth,max_nodes)[0].keys())
        ancestor_field = fields.get("ancestor_pointers",{}) if isinstance(fields.get("ancestor_pointers"),dict) else {}
        examples = ancestor_field.get("examples",{}) if isinstance(ancestor_field.get("examples"),dict) else {}
        member_field = fields.get("member_key",{}) if isinstance(fields.get("member_key"),dict) else {}
        value_field = fields.get("value_type",{}) if isinstance(fields.get("value_type"),dict) else {}
        declaration_closed = bool(
            definition.get("record_id")=="DESCENDANT_RECORD"
            and str(definition.get("record_version"))=="1"
            and definition.get("instance_schema_pointer")=="#/$defs/descendant_record_instance"
            and shape.get("closed") is True
            and shape.get("additional_properties") is False
            and shape.get("field_count")==len(emitted_order)
            and list(shape.get("field_order",[]))==emitted_order
            and sorted(fields)==sorted(emitted_order)
            and [fields[name].get("order") for name in emitted_order]==list(range(1,len(emitted_order)+1))
            and sorted(definition.get("error_behavior",{}).get("error_classes",[]))==["NON_JSON_VALUE","TRAVERSAL_RESOURCE_LIMIT"]
            and limits.get("max_depth_source")=="metacontract.resource_limits.max_json_traversal_depth"
            and limits.get("max_depth_baseline")==max_depth
            and limits.get("max_nodes_source")=="metacontract.resource_limits.max_json_nodes_visited_per_value"
            and limits.get("max_nodes_baseline")==max_nodes
            and limits.get("exceeded_error_class")=="TRAVERSAL_RESOURCE_LIMIT"
            and examples.get("root")==[""]
            and examples.get("top_level")==["","/x"]
            and examples.get("nested")==["","/x","/x/y"]
            and member_field.get("root_value","missing") is None
            and value_field.get("allowed_values")==["NULL","BOOLEAN","NUMBER","STRING","ARRAY","OBJECT"]
        )
        if not declaration_closed:
            failures.append("DESCENDANT_RECORD declaration is not closed against emitted records")
    vectors_reproduced = isinstance(vectors,list) and bool(vectors)
    if isinstance(vectors,list):
        for vector in vectors:
            if not isinstance(vector,dict):
                failures.append("conformance vector is not an object")
                vectors_reproduced = False
                continue
            vid = vector.get("vector_id","")
            try:
                actual = _descendant_rows(vector.get("input"),max_depth,max_nodes)
            except ExpressionError as exc:
                failures.append(f"{vid}: unexpected {exc.error_class}")
                vectors_reproduced = False
                continue
            if len(actual)!=vector.get("expected_record_count") or actual!=vector.get("expected_records"):
                failures.append(f"{vid}: emitted descendant records differ from the registered vector")
                vectors_reproduced = False
            for row in actual:
                chain = row["ancestor_pointers"]
                if not chain or chain[0]!="" or chain[-1]!=row["pointer"]:
                    failures.append(f"{vid}: {row['pointer']} ancestor_pointers is not an inclusive root-through-self chain")
                    vectors_reproduced = False
            probe = vector.get("ancestry_semantics_probe")
            if isinstance(probe,dict):
                observed = next((row["ancestor_pointers"] for row in actual if row["pointer"]==probe.get("probe_pointer")),None)
                if (probe.get("selected_semantics")!="INCLUSIVE_ROOT_THROUGH_SELF"
                        or observed!=probe.get("inclusive_expected_ancestor_pointers")
                        or observed!=probe.get("observed_ancestor_pointers")
                        or observed==probe.get("strict_expected_ancestor_pointers")):
                    failures.append(f"{vid}: inclusive versus strict ancestry probe did not resolve to inclusive")
                    vectors_reproduced = False
            exclusion = vector.get("exclusion_probe")
            if isinstance(exclusion,dict):
                excluded = exclusion.get("excluded_pointer")
                excluded_nodes = [row["pointer"] for row in actual if excluded in row["ancestor_pointers"]]
                included_nodes = [row["pointer"] for row in actual if excluded not in row["ancestor_pointers"]]
                if (exclusion.get("governing_token")!="EXACT_POINTER_EQUALITY_AGAINST_ANCESTOR_POINTERS"
                        or excluded_nodes!=exclusion.get("expected_excluded_node_pointers")
                        or included_nodes!=exclusion.get("expected_included_node_pointers")):
                    failures.append(f"{vid}: excluded-prefix governing token did not resolve by exact ancestor-pointer equality")
                    vectors_reproduced = False
    return {"declaration_closed":bool(declaration_closed),"vectors_reproduced":bool(vectors_reproduced),
            "vector_count":len(vectors) if isinstance(vectors,list) else 0,"failures":failures}

class Interpreter:
    def __init__(self, program: Program, args: Mapping[str, Any], procedure: Mapping[str, Any]):
        self.program = program
        self.args = args
        self.procedure = procedure
        limits = program.metacontract.get("resource_limits", {})
        self.max_depth = int(limits.get("max_expression_depth",64))
        self.max_json_depth = int(limits.get("max_json_traversal_depth",256))
        self.max_json_nodes = int(limits.get("max_json_nodes_visited_per_value",1000000))
        self.max_lexical_depth = int(limits.get("max_lexical_collection_nesting",32))
        self.nodes = 0
        self.max_runtime_steps = min(50_000_000, int(limits.get("max_ast_nodes_per_procedure",8192)) * int(limits.get("max_json_nodes_visited_per_value",1_000_000)))
        self.current_expr_path = ""
        self.scope_bindings_seen: set[str] = set()

    def eval(self, node: Any, scope: Mapping[str, Any] | None = None, depth: int = 0) -> Any:
        scope = scope or {}
        self.nodes += 1
        if depth > self.max_depth:
            raise ExpressionError("AST_RESOURCE_LIMIT", self.current_expr_path, "expression depth limit exceeded")
        if self.nodes > self.max_runtime_steps:
            raise ExpressionError("AST_RESOURCE_LIMIT", self.current_expr_path, "runtime expression-step limit exceeded")
        if not isinstance(node, dict):
            raise ExpressionError("INVALID_AST_NODE", self.current_expr_path, "expression must be a closed object")
        if "arg" in node:
            if set(node) != {"arg"} or node["arg"] not in self.args:
                raise ExpressionError("UNDECLARED_ARGUMENT", self.current_expr_path, str(node.get("arg")))
            return self.args[node["arg"]]
        if "item" in node:
            if set(node) != {"item"} or node["item"] not in scope:
                raise ExpressionError("UNBOUND_ITEM", self.current_expr_path, str(node.get("item")))
            return scope[node["item"]]
        if "literal" in node:
            if set(node) != {"literal"}:
                raise ExpressionError("INVALID_AST_NODE", self.current_expr_path, "literal expression has extra keys")
            return node["literal"]
        if "op" not in node or node["op"] not in self.program.primitives:
            raise ExpressionError("UNSUPPORTED_OPERATION", self.current_expr_path, str(node.get("op")))
        op = node["op"]
        if op == "RESOLVE_ONE":
            universe = self.eval(node["universe"], scope, depth+1)
            reference = self.eval(node["reference"], scope, depth+1)
            if not isinstance(universe, VerificationUniverse):
                raise ExpressionError("INVALID_UNIVERSE", detail="RESOLVE_ONE requires explicit verification_universe")
            try:
                return universe.resolve(reference)
            except ExpressionError as exc:
                if not hasattr(exc, "resolve_one_reference"):
                    exc.resolve_one_reference = reference
                raise
        if op == "GET":
            value = self.eval(node["value"], scope, depth+1)
            if isinstance(value, VerificationUniverse) and node["pointer"] == "/objects":
                return [TypedResolvedJSON(obj.json_view()) for obj in value.objects]
            return _erase_resolved_type(get_pointer(value, node["pointer"]))
        if op == "GET_KEY":
            obj = _json_view(self.eval(node["object"], scope, depth+1))
            key = _json_view(self.eval(node["key"], scope, depth+1))
            if not isinstance(obj, dict): raise ExpressionError("NOT_OBJECT", detail="GET_KEY object operand is not an object")
            if not isinstance(key, str): raise ExpressionError("NON_STRING_KEY", detail="GET_KEY key operand is not a string")
            if key not in obj: raise ExpressionError("MISSING_KEY", detail=f"missing key {key!r}")
            return obj[key]
        if op == "JSON_EQUAL":
            return _json_equal(self.eval(node["left"],scope,depth+1),
                               self.eval(node["right"],scope,depth+1))
        if op == "SET_EQUAL_STRICT":
            left = self.eval(node["left"],scope,depth+1); right = self.eval(node["right"],scope,depth+1)
            if not isinstance(left,list) or not isinstance(right,list): raise ExpressionError("NOT_ARRAY", detail="strict set equality requires arrays")
            lk = [jcs(x) for x in left]; rk = [jcs(x) for x in right]
            if len(set(lk)) != len(lk) or len(set(rk)) != len(rk): raise ExpressionError("DUPLICATE_SET_ITEM", detail="duplicate value in strict set input")
            return set(lk) == set(rk)
        if op == "UNIQUE_BY":
            array = self.eval(node["array"],scope,depth+1)
            if not isinstance(array,list): raise ExpressionError("NOT_ARRAY", detail="UNIQUE_BY requires array")
            pointers = node["pointers"]
            if not isinstance(pointers,list) or not pointers: raise ExpressionError("INVALID_POINTER", detail="UNIQUE_BY needs pointer tuple")
            seen: dict[bytes,int] = {}
            for index, element in enumerate(array):
                parts = [get_pointer(element,pointer) for pointer in pointers]
                key = jcs(parts)
                if key in seen: return False
                seen[key] = index
            return True
        if op == "FILTER":
            array = self.eval(node["array"],scope,depth+1)
            self._bind_scope(node["as"], depth)
            if not isinstance(array,list): raise ExpressionError("NOT_ARRAY", detail="FILTER requires array")
            out=[]
            for value in array:
                child=dict(scope); child[node["as"]]=value
                pred=self.eval(node["where"],child,depth+1)
                if not isinstance(pred,bool): raise ExpressionError("NON_BOOLEAN_PREDICATE", detail="FILTER predicate is not boolean")
                if pred: out.append(value)
            return out
        if op == "PROJECT":
            array = self.eval(node["array"],scope,depth+1)
            self._bind_scope(node["as"], depth)
            if not isinstance(array,list): raise ExpressionError("NOT_ARRAY", detail="PROJECT requires array")
            fields=node["fields"]
            if not isinstance(fields,dict) or not fields: raise ExpressionError("INVALID_PROJECTION", detail="PROJECT needs nonempty fields")
            out=[]
            for value in array:
                child=dict(scope); child[node["as"]]=value
                row={}
                for name, expression in fields.items():
                    if name in row: raise ExpressionError("DUPLICATE_PROJECTED_FIELD", detail=name)
                    row[name]=_erase_resolved_type(self.eval(expression,child,depth+1))
                out.append(row)
            return out
        if op == "COUNT":
            array=self.eval(node["array"],scope,depth+1)
            if not isinstance(array,list): raise ExpressionError("NOT_ARRAY", detail="COUNT requires array")
            return len(array)
        if op in ("ALL","ANY"):
            array=self.eval(node["array"],scope,depth+1)
            self._bind_scope(node["as"], depth)
            if not isinstance(array,list): raise ExpressionError("NOT_ARRAY", detail=f"{op} requires array")
            enumerated = isinstance(node["array"],dict) and node["array"].get("op")=="ENUMERATE_TYPED_REFERENCES"
            for value in array:
                child=dict(scope); child[node["as"]]=value
                try:
                    pred=self.eval(node["where"],child,depth+1)
                except ExpressionError as exc:
                    if enumerated and not hasattr(exc, "enumerated_occurrence"):
                        exc.enumerated_occurrence = value
                    raise
                if not isinstance(pred,bool): raise ExpressionError("NON_BOOLEAN_PREDICATE", detail=f"{op} predicate is not boolean")
                if op == "ALL" and not pred: return False
                if op == "ANY" and pred: return True
            return op == "ALL"
        if op == "NOT":
            value=self.eval(node["value"],scope,depth+1)
            if not isinstance(value,bool): raise ExpressionError("NON_BOOLEAN_OPERAND", detail="NOT operand is not boolean")
            return not value
        if op == "NUMERIC_COMPARE":
            left=self.eval(node["left"],scope,depth+1); right=self.eval(node["right"],scope,depth+1)
            return _compare(_numeric(left),node["comparator"],_numeric(right))
        if op == "RFC3339_COMPARE":
            left=_timestamp_seconds(self.eval(node["left"],scope,depth+1)); right=_timestamp_seconds(self.eval(node["right"],scope,depth+1))
            return _compare(left,node["comparator"],right)
        if op == "DURATION_SECONDS":
            start=_timestamp_seconds(self.eval(node["start"],scope,depth+1)); end=_timestamp_seconds(self.eval(node["end"],scope,depth+1))
            duration=end-start
            return int(duration) if duration == duration.to_integral_value() else duration
        if op == "SCHEMA_VALIDATE":
            schema=self.eval(node["schema"],scope,depth+1); instance=self.eval(node["instance"],scope,depth+1)
            return schema_valid(schema,instance,node["mode"])
        if op == "DIGEST_VERIFY":
            source=self.eval(node["value"],scope,depth+1)
            expected=self.eval(node["expected"],scope,depth+1)
            algorithm=self.eval(node["algorithm"],scope,depth+1)
            serialization=self.eval(node["serialization"],scope,depth+1)
            exclusions=self.eval(node["excluded_pointers"],scope,depth+1)
            return self._digest_verify(source,expected,algorithm,serialization,exclusions)
        if op == "DESCENDANTS":
            value=self.eval(node["value"],scope,depth+1)
            if isinstance(value,BoundArgumentValue): value=value.object.content
            return _descendant_rows(value,self.max_json_depth,self.max_json_nodes)
        if op == "ENUMERATE_TYPED_REFERENCES":
            universe=self.eval(node["universe"],scope,depth+1)
            registry=self.eval(node["registry"],scope,depth+1)
            reference_model=self.eval(node["reference_model"],scope,depth+1)
            reference_form=self.eval(node["reference_form"],scope,depth+1)
            return _enumerate_typed_references(
                universe, registry, reference_model, reference_form,
                self.program.inputs.registration_contract)
        raise ExpressionError("UNSUPPORTED_OPERATION", self.current_expr_path, op)

    def _bind_scope(self, name: Any, depth: int) -> None:
        if not isinstance(name,str) or not name:
            raise ExpressionError("INVALID_SCOPE", detail="scope name must be nonempty string")
        if depth > self.max_lexical_depth:
            raise ExpressionError("AST_RESOURCE_LIMIT", detail="lexical collection nesting limit exceeded")
        # StaticValidator proves the declaration is unique and properly scoped. Re-entry
        # of the same FILTER/ALL/ANY site for successive outer items is expected.

    def _digest_verify(self, source: Any, expected: Any, algorithm: Any, serialization: Any, exclusions: Any) -> bool:
        if isinstance(source, BoundArgumentValue): source = source.object.content
        typed_source = isinstance(source, (ResolvedObject, TypedResolvedJSON))
        public_source = source.json_view() if isinstance(source, ResolvedObject) else source
        resolved_schema = self.program.metacontract["runtime_representation"]["value_schemas"]["resolved_object"]
        is_resolved = typed_source and isinstance(public_source, dict) and not schema_errors(resolved_schema, public_source, "INSTANCE")
        def declared_raw_bytes() -> bytes:
            if not is_resolved:
                raise ExpressionError("RAW_BYTES_UNAVAILABLE", detail="raw digest requires a schema-valid RESOLVED_OBJECT value")
            encoded = public_source["raw_content_base64"]
            try:
                raw = base64.b64decode(encoded, validate=True)
            except (ValueError, binascii.Error) as exc:
                raise ExpressionError("RAW_BYTES_UNAVAILABLE", detail="invalid resolved-object base64") from exc
            if base64.b64encode(raw).decode("ascii") != encoded:
                raise ExpressionError("RAW_BYTES_UNAVAILABLE", detail="noncanonical resolved-object base64")
            return raw
        if not isinstance(expected,str): raise ExpressionError("INVALID_EXPECTED_DIGEST", detail="expected digest must be a string")
        if not isinstance(exclusions,list) or any(not isinstance(x,str) for x in exclusions): raise ExpressionError("INVALID_EXCLUSION_POINTER", detail="excluded_pointers must be a string array")
        if algorithm not in ("SHA-256","SHA-1"): raise ExpressionError("UNSUPPORTED_ALGORITHM", detail=str(algorithm))
        if serialization == "RFC8785_JCS":
            if algorithm != "SHA-256": raise ExpressionError("INVALID_ALGORITHM_SERIALIZATION_PAIR", detail="JCS mode requires SHA-256")
            value = public_source["content"] if is_resolved else public_source
            value = _copy_json_value(value)
            parsed = [parse_pointer(p) for p in exclusions]
            if len(set(tuple(p) for p in parsed)) != len(parsed): raise ExpressionError("DUPLICATE_OR_OVERLAPPING_EXCLUSION", detail="duplicate excluded pointer")
            for i,a in enumerate(parsed):
                for b in parsed[i+1:]:
                    if a == b[:len(a)] or b == a[:len(b)]: raise ExpressionError("DUPLICATE_OR_OVERLAPPING_EXCLUSION", detail="overlapping excluded pointers")
            for pointer in sorted(exclusions,key=lambda p:len(parse_pointer(p)),reverse=True): delete_pointer(value,pointer)
            actual = sha256(jcs(value))
        elif serialization == "RAW_BYTES":
            if algorithm != "SHA-256" or exclusions: raise ExpressionError("INVALID_ALGORITHM_SERIALIZATION_PAIR", detail="RAW_BYTES requires SHA-256 and no exclusions")
            actual = sha256(declared_raw_bytes())
        elif serialization == "GIT_BLOB_OBJECT":
            if algorithm != "SHA-1" or exclusions: raise ExpressionError("INVALID_ALGORITHM_SERIALIZATION_PAIR", detail="GIT_BLOB_OBJECT requires SHA-1 and no exclusions")
            actual = git_blob(declared_raw_bytes())
        else:
            raise ExpressionError("UNSUPPORTED_SERIALIZATION", detail=str(serialization))
        return actual == expected


def _terminal_args(node: Any) -> set[str]:
    out: set[str] = set()
    if isinstance(node,dict):
        if set(node)=={"arg"} and isinstance(node["arg"],str): out.add(node["arg"])
        for v in node.values(): out.update(_terminal_args(v))
    elif isinstance(node,list):
        for v in node: out.update(_terminal_args(v))
    return out


def _has_dynamic_source(node: Any, scopes: Mapping[str, str], arg_types: Mapping[str, str]) -> bool:
    """Recognize declared argument or active lexical-item expression roots."""
    if isinstance(node, dict):
        if set(node) == {"arg"}:
            return node.get("arg") in arg_types
        if set(node) == {"item"}:
            return node.get("item") in scopes
        if "literal" in node:
            return False
        return any(_has_dynamic_source(value, scopes, arg_types)
                   for key, value in node.items() if key != "op")
    if isinstance(node, list):
        return any(_has_dynamic_source(value, scopes, arg_types) for value in node)
    return False

def _ast_nodes(node: Any, path: str = "") -> Iterator[tuple[str,dict[str,Any]]]:
    if isinstance(node,dict):
        if "op" in node: yield path,node
        for k,v in node.items(): yield from _ast_nodes(v,path+"/"+str(k))
    elif isinstance(node,list):
        for i,v in enumerate(node): yield from _ast_nodes(v,path+f"/{i}")

def _compatible_type(expected: str, actual: str) -> bool:
    if actual in ("JSON",):
        # GET and JSON literals are dynamically narrowed by the primitive's runtime contract.
        return expected not in ("VERIFICATION_UNIVERSE","RESOLVED_OBJECT","SCOPE_NAME","RFC6901_POINTER","COMPARATOR")
    if expected == "FINITE_JSON":
        return actual not in ("RESOLVED_OBJECT","VERIFICATION_UNIVERSE")
    if expected in ("JSON","JSON_OR_RESOLVED_OBJECT","JSON_EXPRESSION","MODE_EXPRESSION"):
        return True
    if expected == "JSON_OBJECT": return actual in (
        "JSON_OBJECT","RESOLVED_OBJECT","TYPED_REFERENCE","BASE_TYPED_REFERENCE","INTEGRITY")
    if expected == "JSON_NUMBER": return actual in ("JSON_NUMBER","NONNEGATIVE_INTEGER","SIGNED_DECIMAL_SECONDS")
    if expected == "RFC3339_STRING": return actual in ("STRING","RFC3339_STRING")
    if expected == "JSON_SCHEMA": return actual in ("JSON_SCHEMA","JSON_OBJECT")
    if expected == "ARRAY<T>": return actual in ("ARRAY<JSON>","ARRAY<JSON_OBJECT>","ARRAY<DESCENDANT_RECORD>","ARRAY<RESOLVED_OBJECT>","ARRAY<STRING>","ARRAY<OBJECT{owner_ref:BASE_TYPED_REFERENCE,producer_schema_ref:TYPED_REFERENCE,schema_pointer:RFC6901_POINTER,instance_pointer:RFC6901_POINTER,reference_form:STRING,reference:TYPED_REFERENCE}>")
    if expected == "ARRAY<JSON>": return actual in ("ARRAY<JSON>","ARRAY<JSON_OBJECT>","ARRAY<RESOLVED_OBJECT>","ARRAY<STRING>","ARRAY<OBJECT{owner_ref:BASE_TYPED_REFERENCE,producer_schema_ref:TYPED_REFERENCE,schema_pointer:RFC6901_POINTER,instance_pointer:RFC6901_POINTER,reference_form:STRING,reference:TYPED_REFERENCE}>")
    if expected == "BOOLEAN_EXPRESSION": return actual == "BOOLEAN"
    return expected == actual

def _procedure_index(procedure_registry: Mapping[str,Any], procedure_id: str) -> int:
    rows=procedure_registry.get("procedures",[])
    matches=[index for index,row in enumerate(rows) if isinstance(row,dict) and row.get("procedure_id")==procedure_id]
    if len(matches)!=1:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_LOCATION","procedure_id":procedure_id,"match_count":len(matches)})
    return matches[0]

def _procedure_condition_pointer(procedure_registry: Mapping[str,Any], procedure_id: str, assertion_index: int, field: str="condition") -> str:
    procedure_index=_procedure_index(procedure_registry,procedure_id)
    return pointer_from_tokens(["procedures",str(procedure_index),"assertions",str(assertion_index),field])



# ---------------------------------------------------------------------------
# Execution program (only reached after every pre-execution stage has passed).
# ---------------------------------------------------------------------------
def _build_inputs(run: Run) -> CandidateInputs:
    id_member, version_member = PACKAGE_IDENTITY_MEMBERS
    declaration = PC["package_self_digest_declaration"]
    constants = {name: constraint["const"] for name, constraint in declaration["members_in_declared_order"] if "const" in constraint}
    trust_input = {"expected_package_id": run.trust["expected_package_id"], "expected_package_version": run.trust["expected_package_version"],
                   "expected_package_digest": run.trust["expected_package_digest"],
                   "digest_mode": {"mode": constants["class"], "algorithm": constants["algorithm"], "serialization": "RFC8785_JCS",
                                   "excluded_pointers": [declaration["pointer"] + "/digest"]}}
    wanted = {"id": run.trust["expected_package_id"], "version": run.trust["expected_package_version"],
              "digest": run.trust["expected_package_digest"]}
    actual = {"id": run.package[id_member], "version": run.package[version_member], "digest": run.package_digest}
    trust_result = {"status": "PASS", "code": run_trust_pass_code(run), "witness": {"stage": "EXACT_TRIPLE_MATCH", "expected": wanted, "actual": actual}}
    package_row = _entry_row(run, ENTRYPOINT_SPECS[0])
    registry_row = _entry_row(run, ENTRYPOINT_SPECS[1])
    inputs = CandidateInputs(
        run.root, package_row[1]["path"], registry_row[1]["path"], run.package, run.entries[ENTRYPOINT_SPECS[0]["argument"]]["raw"],
        run.registry, run.entries[ENTRYPOINT_SPECS[1]["argument"]]["raw"], run.profile, run.schema, run.schema_raw,
        trust_input, trust_result)
    inputs.candidate_objects = _candidate_resolved_objects(run)
    inputs.bound_source_objects = _bound_resolved_objects(run)
    inputs.universe = _full_universe(run)
    inputs.registration_contract = _ensure_registration_contract(run)
    inputs.metacontract = run.metacontract
    return inputs


def run_trust_pass_code(run: Run) -> str:
    return run.metacontract["result_contracts"]["trust_result"]["status"]["PASS"]


def _load_program(run: Run, inputs: CandidateInputs) -> Program:
    universe = inputs.universe
    assert universe is not None
    st = _static_context(run)
    meta = run.metacontract
    state = _projection_state(run)
    descriptor = state["descriptor"]
    projection = {"selected_procedure": state["selected"], "map_argument": descriptor["argument"],
                  "map_pointer": pointer_from_tokens(descriptor["pointer_tokens"]),
                  "map_reference": state["map_reference"], "baseline": state["baseline"]}
    inputs.pre_execution = {"status": "PASS", "stage": "PRE_EXECUTION", "code": "PRE_EXECUTION_COMPLETE",
                            "witness": {"operation": "VERIFY_AND_BIND_CANDIDATE", "candidate_object_count": len(inputs.candidate_objects),
                                        "bound_source_count": len(inputs.bound_source_objects)}}
    by_schema = {identity_tuple(x.reference): x.content for x in inputs.candidate_objects if x.reference["kind"] == "SCHEMA"}
    frozen = run.frozen_objects
    reserved_values: dict[str, Any] = {}
    for name, expectation in _reserved_expectations(run).items():
        kind = expectation["type"]
        if kind == "VERIFICATION_UNIVERSE":
            reserved_values[name] = universe
        elif kind == "EXTERNAL_ACCEPTANCE_PROFILE":
            reserved_values[name] = inputs.profile
        elif kind == "EXTERNAL_TRUST":
            reserved_values[name] = dict(inputs.trust_input)
        elif expectation.get("pin_ref"):
            reserved_values[name] = BoundArgumentValue(frozen[expectation["pin_ref"][1]])
    reserved_values["result_projection"] = {"descriptor": descriptor, **projection}
    procedures_by_id = {p.get("procedure_id"): p for p in st["procedures"] if isinstance(p, dict)}
    invariants_by_id = {x.get("invariant_id"): x for x in st["invariants"] if isinstance(x, dict)}
    primitives_by_id = {x.get("primitive_id"): x for x in st["primitives"] if isinstance(x, dict)}
    bindings_by_id = {x.get("invariant_id"): x for x in meta.get("procedure_bindings", []) if isinstance(x, dict)}
    return Program(inputs, inputs.package, inputs.object_registry, meta, st["primitives_document"], st["procedures_document"],
                   st["invariants_document"], st["rules_document"], by_schema, procedures_by_id, invariants_by_id, primitives_by_id,
                   bindings_by_id, reserved_values)


def _resolve_rule_binding(program: Program, spec: Mapping[str, Any], reference: Any, invariant_id: str) -> BoundArgumentValue:
    # PE-48 has already proven every binding site (kind, universe, eligibility, schema, exact source metadata);
    # here the bound object is only fetched from the declared universe.
    constraint = spec.get("source_constraint", {})
    eligible = (program.inputs.candidate_objects if constraint.get("universe") == "CANDIDATE_UNIVERSE"
                else program.inputs.bound_source_objects)
    matches = [obj for obj in eligible if identity_tuple(obj.reference) == identity_tuple(reference)]
    if len(matches) != 1:
        raise RuntimeError(f"binding of {spec.get('name')} escaped the pre-execution binding stage")
    return BoundArgumentValue(program.inputs.universe.resolve(reference))  # type: ignore[union-attr]

def _arguments_for_invocation(program: Program, invariant: Mapping[str, Any], procedure: Mapping[str, Any],
                              overrides: Mapping[str, Any] | None = None) -> dict[str, Any]:
    invariant_id=invariant.get("invariant_id")
    binding=program.bindings.get(invariant_id)
    if binding is None:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"RESOLVE_BINDINGS","invariant_id":invariant_id,"diagnostic":"no metacontract binding row"})
    defaults=invariant.get("default_arguments",{})
    declared_bindings=binding.get("rule_bindings",{})
    overrides=dict(overrides or {})
    unknown=set(overrides)-set(declared_bindings)
    if unknown:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"RESOLVE_BINDINGS","invariant_id":invariant_id,"diagnostic":"rule override names an undeclared argument","unknown":sorted(unknown)})
    effective=dict(defaults)
    effective.update(overrides)
    reserved_rows={x.get("name"):x for x in binding.get("reserved_bindings",[]) if isinstance(x,dict)}
    output:dict[str,Any]={}
    for spec in procedure.get("arguments",[]):
        name=spec.get("name")
        if spec.get("origin")=="RULE_BINDING":
            reference=effective.get(name)
            if reference is None:
                raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"RESOLVE_BINDINGS","invariant_id":invariant_id,"argument":name,"diagnostic":"required rule argument is missing"})
            output[name]=_resolve_rule_binding(program,spec,reference,str(invariant_id))
        else:
            declared=reserved_rows.get(name)
            value=program.reserved_values.get(name)
            if declared is None or value is None or declared.get("type")!=spec.get("type") or declared.get("origin")!=spec.get("origin"):
                raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"RESOLVE_RESERVED_BINDING","invariant_id":invariant_id,"argument":name,"diagnostic":"reserved binding origin/type/value is absent or mismatched"})
            output[name]=value
    if len(output)!=len(procedure.get("arguments",[])):
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"RESOLVE_BINDINGS","invariant_id":invariant_id,"diagnostic":"resolved argument set is not exact"})
    return output


def _sanitize(value: Any, depth: int = 0) -> Any:
    if depth > 64: return "<WITNESS_DEPTH_LIMIT>"
    if isinstance(value,BoundArgumentValue): return _sanitize(value.object.content,depth+1)
    if isinstance(value,ResolvedObject): return _sanitize(value.json_view(),depth+1)
    if isinstance(value,decimal.Decimal):
        if value == value.to_integral_value(): return int(value)
        return format(value,"f")
    if isinstance(value,dict): return {str(k):_sanitize(v,depth+1) for k,v in value.items()}
    if isinstance(value,(list,tuple)): return [_sanitize(v,depth+1) for v in value]
    if value is None or isinstance(value,(str,bool,int,float)): return value
    return str(value)


def _settlement_value(program: Program, procedure: Mapping[str,Any], arguments: Mapping[str,Any], status: str) -> str | None:
    projection=program.reserved_values["result_projection"]
    selected=projection["selected_procedure"]
    if procedure.get("procedure_id") != selected.get("procedure_id"):
        return None
    descriptor=projection["descriptor"]
    argument=descriptor["argument"]
    value=arguments.get(argument)
    expected_ref=projection["map_reference"]
    if not isinstance(value,BoundArgumentValue) or jcs(value.object.reference)!=jcs(expected_ref):
        raise GateError("RESULT_PROJECTION_INVALID", {"operation":"CHECK_INVOCATION_PROJECTION_BINDING","argument":argument,"expected_reference":expected_ref,"actual_reference":None if not isinstance(value,BoundArgumentValue) else dict(value.object.reference)})
    try: mapping=get_pointer(value,projection["map_pointer"])
    except ExpressionError as exc: raise GateError("RESULT_PROJECTION_INVALID", {"operation":"READ_INVOCATION_PROJECTION","argument":argument,"pointer":projection["map_pointer"],"diagnostic":exc.detail}) from exc
    expected=descriptor["expected_literals"]
    if not isinstance(mapping,dict) or len(mapping)!=descriptor["mapping_cardinality"] or jcs(mapping)!=jcs(expected):
        raise GateError("RESULT_PROJECTION_INVALID", {"operation":"COMPARE_INVOCATION_PROJECTION","argument":argument,"expected":expected,"actual":mapping})
    return mapping[status]


_GENERIC_WITNESS_OPERAND_TOKENS = {
    "source_expression":"THE_FAILING_ASSERTION_DECLARED_WITNESS_EXPRESSION_ONLY",
    "condition_expression_contributes":False,
    "union_with_condition_operands":False,
    "terminal":"ARGUMENT_TERMINAL",
    "path_construction":"MAXIMAL_ENCLOSING_LITERAL_GET_CHAIN_ROOTED_AT_THE_TERMINAL_COMPOSED_INNERMOST_POINTER_FIRST_INTO_ONE_RFC6901_POINTER",
    "bare_terminal_pointer":"",
    "intermediate_get_operands":False,
    "non_literal_get_pointer":"FAIL_CLOSED",
    "order":"FIRST_OCCURRENCE_PREORDER_OF_THE_DECLARED_WITNESS_EXPRESSION",
    "preorder_child_order":"DECLARED_OPERATOR_SLOT_ORDER_OF_metacontract:/runtime_representation/static_type_calculus/operator_rules/operators;NAMED_EXPRESSION_MAP_FIELD_NAMES_UTF16_CODE_UNIT_ASCENDING",
    "deduplication_key":["argument","pointer"],
    "deduplication":"KEEP_FIRST_OCCURRENCE",
    "post_deduplication_sort":False,
    "record_fields":["argument","pointer","identity"],
    "identity_sources":["BOUND_OBJECT_IDENTITY","OPERAND_ONLY_IDENTITY_DECLARATION"],
    "missing_identity":"FAIL_CLOSED",
}


def _generic_witness_gate(program: Program, instance_pointer: str, diagnostic: str) -> GateError:
    # The failing declared owner is the metacontract that carries the generic witness law.
    owner=program.inputs.universe.resolve(dict(program.package[PC["claim_artifacts"]["metacontract"]["package_member"]]))
    return GateError("SCHEMA_INVALID_BOUND_OBJECT", {"argument":"metacontract","object_role":"GENERIC_FAILURE_WITNESS_DECLARATION",
        "schema_ref":str(owner.registration.get("schema_ref",{}).get("id","")),"instance_pointer":instance_pointer,
        "failure_kind":"TYPE","diagnostic":diagnostic,"bound_identity":identity_object(owner.reference)})


def _generic_witness_declaration(program: Program) -> Mapping[str,Any]:
    declared=program.metacontract.get("failure_semantics",{}).get("generic_failure_witness")
    operands=declared.get("operands") if isinstance(declared,Mapping) else None
    if (not isinstance(operands,Mapping)
            or any(operands.get(name)!=token for name,token in _GENERIC_WITNESS_OPERAND_TOKENS.items())
            or not isinstance(declared.get("node_path"),Mapping)
            or not isinstance(declared.get("operand_only_identities"),list)):
        raise _generic_witness_gate(program,"/failure_semantics/generic_failure_witness","unsupported or absent generic failure witness declaration")
    return declared


def _generic_failure_node_path(program: Program, procedure_id: str, assertion_index: int) -> str:
    # metacontract:/failure_semantics/generic_failure_witness/node_path: an absolute
    # RFC6901 pointer into the procedure registry at the failing condition root.
    declared=_generic_witness_declaration(program)["node_path"]
    if (declared.get("pointer_standard")!="RFC6901" or declared.get("pointer_base")!="DOCUMENT_ROOT"
            or declared.get("index_encoding")!="CANONICAL_DECIMAL_ARRAY_INDEX_NO_LEADING_ZERO"
            or declared.get("target")!="THE_FAILING_ASSERTION_CONDITION_ROOT"):
        raise _generic_witness_gate(program,"/failure_semantics/generic_failure_witness","unsupported node_path declaration")
    tokens=[]
    for token in declared.get("reference_tokens",[]):
        source=token.get("source") if isinstance(token,Mapping) else None
        if source=="LITERAL" and isinstance(token.get("value"),str): tokens.append(token["value"])
        elif source=="PROCEDURE_INDEX": tokens.append(str(_procedure_index(program.procedure_registry,procedure_id)))
        elif source=="ASSERTION_INDEX": tokens.append(str(assertion_index))
        else:
            raise _generic_witness_gate(program,"/failure_semantics/generic_failure_witness","unsupported node_path token")
    return pointer_from_tokens(tokens)


def _declared_witness_operand_pairs(program: Program, expression: Any) -> list[tuple[str,str]]:
    """(argument, pointer) pairs of the declared witness in first-occurrence preorder."""
    slots={op:[(slot[0],slot[1]) for slot in rule["slots"]] for op,rule in program.metacontract["runtime_representation"]["static_type_calculus"]["operator_rules"]["operators"].items()}
    pairs:list[tuple[str,str]]=[]
    def rooted_chain(node: Any) -> tuple[str,str] | None:
        tokens:list[str]=[]; depth=0; current=node
        while isinstance(current,dict) and current.get("op")=="GET":
            if not isinstance(current.get("pointer"),str):
                raise _generic_witness_gate(program,"/failure_semantics/generic_failure_witness","non-literal GET pointer in a declared witness")
            tokens=parse_pointer(current["pointer"])+tokens
            depth+=1; current=current.get("value")
        if depth and isinstance(current,dict) and set(current)=={"arg"}:
            return current["arg"], pointer_from_tokens(tokens) if tokens else ""
        return None
    def visit(node: Any) -> None:
        if not isinstance(node,dict): return
        if set(node)=={"arg"}:
            pairs.append((node["arg"],"")); return
        if node.get("op")=="GET":
            rooted=rooted_chain(node)
            if rooted is not None:
                pairs.append(rooted); return
        if "op" not in node: return
        for slot,slot_type in slots.get(node["op"],[]):
            value=node.get(slot)
            if slot_type=="EXPRESSION":
                visit(value)
            elif slot_type=="NAMED_EXPRESSION_MAP" and isinstance(value,dict):
                for name in sorted(value,key=lambda key: key.encode("utf-16-be")): visit(value[name])
    visit(expression)
    ordered:list[tuple[str,str]]=[]
    for pair in pairs:
        if pair not in ordered: ordered.append(pair)
    return ordered


def _declared_witness_operands(program: Program, procedure: Mapping[str,Any], arguments: Mapping[str,Any], expression: Any) -> list[dict[str,Any]]:
    declared=_generic_witness_declaration(program)
    origins={row.get("name"):row.get("origin") for row in procedure.get("arguments",[])}
    only={row.get("argument"):row for row in declared["operand_only_identities"] if isinstance(row,Mapping)}
    rows=[]
    for name,pointer in _declared_witness_operand_pairs(program,expression):
        value=arguments.get(name)
        if origins.get(name)=="RULE_BINDING" and isinstance(value,BoundArgumentValue):
            identity=dict(identity_object(value.object.reference))
        elif name in only and only[name].get("argument_origin")==origins.get(name) and isinstance(only[name].get("identity"),Mapping):
            identity=dict(only[name]["identity"])
        else:
            raise _generic_witness_gate(program,"/failure_semantics/generic_failure_witness","witness operand has no declared identity source")
        rows.append({"argument":name,"pointer":pointer,"identity":identity})
    return rows


_RESOLUTION_FAILURE_OWNER_TOKENS = {
    "verified_bound_source_owner":"FIRST_FAILURE.owner_ref_JSON_EQUAL_TO_ANY_reference_model.bound_source_references[*].reference_BY_TYPED_REFERENCE_IDENTITY",
    "candidate_registry_owner":"FIRST_FAILURE.owner_ref_JSON_EQUAL_TO_REFERENCE_OF_AN_EXACT_ACTIVE_NORMATIVE_REGISTRY_ROW",
}
_RESOLUTION_FAILURE_FIELD_TOKENS = {
    "schema_ref":"FIRST_FAILING_ENUMERATED_OCCURRENCE.producer_schema_ref",
    "instance_pointer":"FIRST_FAILING_ENUMERATED_OCCURRENCE.instance_pointer",
    "failure_kind":"FIRST_FAILING_RESOLVE_ONE.failure_kind",
    "bound_identity":"FIRST_FAILING_ENUMERATED_OCCURRENCE.reference",
}


def _reference_resolution_failure_result(program: Program, procedure: Mapping[str,Any], assertion: Mapping[str,Any],
                                         arguments: Mapping[str,Any], error: ExpressionError, node_path: str) -> dict[str,Any] | None:
    """metacontract:/result_contracts/reference_resolution_failure when its declared trigger holds; otherwise None."""
    declared=program.metacontract.get("failure_semantics",{}).get("reference_resolution_failure")
    if not isinstance(declared,Mapping): return None
    if (procedure.get("procedure_id")!=declared.get("procedure_id") or assertion.get("assertion_id") not in declared.get("assertion_ids",[])
            or error.error_class!=declared.get("failure_kind")):
        return None
    occurrence=getattr(error,"enumerated_occurrence",None)
    reference=getattr(error,"resolve_one_reference",None)
    if not isinstance(occurrence,Mapping) or reference is None or jcs(_json_view(occurrence.get("reference")))!=jcs(_json_view(reference)):
        return None
    construction=declared.get("witness_construction",{})
    provenance=construction.get("field_provenance",{})
    if (construction.get("trigger")!="RESOLVE_ONE_FAILURE_KIND_EQUALS_RESOLUTION_NOT_FOUND_FOR_AN_ENUMERATED_TYPED_REFERENCE"
            or construction.get("owner_classification",{}).get("verified_bound_source_owner")!=_RESOLUTION_FAILURE_OWNER_TOKENS["verified_bound_source_owner"]
            or construction.get("owner_classification",{}).get("candidate_registry_owner")!=_RESOLUTION_FAILURE_OWNER_TOKENS["candidate_registry_owner"]
            or any(provenance.get(name)!=token for name,token in _RESOLUTION_FAILURE_FIELD_TOKENS.items())
            or declared.get("code")!=assertion.get("failure_code")):
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"REFERENCE_RESOLUTION_FAILURE_DECLARATION","diagnostic":"unsupported dedicated reference-resolution failure declaration"})
    owner=_json_view(occurrence.get("owner_ref"))
    model=arguments.get("reference_model"); registry=arguments.get("registry")
    model_content=model.object.content if isinstance(model,BoundArgumentValue) else None
    registry_content=registry.object.content if isinstance(registry,BoundArgumentValue) else None
    bound_refs=[row.get("reference") for row in (model_content or {}).get("bound_source_references",[]) if isinstance(row,Mapping)]
    candidate_refs=[row.get("reference") for row in (registry_content or {}).get("objects",[])
                    if isinstance(row,Mapping) and row.get("status")=="ACTIVE" and row.get("classification")=="NORMATIVE"]
    owner_key=jcs(owner)
    if any(jcs(ref)==owner_key for ref in bound_refs if ref is not None):
        owner_class="verified_bound_source_owner"
    elif any(jcs(ref)==owner_key for ref in candidate_refs if ref is not None):
        owner_class="candidate_registry_owner"
    else:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"REFERENCE_RESOLUTION_FAILURE_OWNER","diagnostic":"failing occurrence owner is neither a bound-source nor a candidate registry owner"})
    witness={"argument":provenance["argument"][owner_class],"object_role":provenance["object_role"][owner_class],
             "schema_ref":_json_view(occurrence.get("producer_schema_ref")),"instance_pointer":occurrence.get("instance_pointer"),
             "failure_kind":error.error_class,"diagnostic":provenance["diagnostic"],"bound_identity":_json_view(occurrence.get("reference"))}
    return {"status":"FAIL","stage":declared["stage"],"code":declared["code"],"procedure_id":procedure.get("procedure_id"),
            "assertion_id":assertion.get("assertion_id"),"failure_kind":declared["failure_kind"],"witness":witness,
            "diagnostics":{"node_path":node_path,"detail":error.detail}}


_RESULT_CONTRACT_VALIDATORS: dict[tuple[int,str],Any] = {}


def _result_contract_errors(program: Program, contract_name: str, result: Any) -> list[str]:
    """Validate against the registered schema member named by metacontract:/result_contracts/<name>/schema_ref."""
    key=(id(program),contract_name)
    validator=_RESULT_CONTRACT_VALIDATORS.get(key)
    if validator is None:
        schema_ref=program.metacontract.get("result_contracts",{}).get(contract_name,{}).get("schema_ref")
        binding=getattr(program.inputs.registration_contract,"member_binding",None)
        if not isinstance(schema_ref,dict) or "member_id" not in schema_ref or binding is None:
            return [f"result contract {contract_name} does not name a registered schema member"]
        try:
            owner,member_schema=_resolve_schema_object(program.inputs.universe,dict(schema_ref),program.inputs.registration_contract)  # type: ignore[arg-type]
        except ExpressionError as exc:
            return [f"result contract {contract_name} schema member does not resolve ({exc.error_class})"]
        # The member is validated in place inside its registered parent document so
        # its local references resolve against that parent, as the member binding declares.
        parent_id=member_schema["$id"]
        registry=_ReferencingRegistry().with_resource(parent_id,_ReferencingResource.from_contents(owner.content,default_specification=_REFERENCING_DRAFT202012))
        validator=jsonschema.Draft202012Validator({"$schema":DIALECT,"$ref":parent_id+"#"+binding.pointer(schema_ref["member_id"])},registry=registry,format_checker=_DATE_TIME_FORMAT_CHECKER)
        _RESULT_CONTRACT_VALIDATORS[key]=validator
    return [error.message for error in validator.iter_errors(_json_view(result))]


def _trust_procedure_result(program: Program, procedure: Mapping[str,Any], status: str, code: str,
                            arguments: Mapping[str,Any], witness: Mapping[str,Any]) -> dict[str,Any]:
    if status=="PASS":
        trust=program.inputs.trust_result
        return {"status":"PASS","code":"EXPECTED_PACKAGE_VERIFIED","witness":trust["witness"]}
    return {"status":"FAIL","code":code,"witness":dict(witness)}

def _validate_emitted_result_shape(program: Program, result: Any, result_type: str, procedure_id: str) -> dict[str,Any]:
    # Every emitted procedure result is the registered result object itself and must
    # validate against the schema member its declared result contract names.
    contract_name = "trust_result" if result_type=="TRUST_RESULT" else "procedure_result"
    errors = _result_contract_errors(program, contract_name, result)
    if errors:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_CONTRACT","procedure_id":procedure_id,"result_contract":contract_name,"diagnostic":errors[0],"actual":_sanitize(result)})
    if not isinstance(result,dict) or result.get("status") not in ("PASS","FAIL") or (result_type!="TRUST_RESULT" and result.get("procedure_id")!=procedure_id) or not isinstance(result.get("witness"),dict):
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"result_type":result_type,"actual":_sanitize(result)})
    if result_type=="TRUST_RESULT":
        if not isinstance(result.get("code"),str) or not result["code"]:
            raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"diagnostic":"TRUST_RESULT requires a nonempty code"})
        if result["status"]=="PASS" and result["code"]!="EXPECTED_PACKAGE_VERIFIED":
            raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"diagnostic":"successful trust result has wrong code","code":result["code"]})
    elif result_type=="BOOLEAN":
        if result["status"]=="FAIL":
            if not isinstance(result.get("code"),str) or not result["code"] or not isinstance(result.get("assertion_id"),str):
                raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"diagnostic":"failed BOOLEAN result requires code and assertion_id"})
            if "node_path" in result:
                node_path=result.get("node_path")
                try:
                    get_pointer(program.procedure_registry,node_path)
                except (ExpressionError,TypeError) as exc:
                    raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_LOCATION","procedure_id":procedure_id,"node_path":node_path,"diagnostic":str(exc)}) from exc
        elif "code" in result:
            raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"diagnostic":"successful BOOLEAN result must not carry a failure code"})
    else:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"diagnostic":"undeclared procedure result type","result_type":result_type})
    if "result" in result and not isinstance(result["result"],str):
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"PROCEDURE_RESULT_SHAPE","procedure_id":procedure_id,"diagnostic":"settlement result projection must be a string"})
    return result


def _execute_procedure(program: Program, procedure: Mapping[str,Any], arguments: Mapping[str,Any]) -> dict[str,Any]:
    assertions=procedure.get("assertions",[])
    if not isinstance(assertions,list) or not assertions:
        raise GateError("SCHEMA_INVALID_BOUND_OBJECT", {"operation":"EXECUTE_PROCEDURE","procedure_id":procedure.get("procedure_id"),"diagnostic":"procedure must declare ordered assertions"})
    pid=procedure.get("procedure_id")
    result_type=procedure.get("result",{}).get("type")
    for index,assertion in enumerate(assertions):
        assertion_id=assertion.get("assertion_id")
        node_path=_generic_failure_node_path(program,pid,index)
        interpreter=Interpreter(program,arguments,procedure)
        interpreter.current_expr_path=node_path
        error:ExpressionError|None=None
        condition:Any=None
        try:
            condition=interpreter.eval(assertion.get("condition"))
            if not isinstance(condition,bool): raise ExpressionError("NON_BOOLEAN_ASSERTION","","assertion condition did not produce Boolean")
        except ExpressionError as exc:
            error=exc
        if error is not None or condition is not True:
            code=assertion.get("failure_code")
            if result_type=="TRUST_RESULT":
                # Dedicated trust_result contract: one witness per registered FAIL branch, no generic node_path or operands;
                # anything else fails the registered result contract closed.
                trust_input=program.inputs.trust_input
                expected={"id":trust_input.get("expected_package_id",""),"version":trust_input.get("expected_package_version","")}
                actual={"id":program.package.get("package_id",""),"version":program.package.get("package_version","")}
                trust_witness={"stage":"IDENTITY_COMPARISON","expected":expected,"actual":actual}
                if code=="TRUSTED_IDENTITY_MISMATCH":
                    trust_witness={"stage":"DIGEST_COMPARISON","expected":dict(expected,digest=trust_input.get("expected_package_digest","")),
                                   "actual":dict(actual,digest=program.inputs.trust_result.get("witness",{}).get("actual",{}).get("digest",""))}
                elif code=="MISSING_EXTERNAL_TRUST_INPUT":
                    trust_witness={"stage":"MISSING_EXPECTATION","missing_fields":[field for field in ("expected_package_id","expected_package_version","expected_package_digest") if not trust_input.get(field)]}
                return _validate_emitted_result_shape(program,_trust_procedure_result(program,procedure,"FAIL",code,arguments,trust_witness),result_type,pid)
            if error is not None:
                dedicated=_reference_resolution_failure_result(program,procedure,assertion,arguments,error,node_path)
                if dedicated is not None:
                    return _validate_emitted_result_shape(program,dedicated,result_type,pid)
            witness={"operands":_declared_witness_operands(program,procedure,arguments,assertion.get("witness")),"condition":"EVALUATION_ERROR" if error else "FALSE","expected":True}
            if error is not None:
                witness["error_class"]=error.error_class
                witness["actual"]={"pointer":error.pointer,"detail":error.detail}
            else:
                witness["actual"]=False
                try:
                    witness_interpreter=Interpreter(program,arguments,procedure)
                    witness_interpreter.current_expr_path=_procedure_condition_pointer(program.procedure_registry,pid,index,"witness")
                    witness["actual"]={"condition":False,"expression_witness":_sanitize(witness_interpreter.eval(assertion.get("witness")))}
                except ExpressionError as exc:
                    witness["actual"]={"condition":False,"witness_error":exc.error_class,"detail":exc.detail}
            projection_value=_settlement_value(program,procedure,arguments,"FAIL")
            result={"status":"FAIL","procedure_id":pid,"node_path":node_path,"assertion_id":assertion_id,"code":code,"witness":witness}
            if projection_value is not None: result["result"]=projection_value
            return _validate_emitted_result_shape(program,result,result_type,pid)
    if result_type=="TRUST_RESULT":
        return _validate_emitted_result_shape(program,_trust_procedure_result(program,procedure,"PASS","EXPECTED_PACKAGE_VERIFIED",arguments,{}),result_type,pid)
    projection_value=_settlement_value(program,procedure,arguments,"PASS")
    result={"status":"PASS","procedure_id":pid,"witness":{"assertions_evaluated":len(assertions)}}
    if projection_value is not None: result["result"]=projection_value
    return _validate_emitted_result_shape(program,result,result_type,pid)



def _evaluate_loaded_candidate(program: Program, run_mutations: bool = False) -> dict[str, Any]:
    inputs = program.inputs
    if run_mutations:
        print("[self-test] evaluating invariants in declared order", file=sys.stderr, flush=True)
    invariant_results = []
    all_pass = True
    projection_result = None
    selected_id = program.reserved_values["result_projection"]["selected_procedure"].get("procedure_id")
    for invariant in program.invariant_registry.get("invariants", []):
        procedure = program.procedures[invariant["procedure_id"]]
        arguments = _arguments_for_invocation(program, invariant, procedure)
        result = _execute_procedure(program, procedure, arguments)
        invariant_results.append({"invariant_id": invariant["invariant_id"], "procedure_id": procedure["procedure_id"], "result": result})
        all_pass = all_pass and result.get("status") == "PASS"
        if procedure.get("procedure_id") == selected_id:
            projection_result = result
    rule_results = []
    for rule in program.rule_registry.get("rules", []):
        binding = rule.get("invariant_binding")
        if not isinstance(binding, dict):
            continue
        invariant = program.invariants.get(binding.get("invariant_id"))
        procedure = program.procedures[invariant["procedure_id"]]
        arguments = _arguments_for_invocation(program, invariant, procedure, binding.get("arguments", {}))
        result = _execute_procedure(program, procedure, arguments)
        rule_results.append({"rule_id": rule["rule_id"], "invariant_id": invariant["invariant_id"],
                             "procedure_id": procedure["procedure_id"], "result": result})
        all_pass = all_pass and result.get("status") == "PASS"
    if projection_result is None or not isinstance(projection_result.get("result"), str):
        raise RuntimeError("the selected projection procedure did not produce a string result")
    return {"status": "PASS" if all_pass else "FAIL", "trust_result": inputs.trust_result,
            "candidate_identity": {"id": inputs.package.get(PACKAGE_IDENTITY_MEMBERS[0]), "version": inputs.package.get(PACKAGE_IDENTITY_MEMBERS[1]),
                                   "digest": inputs.trust_result.get("witness", {}).get("actual", {}).get("digest")},
            "pre_execution_status": "PASS", "candidate_objects": len(inputs.candidate_objects), "bound_sources": len(inputs.bound_source_objects),
            "procedure_definitions": len(program.procedures), "invariants": invariant_results, "bound_rules": rule_results,
            "result_projection": {"procedure_id": selected_id, "status": projection_result.get("status"), "outcome": projection_result.get("result")}}


def _init_run(args: argparse.Namespace) -> Run:
    run = Run(args)
    _LEAP_RUN[0], _LEAP_BOUND[0] = run, None  # the governed table is bound on every run during pre-execution
    run.root = Path(args.root) if _supplied(getattr(args, "root", None)) else None
    run.schema_id = getattr(args, "acceptance_profile_schema_id", None)
    run.schema_path = getattr(args, "acceptance_profile_schema", None)
    run.schema_sha = getattr(args, "acceptance_profile_schema_sha256", None)
    run.profile_path = getattr(args, "verification_input", None)
    run.trust = {name: run.caller_input(name) for name in _caller_inputs_at("PE-03")}
    return run


def _run_evaluation(args: argparse.Namespace, run_mutations: bool = False) -> dict[str, Any]:
    run = _init_run(args)
    try:
        _verify_pre_execution(run)
    except PreFail as fail:
        result, is_trust = _prefail_result(run, fail)
        return {"status": "FAIL", "trust_result": result} if is_trust else result
    program = _load_program(run, _build_inputs(run))
    return _evaluate_loaded_candidate(program, run_mutations)


def _selftest_args(repo_root: Path, profile_path: Path, digest: str | None = None) -> argparse.Namespace:
    package_path = repo_root / "docs/accord-02e4r5r4/specification-package-0.2.json"
    package = json.loads(package_path.read_text(encoding="utf-8"))
    schema_path = repo_root / "docs/accord-02e4r5r4/sources/external-acceptance-profile.schema.json"
    return argparse.Namespace(
        root=str(repo_root), candidate_package="docs/accord-02e4r5r4/specification-package-0.2.json",
        bootstrap_object_registry="docs/accord-02e4r5r4/object-registry.json",
        expected_package_id=package[PACKAGE_IDENTITY_MEMBERS[0]], expected_package_version=package[PACKAGE_IDENTITY_MEMBERS[1]],
        expected_package_digest=digest or package["current_candidate_integrity"]["digest"], verification_input=str(profile_path),
        acceptance_profile_schema_id=PROFILE_SCHEMA_ID, acceptance_profile_schema=str(schema_path),
        acceptance_profile_schema_sha256=sha256(schema_path.read_bytes()))


def _selftest_profile(repo_root: Path) -> dict[str, Any]:
    metacontract = json.loads((repo_root / "docs/accord-02e4r5r4/metacontract.json").read_text(encoding="utf-8"))
    sources = repo_root / "docs/accord-02e4r5r4/sources"
    frozen_files = {"frozen_r5r2_rules": "frozen-r5r2-rule-registry.json", "frozen_r5r3_v013_semantics": "frozen-r5r3-v013-governance.json"}
    accepted_files = {"PACKAGE": "accepted-base-package-0.1.json", "SOURCE_VECTOR_CATALOG": "accepted-vectors-0.1.json"}
    encode = lambda path: base64.b64encode((sources / path).read_bytes()).decode("ascii")
    allowlist = metacontract["accepted_source_allowlist"]
    return {"$schema": DIALECT, "$id": "urn:moirae:accord-02e4r5r4:external-acceptance-profile:1", "profile_id": "ACCORD-02E4R5R4-ACCEPTANCE-PROFILE",
            "profile_version": "1", "registry_membership": "FORBIDDEN_NOT_A_PACKAGE_OBJECT",
            "frozen_authority_pins": metacontract["external_authority_pins"],
            "frozen_authority_contents": {m: {"content_encoding": "BASE64_RAW_FILE_BYTES", "content_base64": encode(f)} for m, f in frozen_files.items()},
            "accepted_source_allowlist": allowlist,
            "accepted_source_contents": [{"ref": a["ref"], "canonical_path": a["canonical_path"], "git_blob": a["git_blob"],
                                          "content_encoding": "BASE64_RAW_FILE_BYTES", "content_base64": encode(accepted_files[a["ref"]["kind"]])}
                                         for a in allowlist],
            "authorized_result_projection_descriptor": metacontract["result_projection_authorization"]["descriptor"],
            "profile_is_caller_supplied_outside_candidate": True, "profile_is_immutable_for_run": True,
            "candidate_copies_are_authority": False, "candidate_registry_fallback": False}


def _init_catalog_run(repo_root: Path, profile_path: Path) -> Run:
    """Run state with the verified accepted sources only (self-test helper for the vector catalog)."""
    run = _init_run(_selftest_args(repo_root, profile_path))
    run.profile = json.loads(profile_path.read_text(encoding="utf-8"))
    run.accepted_content = {i: (base64.b64decode(row["content_base64"]), i) for i, row in enumerate(run.profile["accepted_source_contents"])}
    return run


def _self_test(repo_root: Path) -> dict[str, Any]:
    global _PROGRESS_ENABLED
    _PROGRESS_ENABLED = True
    profile_path = Path(tempfile.gettempdir()) / f"accord-r5r4-selftest-profile-{os.getpid()}.json"
    if profile_path.exists():
        raise AssertionError(f"refusing to overwrite pre-existing self-test path {profile_path}")
    profile_path.write_text(json.dumps(_selftest_profile(repo_root), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    try:
        result = _run_evaluation(_selftest_args(repo_root, profile_path), run_mutations=True)
        mismatch = _run_evaluation(_selftest_args(repo_root, profile_path, "0" * 64))
        registry = json.loads((repo_root / "docs/accord-02e4r5r4/primitive-registry.json").read_text(encoding="utf-8"))
        metacontract = json.loads((repo_root / "docs/accord-02e4r5r4/metacontract.json").read_text(encoding="utf-8"))
        closure = _descendant_conformance_report(registry, metacontract.get("resource_limits", {}))
        catalog = next((o.content for o in _bound_resolved_objects(_init_catalog_run(repo_root, profile_path)) if o.reference.get("kind") == "SOURCE_VECTOR_CATALOG"), {})
        vectors = catalog.get("vectors", []) if isinstance(catalog, dict) else []
        axes = next((v for v in vectors if v.get("vector_id") == "ACCORD-02C-V013-COMPLETE-NEGATIVE-EVIDENCE"), {}).get("expected", {})
        checks = {
            "external_trust_triple_passes": result.get("trust_result", {}).get("status") == "PASS"
                                            and result.get("trust_result", {}).get("code") == "EXPECTED_PACKAGE_VERIFIED",
            "all_invariants_and_rules_pass": all(row.get("result", {}).get("status") == "PASS"
                                                 for row in result.get("invariants", []) + result.get("bound_rules", [])),
            "v013_projection_is_expected": result.get("result_projection", {}).get("status") == "PASS"
                                           and result.get("result_projection", {}).get("outcome") == metacontract["result_projection_authorization"]["descriptor"]["expected_literals"]["PASS"],
            "primitive_count_19": len(registry.get("primitives", [])) == 19,
            "procedure_definition_count_39": result.get("procedure_definitions") == 39,
            "invariant_count_40": len(result.get("invariants", [])) == 40,
            "bound_rule_count_42": len(result.get("bound_rules", [])) == 42,
            "accepted_vector_count_23": len(vectors) == 23,
            "v013_expected_axis_count_13": len(axes) == 13,
            "external_trust_digest_mutation_rejected": mismatch.get("trust_result", {}).get("code") == "TRUSTED_IDENTITY_MISMATCH",
            "descendant_record_declaration_closed": closure["declaration_closed"],
            "descendant_conformance_vectors_reproduced": closure["vectors_reproduced"],
        }
        result["self_test_checks"] = checks
        result["self_test_failures"] = [name for name, passed in checks.items() if not passed]
        result["self_test"] = "PASS" if not result["self_test_failures"] else "FAIL"
        return result
    finally:
        profile_path.unlink(missing_ok=True)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Primary generic reference evaluator for an ACCORD-02E4R5R4 candidate.")
    parser.add_argument("--self-test", action="store_true", help="run the bundled baseline and focused checks")
    parser.add_argument("--root", help="explicit candidate root directory")
    parser.add_argument("--candidate-package", help="explicit candidate package JSON path, relative to root")
    parser.add_argument("--bootstrap-object-registry", help="explicit package-pinned object-registry JSON path, relative to root")
    for entry in PC["caller_input_precedence"]:
        name = entry["input_name"]
        parser.add_argument(name if name.startswith("--") else "--" + name.replace("_", "-"),
                            help=f"caller input {entry['contract_field']} ({entry['declared_by']})")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.self_test:
            repo_root = Path(args.root).resolve() if args.root else Path(__file__).resolve().parents[3]
            result = _self_test(repo_root)
        else:
            result = _run_evaluation(args)
        print(json.dumps(_sanitize(result), ensure_ascii=True, sort_keys=True, indent=2))
        if result.get("status") == "PASS" and result.get("self_test", "PASS") == "PASS":
            return 0
        return 2 if result.get("stage") == _STAGE or "trust_result" in result and result.get("status") == "FAIL" and "invariants" not in result else 1
    except Exception as exc:  # internal verifier error: never a registered normative result
        print(json.dumps({"status": "ERROR", "error_class": type(exc).__name__, "detail": str(exc)}, ensure_ascii=False, sort_keys=True, indent=2))
        return 3


if __name__ == "__main__":
    raise SystemExit(main())
